insert into public.mushroom_lookalikes_i18n (edible_slug,lookalike_slug,lang,visual_differences,smell_differences,habitat_differences,spore_print_differences,pro_tip,key_differences,verified) values 
('amanita_rubescens','amanita_franchetii','en','rubescens reddens at the flesh/bruised spots and has greyish-pink veil; franchetii does not redden and shows sulphur-yellow veil flakes plus a yellow-rimmed ring and yellow flocculose belts at the stem base.','Both inconspicuous-mushroomy; no reliable smell feature.','Both in warm broadleaf woodland; franchetii distinctly more thermophilic and rarer.','Both white spore print – no distinguishing feature.','Pressure test: the blusher (rubescens) ALWAYS reddens (cut/squeeze the flesh, wait a few minutes). If it stays whitish-yellow and the flakes are yellow, it is franchetii – leave it. Note: the panther cap (deadly) also belongs to this confusion group – beginners to mushroom inspection.','{"Blusher (rubescens): flesh and bruised spots REDDEN distinctly (wine-red), often reddish maggot tunnels – Franchet''s amanita (franchetii): flesh does NOT redden.","franchetii has yellow to sulphur-yellow veil flakes on the cap, a yellow-rimmed ring and yellowish flocculose belts at the stem base – rubescens has dirty-grey to reddish, NON-yellow veil remnants.","franchetii is poisonous/intolerable (strongly poisonous raw); rubescens only poisonous raw, edible when thoroughly cooked – when in doubt: no reddening + yellow flakes = do not eat.","franchetii looks like a ''small blusher without red'' – precisely the missing reddening plus the yellow flakes is the warning sign."}',false),
('amanita_rubescens','amanita_franchetii','es','rubescens enrojece en la carne/zonas de presion y tiene velo gris-rosado; franchetii no enrojece y muestra floculos del velo amarillo azufre mas un anillo de borde amarillo y cinturones floconosos amarillos en la base del pie.','Ambos discretos-fungicos; ningun caracter olfativo fiable.','Ambos en bosques de frondosas calidos; franchetii claramente mas termofilo y mas raro.','Ambos esporada blanca – ningun caracter distintivo.','Prueba de presion: la amanita rojiza/rubescente (rubescens) enrojece SIEMPRE (cortar/aplastar la carne, esperar unos minutos). Si permanece blanco-amarillenta y los floculos son amarillos, es franchetii – dejarla. Nota: la amanita pantera (mortal) tambien pertenece a este grupo de confusion – principiantes al control de setas.','{"Amanita rojiza (rubescens): la carne y las zonas de presion ENROJECEN claramente (rojo vinoso), a menudo galerias de larvas rojizas – Amanita de Franchet (franchetii): la carne NO enrojece.","franchetii tiene floculos del velo amarillos a amarillo azufre sobre el sombrero, anillo de borde amarillo y cinturones floconosos amarillentos en la base del pie – rubescens tiene restos del velo gris sucio a rojizo, NO amarillos.","franchetii es toxica/mal tolerada (fuertemente toxica cruda); rubescens solo toxica cruda, comestible bien cocida – en caso de duda: sin enrojecimiento + floculos amarillos = no comer.","franchetii parece una ''pequena amanita rojiza sin rojo'' – justamente la ausencia de enrojecimiento mas los floculos amarillos es la senal de advertencia."}',false),
('amanita_rubescens','amanita_franchetii','fr','rubescens rougit à la chair/aux points de pression et a un voile gris-rosé ; franchetii ne rougit pas et montre des flocons de voile jaune soufre plus un anneau bordé de jaune et des ceintures de flocons jaunes à la base du pied.','Les deux discrètes et fongiques ; pas de critère olfactif fiable.','Les deux dans les forêts de feuillus chaudes ; franchetii nettement plus thermophile et plus rare.','Les deux à sporée blanche – pas un critère distinctif.','Test de pression : l''amanite rougissante ROUGIT TOUJOURS (couper/presser la chair, attendre quelques minutes). Si cela reste blanc-jaunâtre et que les flocons sont jaunes, c''est franchetii – laisser sur place. Attention : l''amanite panthère (mortelle) appartient aussi à ce groupe de confusion – débutants au contrôle des champignons.','{"Amanite rougissante (rubescens) : chair et points de pression ROUGISSENT nettement (rouge vineux), souvent galeries de vers rougeâtres – Amanite à flocons jaunes/rugueuse (franchetii) : chair ne rougit PAS.","franchetii a des flocons de voile jaunes à jaune soufre sur le chapeau, un anneau bordé de jaune et des ceintures de flocons jaunâtres à la base du pied – rubescens a des restes de voile gris sale à rougeâtre, NON jaunes.","franchetii est toxique/mal tolérée (crue fortement toxique) ; rubescens seulement toxique crue, comestible bien cuite – en cas de doute : pas de rougissement + flocons jaunes = ne pas manger.","franchetii ressemble à une « petite amanite rougissante sans rouge » – c''est précisément l''absence de rougissement plus les flocons jaunes qui est l''avertissement."}',false),
('amanita_rubescens','amanita_franchetii','it','rubescens arrossa alla carne/nei punti di pressione e ha velo grigio-rosa; franchetii non arrossa e mostra fioccosita del velo giallo zolfo piu un anello bordato di giallo e cinture fioccose gialle alla base del gambo.','Entrambi inappariscenti-fungini; nessun carattere olfattivo affidabile.','Entrambi in boschi di latifoglie caldi; franchetii nettamente piu termofilo e piu raro.','Entrambi sporata bianca – nessun carattere distintivo.','Test di pressione: l''amanita rosseggiante (rubescens) arrossa SEMPRE (tagliare/schiacciare la carne, attendere alcuni minuti). Se rimane bianco-giallastra e le fioccosita sono gialle, e franchetii – lasciarla. Nota: anche l''amanita panterina (mortale) appartiene a questo gruppo di confusione – principianti al controllo dei funghi.','{"Amanita rosseggiante (rubescens): la carne e i punti di pressione ARROSSANO nettamente (rosso vinoso), spesso gallerie di larve rossastre – Amanita di Franchet (franchetii): la carne NON arrossa.","franchetii ha fioccosita del velo gialle a giallo zolfo sul cappello, anello bordato di giallo e cinture fioccose giallastre alla base del gambo – rubescens ha resti del velo grigio sporco a rossastro, NON gialli.","franchetii e tossica/mal tollerata (fortemente tossica da cruda); rubescens solo tossica da cruda, commestibile ben cotta – nel dubbio: nessun arrossamento + fioccosita gialle = non mangiare.","franchetii sembra una ''piccola amanita rosseggiante senza rosso'' – proprio l''assenza di arrossamento piu le fioccosita gialle e l''avvertimento."}',false),
('amanita_rubescens','amanita_porphyria','en','porphyria greyish-brown with a coppery-violet porphyry tone, grey veil remnants and a sharply rimmed bulb, no reddening; rubescens fleshy-brown-reddish with a clavate, non-rimmed bulb and distinct reddening.','porphyria distinctly musty of raw potatoes/potato sprouts; rubescens neutral-mushroomy.','porphyria mainly in coniferous woodland on acidic soil; rubescens more widely distributed in broadleaf and coniferous woodland.','Both white spore print (porphyria amyloid) – microscopic, no field feature.','The bulb and pressure test decide: sharply rimmed bulb + potato/radish smell + no reddening = porphyria, leave it. The blusher always reddens. When in doubt have it checked.','{"Grey veiled amanita / porphyry amanita (porphyria): sharply set-off, rimmed-bulbous stem base and coppery violet-greyish-brown (porphyry-coloured) cap tone, flesh does NOT redden – Blusher (rubescens): clavately thickened, NON-rimmed bulb, flesh and bruised spots REDDEN distinctly.","porphyria smells characteristically musty of raw potatoes/potato sprouts (radish/potato note) – rubescens inconspicuous-mushroomy.","porphyria contains bufotenine plus heat-stable gastrointestinal toxins and is classified as poisonous – do not eat; rubescens only poisonous raw, edible when thoroughly cooked.","Missing reddening + potato/radish smell + sharply rimmed bulb = porphyria, not the blusher."}',false),
('amanita_rubescens','amanita_porphyria','es','porphyria gris-parda con tono porfido cobrizo-violeta, restos del velo grises y bulbo de borde neto, sin enrojecimiento; rubescens pardo-carne-rojiza con bulbo claviforme no marginado y enrojecimiento claro.','porphyria claramente rancio a patatas crudas/brotes de patata; rubescens neutro-fungico.','porphyria sobre todo en bosques de coniferas en suelo acido; rubescens mas ampliamente distribuida en bosques de frondosas y coniferas.','Ambos esporada blanca (porphyria amiloide) – microscopica, en el campo ningun caracter.','El bulbo y la prueba de presion deciden: bulbo de borde neto + olor a patata/rabano + sin enrojecimiento = porphyria, dejarla. La amanita rojiza siempre enrojece. En caso de duda, hacerla revisar.','{"Amanita porfido (porphyria): base del pie con bulbo netamente marginado y sombrero de tono cobrizo violeta-gris-pardo (color porfido), la carne NO enrojece – Amanita rojiza (rubescens): bulbo claviforme engrosado, NO marginado, la carne y las zonas de presion ENROJECEN claramente.","porphyria huele de forma caracteristica rancio a patatas crudas/brotes de patata (nota rabano/patata) – rubescens discreto-fungico.","porphyria contiene bufotenina mas toxinas gastrointestinales termoestables y esta clasificada como toxica – no comer; rubescens solo toxica cruda, comestible bien cocida.","Ausencia de enrojecimiento + olor a patata/rabano + bulbo de borde neto = porphyria, no la amanita rojiza."}',false),
('amanita_rubescens','amanita_porphyria','fr','porphyria gris-brun avec une teinte porphyre cuivré-violacée, des restes de voile gris et un bulbe à bord marginé, pas de rougissement ; rubescens brun-chair-rougeâtre avec un bulbe en massue, non marginé, et un rougissement net.','porphyria nettement terne, de pommes de terre crues/germes de pommes de terre ; rubescens neutre-fongique.','porphyria principalement dans les forêts de conifères sur sol acide ; rubescens plus largement répandue dans les forêts de feuillus et de conifères.','Les deux à sporée blanche (porphyria amyloïde) – microscopique, pas de critère de séparation sur le terrain.','Le bulbe et le test de pression décident : bulbe nettement marginé + odeur de pomme de terre/radis + pas de rougissement = porphyria, laisser sur place. L''amanite rougissante rougit toujours. En cas de doute, au contrôle des champignons.','{"Amanite porphyre (porphyria) : base du pied bulbeuse, nettement marginée, et chapeau gris-brun violacé-cuivré (couleur porphyre), chair ne rougit PAS – Amanite rougissante (rubescens) : bulbe épaissi en massue, NON marginé, chair et points de pression ROUGISSENT nettement.","porphyria sent de façon caractéristique le terne, les pommes de terre crues/germes de pommes de terre (note radis/pomme de terre) – rubescens discrète-fongique.","porphyria contient de la bufoténine plus des poisons gastro-intestinaux thermostables et est classée toxique – ne pas manger ; rubescens seulement toxique crue, comestible bien cuite.","Absence de rougissement + odeur de pomme de terre/radis + bulbe nettement marginé = porphyria, pas l''amanite rougissante."}',false),
('amanita_rubescens','amanita_porphyria','it','porphyria grigio-bruna con tono porfido rame-violetto, resti del velo grigi e bulbo a bordo netto, senza arrossamento; rubescens bruno-carne-rossastra con bulbo claviforme non bordato e netto arrossamento.','porphyria nettamente smorto, odore di patate crude/germogli di patata; rubescens neutro-fungino.','porphyria soprattutto in boschi di conifere su suolo acido; rubescens piu ampiamente diffusa in boschi di latifoglie e conifere.','Entrambi sporata bianca (porphyria amiloide) – microscopica, sul campo nessun carattere.','Il bulbo e il test di pressione decidono: bulbo a bordo netto + odore di patata/ravanello + nessun arrossamento = porphyria, lasciarla. L''amanita rosseggiante arrossa sempre. Nel dubbio far controllare.','{"Amanita porfido (porphyria): base del gambo a bulbo nettamente bordato e cappello di tono rame violetto-grigio-bruno (color porfido), la carne NON arrossa – Amanita rosseggiante (rubescens): bulbo claviforme ingrossato, NON bordato, la carne e i punti di pressione ARROSSANO nettamente.","porphyria odora in modo caratteristico smorto di patate crude/germogli di patata (nota ravanello/patata) – rubescens inappariscente-fungino.","porphyria contiene bufotenina piu tossine gastrointestinali termostabili ed e classificata tossica – non mangiare; rubescens solo tossica da cruda, commestibile ben cotta.","Assenza di arrossamento + odore di patata/ravanello + bulbo a bordo netto = porphyria, non l''amanita rosseggiante."}',false),
('amanita_strobiliformis','amanita_echinocephala','en','echinocephala bears firm, pointed-pyramidal, NON-wipeable veil spines and tends to discolour dirty greenish-grey; strobiliformis has soft, fringed-tattered, wipeable veil flakes on a white-greyish-brownish cap, without a green tone.','echinocephala insignificant to faintly unpleasant; strobiliformis neutral with a slight radish note – smell alone is NOT a reliable feature.','Both thermophilic on calcareous soil in broadleaf woodland – habitat does not separate them, only the veil does.','Both white spore print – no distinguishing feature.','For any white, warty large amanita on lime: check the veil remnants – hard, non-wipeable pyramidal spines = hands off. The veil form can be washed out by weather – when in doubt ALWAYS have it checked (VAPKO).','{"Solitary lepidella / hedgehog amanita (echinocephala): pointed, pyramidal-spiny, NON-wipeable veil remnants on the cap – Warted amanita (strobiliformis): fringed-tattered, soft, wipeable veil flakes, NO hard pyramidal spines.","echinocephala smells insignificant to faintly unpleasant and often discolours dirty greenish-grey at the stem base and gills – strobiliformis smells neutral with a faint radish component, gills pure white to cream.","echinocephala is classified as (mildly) poisonous / gastrointestinally intolerable – to be safe, NEVER eat it.","Both whitish, large, warty and on calcareous soil – only the veil form (hard spines vs soft fringes) separates them reliably."}',false),
('amanita_strobiliformis','amanita_echinocephala','es','echinocephala lleva aguijones del velo firmes, puntiagudos y piramidales, NO eliminables al frotar, y tiende a colorearse de gris-verdoso sucio; strobiliformis lleva floculos del velo blandos, deshilachados-desgarrados, eliminables al frotar sobre un sombrero blanco-grisaceo-parduzco, sin tono verde.','echinocephala insignificante a debilmente desagradable; strobiliformis neutro con leve nota de rabano – el olor por si solo NO es un caracter seguro.','Ambos termofilos en suelo calcareo en bosque de frondosas – el habitat no los separa, solo el velo.','Ambos esporada blanca – ningun caracter distintivo.','Para cualquier amanita blanca, verrugosa y grande sobre caliza: examinar los restos del velo – aguijones piramidales duros y no eliminables al frotar = no tocar. La forma del velo puede estar deslavada por el tiempo – en caso de duda SIEMPRE hacerla revisar (VAPKO).','{"Amanita de cabeza espinosa (echinocephala): restos del velo puntiagudos, piramidales-espinosos, NO eliminables al frotar sobre el sombrero – Amanita deshilachada (strobiliformis): floculos del velo deshilachados-desgarrados, blandos, eliminables al frotar, NINGUN aguijon piramidal duro.","echinocephala huele insignificante a debilmente desagradable y a menudo se colorea de gris-verdoso sucio en la base del pie y las laminas – strobiliformis huele neutro con debil componente de rabano, laminas blanco puro a crema.","echinocephala esta clasificada como (debilmente) toxica / mal tolerada a nivel gastrointestinal – por seguridad, NUNCA consumirla.","Ambas blanquecinas, grandes, verrugosas y sobre suelo calcareo – solo la forma del velo (aguijones duros vs flecos blandos) las separa con seguridad."}',false),
('amanita_strobiliformis','amanita_echinocephala','fr','echinocephala porte des aiguillons de voile fermes, en pyramide pointue, non essuyables, et tend à se décolorer en gris-verdâtre sale ; strobiliformis présente des flocons de voile mous, frangés-déchiquetés, essuyables, sur un chapeau blanc-gris-brunâtre, sans teinte verte.','echinocephala insignifiante à faiblement désagréable ; strobiliformis neutre avec une légère note de radis – l''odeur seule n''est PAS un critère de séparation sûr.','Les deux thermophiles sur sol calcaire en forêt de feuillus – l''habitat ne sépare pas, seul le voile le fait.','Les deux à sporée blanche – pas un critère distinctif.','Pour toute amanite blanche et verruqueuse sur calcaire : vérifier les restes de voile – aiguillons pyramidaux durs, non essuyables = ne pas toucher. La forme du voile peut être délavée par les intempéries – en cas de doute, TOUJOURS au contrôle des champignons (VAPKO).','{"Amanite à tête échinée (echinocephala) : restes de voile en pyramide pointue et épineuse, NON essuyables sur le chapeau – Amanite à voile frangé (strobiliformis) : flocons de voile frangés-déchiquetés, mous, essuyables, AUCUN aiguillon pyramidal dur.","echinocephala sent l''insignifiant à faiblement désagréable et se décolore souvent en gris-verdâtre sale à la base du pied et aux lamelles – strobiliformis sent neutre avec une faible composante de radis, lamelles blanc pur à crème.","echinocephala est classée comme (faiblement) toxique / mal tolérée digestivement – par sécurité, ne JAMAIS la prendre comme comestible.","Les deux blanchâtres, grandes, verruqueuses et sur sol calcaire – seule la forme du voile (aiguillons durs vs. franges molles) les sépare sûrement."}',false),
('amanita_strobiliformis','amanita_echinocephala','it','echinocephala porta aculei del velo sodi, appuntiti e piramidali, NON asportabili, e tende a colorarsi di grigio-verde sporco; strobiliformis porta fioccosita del velo molli, sfrangiate-lacere, asportabili su cappello bianco-grigio-brunastro, senza tono verde.','echinocephala insignificante o debolmente sgradevole; strobiliformis neutro con leggera nota di ravanello – l''odore da solo NON e un carattere sicuro.','Entrambi termofili su suolo calcareo nel bosco di latifoglie – l''habitat non separa, solo il velo.','Entrambi sporata bianca – nessun carattere distintivo.','Per ogni grande amanita bianca e verrucosa su calcare: esaminare i resti del velo – aculei piramidali duri e non asportabili = non toccare. La forma del velo puo essere dilavata dal tempo – nel dubbio SEMPRE far controllare (VAPKO).','{"Amanita dalla testa spinosa (echinocephala): resti del velo appuntiti, piramidali-spinosi, NON asportabili sul cappello – Amanita sfrangiata (strobiliformis): fioccosita del velo sfrangiate-lacere, molli, asportabili, NESSUN aculeo piramidale duro.","echinocephala odora di insignificante o debolmente sgradevole e si colora spesso di grigio-verde sporco alla base del gambo e alle lamelle – strobiliformis odora neutro con debole componente di ravanello, lamelle bianco puro a crema.","echinocephala e classificata come (debolmente) tossica / mal tollerata a livello gastrointestinale – per sicurezza, MAI consumarla.","Entrambe biancastre, grandi, verrucose e su suolo calcareo – solo la forma del velo (aculei duri vs frange molli) le separa con sicurezza."}',false),
('amanita_strobiliformis','amanita_ovoidea','en','ovoidea: smooth-mealy white egg-shaped mushroom with a thick, yellowish to pale-orange tinged sac volva and a soon-disintegrating ring; strobiliformis with fringed-tattered veil flakes and a turnip-shaped bulb.','ovoidea with age carrion-like unpleasant; strobiliformis neutral with a slight radish note.','Both thermophilic on lime – habitat does not separate them, rather the veil and volva form.','Both white spore print – no distinguishing feature.','Never eat large white amanitas on lime as a beginner – the egg/warted amanita group borders the nephrotoxic A. proxima and deadly death caps. Always have it checked (VAPKO).','{"Egg amanita (ovoidea): when young purely egg-shaped-white, smooth to mealy-flocculose, with a thick, sac-like, yellowish to pale-orange tinged volva at the base and a soon-disintegrating membranous ring – Warted amanita (strobiliformis): fringed-tattered veil flakes on the cap, turnip-shaped bulb with an ephemeral sheath.","ovoidea''s veil leaves mealy-smooth remnants, the ring crumbles early – strobiliformis with distinctly fringed, tattered veil.","ovoidea with age has a carrion-like unpleasant smell; strobiliformis neutral with a faint radish note.","WARNING: ovoidea itself is considered edible, but because of confusion with the nephrotoxic ochre-sheathed egg amanita (A. proxima, volva remaining yellow-ochre) and deadly death caps, it is NEVER suitable for beginners.","Both large, white and lime-loving – the veil structure (fringed vs mealy-smooth with sac volva) is the main distinguishing feature."}',false),
('amanita_strobiliformis','amanita_ovoidea','es','ovoidea: hongo blanco en forma de huevo, liso-harinoso, con volva gruesa en saco, tenida de amarillento a naranja claro, y un anillo que se desintegra pronto; strobiliformis con floculos del velo deshilachados-desgarrados y un bulbo napiforme.','ovoidea con la edad olor desagradable a carrona; strobiliformis neutro con leve nota de rabano.','Ambos termofilos sobre caliza – el habitat no los separa, mas bien el velo y la forma de la volva.','Ambos esporada blanca – ningun caracter distintivo.','Nunca comer como principiante grandes amanitas blancas sobre caliza – el grupo de la amanita ovoide/deshilachada limita con A. proxima (nefrotoxica) y las amanitas mortales. Siempre hacerla revisar (VAPKO).','{"Amanita ovoide (ovoidea): de joven puramente ovoide-blanca, lisa a harinoso-floconosa, con volva gruesa, en saco, tenida de amarillento a naranja claro en la base y un anillo membranoso que se desintegra pronto – Amanita deshilachada (strobiliformis): floculos del velo deshilachados-desgarrados sobre el sombrero, bulbo napiforme con una vaina efimera.","El velo de ovoidea deja restos harinoso-lisos, el anillo se desmenuza pronto – strobiliformis con velo claramente deshilachado, desgarrado.","ovoidea con la edad tiene olor desagradable a carrona; strobiliformis neutro con debil nota de rabano.","ATENCION: ovoidea en si se considera comestible, pero por la confusion con la amanita ovoide de volva ocre nefrotoxica (A. proxima, volva que permanece amarillo-ocre) y las amanitas mortales, NUNCA es adecuada para principiantes.","Ambas grandes, blancas y calcicolas – la estructura del velo (deshilachada vs harinoso-lisa con volva en saco) es el caracter principal."}',false),
('amanita_strobiliformis','amanita_ovoidea','fr','ovoidea champignon blanc en forme d''œuf, lisse-farineux, avec une volve en sac épaisse teintée de jaunâtre à orange clair et un anneau se désagrégeant vite ; strobiliformis avec des flocons de voile frangés-déchiquetés et un bulbe napiforme.','ovoidea désagréable, cadavérique avec l''âge ; strobiliformis neutre avec une légère note de radis.','Les deux thermophiles sur calcaire – l''habitat ne sépare pas, plutôt le voile et la forme de la volve.','Les deux à sporée blanche – pas un critère distinctif.','Ne jamais manger les grandes amanites blanches sur calcaire en tant que débutant – le groupe autour de l''amanite ovoïde/à voile frangé jouxte A. proxima (toxique rénal) et les amanites phalloïdes mortelles. Toujours contrôle des champignons (VAPKO).','{"Amanite ovoïde (ovoidea) : jeune purement ovoïde-blanche, lisse à farineuse-floconneuse, avec une volve épaisse, en sac, teintée de jaunâtre à orange clair à la base et un anneau membraneux se désagrégeant vite – Amanite à voile frangé (strobiliformis) : flocons de voile frangés-déchiquetés sur le chapeau, bulbe napiforme avec une gaine éphémère.","Le voile d''ovoidea laisse des restes farineux-lisses, l''anneau s''effrite tôt – strobiliformis avec un voile nettement frangé, déchiqueté.","ovoidea avec l''âge a une odeur désagréable cadavérique ; strobiliformis neutre avec une faible note de radis.","ATTENTION : ovoidea elle-même est certes considérée comestible, mais à cause de la confusion avec l''amanite ovoïde à gaine ocre (A. proxima, volve restant jaune-ocre, toxique rénal) et les amanites phalloïdes mortelles, elle n''est JAMAIS adaptée aux débutants.","Les deux grandes, blanches et calcicoles – la structure du voile (frangé vs. farineux-lisse avec volve en sac) est le critère principal de séparation."}',false),
('amanita_strobiliformis','amanita_ovoidea','it','ovoidea: fungo bianco a forma di uovo, liscio-farinoso, con volva spessa a sacco, tinta di giallastro a arancio chiaro, e un anello che si disgrega presto; strobiliformis con fioccosita del velo sfrangiate-lacere e bulbo napiforme.','ovoidea con l''eta odore sgradevole di carogna; strobiliformis neutro con leggera nota di ravanello.','Entrambi termofili su calcare – l''habitat non separa, piuttosto il velo e la forma della volva.','Entrambi sporata bianca – nessun carattere distintivo.','Non mangiare mai da principianti grandi amanite bianche su calcare – il gruppo dell''amanita ovoide/sfrangiata confina con A. proxima (nefrotossica) e le amanite mortali. Sempre far controllare (VAPKO).','{"Amanita ovoidea (ovoidea): da giovane puramente ovoide-bianca, liscia a farinosa-fioccosa, con volva spessa, a sacco, tinta di giallastro a arancio chiaro alla base e un anello membranoso che si disgrega presto – Amanita sfrangiata (strobiliformis): fioccosita del velo sfrangiate-lacere sul cappello, bulbo napiforme con guaina effimera.","Il velo di ovoidea lascia resti farinoso-lisci, l''anello si sbriciola presto – strobiliformis con velo nettamente sfrangiato, lacero.","ovoidea con l''eta ha odore sgradevole di carogna; strobiliformis neutro con debole nota di ravanello.","ATTENZIONE: ovoidea stessa e considerata commestibile, ma a causa della confusione con l''amanita ovoide a volva ocra nefrotossica (A. proxima, volva che resta giallo-ocra) e le amanite mortali, NON e MAI adatta ai principianti.","Entrambe grandi, bianche e calcicole – la struttura del velo (sfrangiata vs farinosa-liscia con volva a sacco) e il carattere principale."}',false),
('amanita_vaginata','amanita_porphyria','en','vaginata ringless with a volva sheath and a strongly grooved cap margin; porphyria with a ring and a rimmed onion bulb, coppery violet-greyish-brown cap.','porphyria of raw potatoes/radish; vaginata odourless to mild.','porphyria prefers acidic coniferous woodland; vaginata in broadleaf and coniferous woodland.','Both white spore print – no field distinguishing feature.','Grisettes (ringless amanitas) NEVER have a ring. If you find a ring plus a rimmed bulb, it is a bulbed amanita – with a violet tone and potato smell, the poisonous porphyria. More importantly: ringless grey grisettes can be confused with deadly young death caps – always dig up the volva and bulb, when in doubt have it checked.','{"Grey grisette (vaginata): WITHOUT a ring/collar and with a membranous sheath (volva) at the non-bulbous base, cap margin distinctly grooved – Porphyry amanita (porphyria): with a pendent ring and a sharply rimmed, onion-shaped bulb (NO free sheath).","porphyria greyish-brown with a coppery-violet-porphyry tone and potato/radish smell – vaginata plainly grey, mild and without conspicuous smell.","vaginata stem ringless and slender; porphyria stem with a ring zone and a set-off bulb.","porphyria contains bufotenine and is poisonous; vaginata edible when thoroughly cooked (poisonous raw) – the presence of ring + bulb points to porphyria.","Rule of thumb: ring + rimmed bulb = not a grisette, but a bulbed amanita (here the poisonous porphyria)."}',false),
('amanita_vaginata','amanita_porphyria','es','vaginata sin anillo con vaina-volva y margen del sombrero fuertemente estriado; porphyria con anillo y bulbo en cebolla marginado, sombrero cobrizo violeta-gris-pardo.','porphyria a patatas crudas/rabano; vaginata inodora a suave.','porphyria prefiere bosques de coniferas acidos; vaginata en bosques de frondosas y coniferas.','Ambos esporada blanca – ningun caracter de campo.','Las amanitas con vaina (de tipo vaginata) NUNCA tienen anillo. Si encuentras un anillo mas un bulbo marginado, es una amanita con bulbo – con tono violeta y olor a patata, la toxica porphyria. Mas importante: las amanitas grises sin anillo pueden confundirse con jovenes amanitas mortales – siempre desenterrar la volva y el bulbo, en caso de duda hacerla revisar.','{"Amanita vaginata gris (vaginata): SIN anillo/manguito y con vaina membranosa (volva) en la base no bulbosa, margen del sombrero netamente estriado – Amanita porfido (porphyria): con anillo colgante y bulbo en cebolla netamente marginado (NINGUNA vaina libre).","porphyria gris-parda con tono cobrizo-violeta-porfido y olor a patata/rabano – vaginata simplemente gris, suave y sin olor llamativo.","Pie de vaginata sin anillo y esbelto; pie de porphyria con zona anular y bulbo diferenciado.","porphyria contiene bufotenina y es toxica; vaginata comestible bien cocida (toxica cruda) – la presencia de anillo + bulbo apunta a porphyria.","Regla: anillo + bulbo marginado = no una amanita con vaina, sino una amanita con bulbo (aqui la toxica porphyria)."}',false),
('amanita_vaginata','amanita_porphyria','fr','vaginata sans anneau avec une gaine volvaire et un bord de chapeau fortement strié ; porphyria avec anneau et bulbe oignon marginé, chapeau gris-brun violacé-cuivré.','porphyria de pommes de terre crues/radis ; vaginata inodore à douce.','porphyria préfère les forêts de conifères acides ; vaginata dans les forêts de feuillus et de conifères.','Les deux à sporée blanche – pas de critère distinctif sur le terrain.','Les amanites engainées n''ont JAMAIS d''anneau. Si tu trouves un anneau plus un bulbe marginé, c''est une amanite à bulbe – avec teinte violette et odeur de pomme de terre, la toxique porphyria. Plus important : les amanites engainées grises sans anneau peuvent être confondues avec de jeunes amanites phalloïdes mortelles – toujours déterrer la volve et le bulbe, en cas de doute contrôle des champignons.','{"Amanite vaginée grise (vaginata) : SANS anneau/manchette et avec une gaine membraneuse (volve) à la base non bulbeuse, bord du chapeau nettement strié – Amanite porphyre (porphyria) : avec anneau pendant et bulbe en oignon nettement marginé (AUCUNE gaine libre).","porphyria gris-brun avec une teinte porphyre violacé-cuivré et une odeur de pomme de terre/radis – vaginata simplement grise, douce et sans odeur marquante.","Pied de vaginata sans anneau et élancé ; pied de porphyria avec zone annulaire et bulbe distinct.","porphyria contient de la bufoténine et est toxique ; vaginata comestible bien cuite (toxique crue) – la présence d''anneau + bulbe indique porphyria.","Règle : anneau + bulbe marginé = pas une amanite engainée, mais une amanite à bulbe (ici la toxique porphyria)."}',false),
('amanita_vaginata','amanita_porphyria','it','vaginata senza anello con guaina-volva e margine del cappello fortemente striato; porphyria con anello e bulbo a cipolla bordato, cappello rame violetto-grigio-bruno.','porphyria odore di patate crude/ravanello; vaginata inodore a mite.','porphyria preferisce boschi di conifere acidi; vaginata in boschi di latifoglie e conifere.','Entrambi sporata bianca – nessun carattere sul campo.','Le amanite a guaina (vaginate) non hanno MAI un anello. Se trovi un anello piu un bulbo bordato, e un''amanita a bulbo – con tono violetto e odore di patata, la tossica porphyria. Piu importante: le amanite grigie senza anello possono essere confuse con giovani amanite mortali – sempre dissotterrare volva e bulbo, nel dubbio far controllare.','{"Amanita vaginata grigia (vaginata): SENZA anello/manicotto e con guaina membranosa (volva) alla base non bulbosa, margine del cappello nettamente striato – Amanita porfido (porphyria): con anello pendente e bulbo a cipolla a bordo netto (NESSUNA guaina libera).","porphyria grigio-bruna con tono rame-violetto-porfido e odore di patata/ravanello – vaginata semplicemente grigia, mite e senza odore marcato.","Gambo di vaginata senza anello e slanciato; gambo di porphyria con zona anulare e bulbo distinto.","porphyria contiene bufotenina ed e tossica; vaginata commestibile ben cotta (tossica da cruda) – la presenza di anello + bulbo indica porphyria.","Regola: anello + bulbo bordato = non un''amanita a guaina, ma un''amanita a bulbo (qui la tossica porphyria)."}',false),
('butterpilz','tricholoma_ustale','en','The slippery jack (Suillus luteus) has pores/tubes and a ring on the stem; T. ustale has gills that become rust-spotted, without a ring.','both inconspicuous/mild to faintly mealy - NOT a reliable distinguishing feature.','The slippery jack grows with pine, T. ustale in broadleaf woodland with beech/oak.','Slippery jack: olive-brown spore print (bolete); T. ustale: white (gilled mushroom).','Check the underside of the cap: tubes/pores = slippery jack/bolete, gills = tricholoma. Never take a gilled mushroom with a brown slimy cap as a slippery jack.','{"The slippery jack (edible) is a bolete with TUBES/PORES under the cap and usually a ring on the stem; the burnt knight (T. ustale) has GILLS and no ring.","The resemblance comes only from the brown, slimy-greasy cap seen from a distance - from above the T. ustale cap can recall a slippery jack.","The slippery jack''s cap cuticle peels off easily, tubes yellowish; T. ustale gills become rust-spotted.","The slippery jack grows in mycorrhiza with pine, T. ustale in broadleaf woodland.","Taste: slippery jack mild, T. ustale somewhat bitter."}',false),
('butterpilz','tricholoma_ustale','es','El boleto anillado (Suillus luteus) tiene tubos/poros y un anillo en el pie; T. ustale tiene laminas que se manchan de herrumbre, sin anillo.','ambos discretos/suaves a debilmente harinosos - NO es un caracter distintivo fiable.','El boleto anillado crece bajo pinos, T. ustale en bosque de frondosas bajo haya/roble.','Boleto anillado: esporada pardo-olivacea (boleto); T. ustale: esporada blanca (hongo laminado).','Comprobar la cara inferior del sombrero: tubos/poros = boleto anillado/boleto, laminas = tricoloma. Nunca recoger como boleto anillado un hongo laminado con sombrero pardo viscoso.','{"El boleto anillado (comestible) es un boleto con TUBOS/POROS bajo el sombrero y normalmente un anillo en el pie; el tricoloma quemado (T. ustale) tiene LAMINAS y ningun anillo.","La semejanza solo viene del sombrero pardo, viscoso-grasiento visto de lejos - desde arriba el sombrero de T. ustale puede recordar a un boleto anillado.","La cuticula del boleto anillado se pela facilmente, tubos amarillentos; las laminas de T. ustale se manchan de herrumbre.","El boleto anillado crece en micorriza con pino, T. ustale en bosque de frondosas.","Sabor: boleto anillado suave, T. ustale algo amargo."}',false),
('butterpilz','tricholoma_ustale','fr','Le bolet jaune (Suillus luteus) a des tubes et un anneau sur le pied; T. ustale a des lames qui se tachent de rouille, sans anneau.','les deux discrets/doux a faiblement farineux - ce n''est PAS un critere de distinction fiable.','Le bolet jaune pousse sous les pins, T. ustale en foret de feuillus sous hetre/chene.','Bolet jaune: sporee brun olive (bolet); T. ustale: sporee blanche (champignon a lames).','Verifiez le dessous du chapeau: tubes = bolet jaune/bolet, lames = tricholome. Ne jamais ramasser un champignon a lames avec chapeau brun visqueux comme bolet jaune.','{"Le bolet jaune (comestible) est un bolet avec des TUBES sous le chapeau et generalement un anneau au pied; le tricholome brule (T. ustale) a des LAMES et pas d''anneau.","La ressemblance ne vient que du chapeau brun, gluant-visqueux vu de loin - de dessus, le chapeau de T. ustale peut rappeler un bolet jaune.","La cuticule du bolet jaune se pele facilement, tubes jaunatres; les lames de T. ustale se tachent de rouille.","Le bolet jaune pousse en mycorhize sous les pins, T. ustale en foret de feuillus.","Saveur: bolet jaune doux, T. ustale un peu amer."}',false),
('butterpilz','tricholoma_ustale','it','Il boleto giallo (Suillus luteus) ha tubuli e un anello sul gambo; T. ustale ha lamelle che si macchiano di ruggine, senza anello.','entrambi inappariscenti/miti o debolmente farinosi - NON e un carattere distintivo affidabile.','Il boleto giallo cresce sotto i pini, T. ustale nel bosco di latifoglie sotto faggio/quercia.','Boleto giallo: sporata bruno-olivacea (boleto); T. ustale: sporata bianca (fungo a lamelle).','Controllare il sotto del cappello: tubuli = boleto giallo/boleto, lamelle = tricoloma. Mai raccogliere come boleto giallo un fungo a lamelle con cappello bruno vischioso.','{"Il boleto giallo (commestibile) e un boleto con TUBULI sotto il cappello e di solito un anello sul gambo; il tricoloma bruciato (T. ustale) ha LAMELLE e nessun anello.","La somiglianza nasce solo dal cappello bruno, viscido-vischioso visto da lontano - dall''alto il cappello di T. ustale puo ricordare un boleto giallo.","La cuticola del boleto giallo si pela facilmente, tubuli giallastri; le lamelle di T. ustale si macchiano di ruggine.","Il boleto giallo cresce in micorriza sotto i pini, T. ustale nel bosco di latifoglie.","Sapore: boleto giallo mite, T. ustale un po'' amaro."}',false),
('clavariadelphus_truncatus','ramaria_formosa','en','The truncate club (truncate Hercules'' club) is a single, apically truncate club; the beautiful coral (handsome clavaria) is repeatedly branched — the branching is the key feature.','Both inconspicuous to faintly mushroomy; smell does not separate them.','The Hercules'' club mainly in calcareous coniferous woodland; the beautiful coral rather in broadleaf woodland — a habitat difference, but not absolutely reliable.','Hercules'' club ochre-yellowish spore print, beautiful coral likewise ochrish — no practical distinguishing feature.','Only harvest unbranched, apically truncate clubs — as soon as a fungus branches shrub-like and/or tastes bitter, the poisonous beautiful coral threatens.','{"Truncate Hercules'' club: simple, unbranched club-shaped fruiting bodies with a flat-truncate, often slightly depressed apex; beautiful coral richly branched like a shrub.","Hercules'' club mostly yellow-ochre to orange-brown, solitary/clavate; beautiful coral orange-salmon with many yellow branch tips.","Hercules'' club tastes mild to sweetish; beautiful coral bitter and gastrointestinally poisonous.","Hercules'' club typically grows in lime-loving coniferous woodland (often spruce/fir); beautiful coral rather in broadleaf woodland.","The unbranched club form of the Hercules'' club rules out confusion on close inspection — confusion only happens fleetingly at young, coral-like stages."}',false),
('clavariadelphus_truncatus','ramaria_formosa','es','La clavaria truncada (maza de Hercules truncada) es una maza unica, truncada en el apice; la ramaria hermosa (coral hermoso) esta ramificada muchas veces — la ramificacion es el caracter clave.','Ambos discretos a debilmente fungicos; el olor no los separa.','La maza de Hercules sobre todo en bosque de coniferas rico en caliza; la ramaria hermosa mas bien en bosque de frondosas — diferencia de estacion, pero no absolutamente fiable.','Maza de Hercules esporada amarillo-ocre, ramaria hermosa tambien ocracea — ningun caracter practico.','Recolectar solo mazas no ramificadas, truncadas en el apice — en cuanto un hongo se ramifica en arbusto y/o sabe amargo, amenaza la toxica ramaria hermosa.','{"Maza de Hercules truncada: cuerpos fructiferos simples, no ramificados, en forma de maza con apice plano-truncado, a menudo ligeramente deprimido; ramaria hermosa ricamente ramificada como un arbusto.","Maza de Hercules generalmente amarillo-ocre a pardo-naranja, solitaria/claviforme; ramaria hermosa naranja-salmon con muchas puntas de ramas amarillas.","Maza de Hercules sabe suave a dulzona; ramaria hermosa amarga y gastrointestinalmente toxica.","Maza de Hercules crece tipicamente en bosque de coniferas calcicola (a menudo abeto rojo/abeto blanco); ramaria hermosa mas bien en bosque de frondosas.","La forma de maza no ramificada de la maza de Hercules excluye una confusion mirando con atencion — una confusion solo ocurre fugazmente en estadios jovenes coraliformes."}',false),
('clavariadelphus_truncatus','ramaria_formosa','fr','La massue d''Hercule tronquee est une massue unique, tronquee au sommet; la belle clavaire (ramaire jolie) est multiplement ramifiee — la ramification est le critere cle.','Les deux discrets a faiblement fongiques; l''odeur ne separe pas.','La massue d''Hercule surtout en foret de coniferes riche en calcaire; la belle clavaire plutot en foret de feuillus — difference de station, mais pas absolument fiable.','Massue d''Hercule sporee jaune-ocre, belle clavaire egalement ocree — pas de critere pratique.','Ne recolter que des massues non ramifiees, tronquees au sommet — des qu''un champignon se ramifie en buisson et/ou a un gout amer, gare a la toxique belle clavaire.','{"Massue d''Hercule tronquee: fructifications simples, non ramifiees, en forme de massue, a sommet aplati-tronque, souvent legerement deprime; belle clavaire richement ramifiee comme un buisson.","Massue d''Hercule generalement jaune-ocre a brun-orange, isolee/claviforme; belle clavaire orange-saumon avec de nombreuses pointes de rameaux jaunes.","Massue d''Hercule a saveur douce a sucree; belle clavaire amere et gastro-intestinalement toxique.","Massue d''Hercule pousse typiquement en foret de coniferes calcicole (souvent epicea/sapin); belle clavaire plutot en foret de feuillus.","La forme en massue non ramifiee de la massue d''Hercule exclut une confusion en regardant attentivement — une confusion ne survient que furtivement aux jeunes stades coralliformes."}',false),
('clavariadelphus_truncatus','ramaria_formosa','it','La clavaria troncata (mazza d''Ercole troncata) e una clava singola, troncata all''apice; la ramaria bella e ripetutamente ramificata — la ramificazione e il carattere chiave.','Entrambi inappariscenti a debolmente fungini; l''odore non separa.','La mazza d''Ercole soprattutto in bosco di conifere ricco di calcare; la ramaria bella piuttosto in bosco di latifoglie — differenza di stazione, ma non assolutamente affidabile.','Mazza d''Ercole sporata giallo-ocra, ramaria bella anch''essa ocracea — nessun carattere pratico.','Raccogliere solo clave non ramificate, troncate all''apice — appena un fungo si ramifica a cespuglio e/o ha sapore amaro, c''e il rischio della tossica ramaria bella.','{"Mazza d''Ercole troncata: corpi fruttiferi semplici, non ramificati, a forma di clava con apice piatto-troncato, spesso leggermente depresso; ramaria bella riccamente ramificata come un cespuglio.","Mazza d''Ercole generalmente giallo-ocra a bruno-arancio, isolata/claviforme; ramaria bella arancio-salmone con molte punte dei rami gialle.","Mazza d''Ercole ha sapore mite a dolciastro; ramaria bella amara e gastrointestinalmente tossica.","Mazza d''Ercole cresce tipicamente in bosco di conifere calcicolo (spesso abete rosso/abete bianco); ramaria bella piuttosto in bosco di latifoglie.","La forma a clava non ramificata della mazza d''Ercole esclude una confusione guardando con attenzione — una confusione avviene solo fugacemente negli stadi giovani coralliformi."}',false),
('clavulina_coralloides','ramaria_formosa','en','Crested coral fungus whitish and delicate with comb-like toothed tips; the beautiful coral (Ramaria formosa) is large, orange-salmon coloured with yellow branch tips.','Both mild and mushroomy, no distinguishing odour.','Both on the forest floor; the crested coral often at path edges and in deciduous/coniferous forest, the beautiful coral prefers deciduous forest — habitat does not distinguish reliably.','Crested coral white spore print, beautiful coral ochre-yellowish — spore colour distinguishes reliably.','Avoid coloured (orange/yellow) corals on principle; only small, white, mild-tasting corals are suitable for beginners — bitter taste or reddish discolouration = poisonous.','{"Crested coral (Clavulina coralloides/cristata): dainty, white to cream, with finely toothed/comb-like branch tips; the beautiful coral is distinctly larger, fleshy and orange-salmon coloured.","The crested coral stays whitish and does not turn wine-red; the beautiful coral discolours reddish-brownish when pressed.","Crested coral mild and small (a few cm); beautiful coral bitter and more massive.","The beautiful coral has orange branches with yellow tips — the colour rules out the white crested coral.","The beautiful coral is gastrointestinally poisonous/laxative; confusion is practically only conceivable at the juvenile stage."}',false),
('clavulina_coralloides','ramaria_formosa','es','Clavulina coralloide blanquecina y delicada con puntas dentadas en forma de cresta; la Ramaria formosa es grande, de color naranja-salmón con puntas de las ramas amarillas.','Ambas de olor suave y fúngico, ningún olor distintivo.','Ambas en el suelo del bosque; la Clavulina coralloide a menudo en bordes de senderos y en bosque de frondosas/coníferas, la Ramaria formosa prefiere el bosque de frondosas — el hábitat no distingue de forma fiable.','Clavulina coralloide: esporada blanca; Ramaria formosa: esporada ocre-amarillenta — el color de la esporada distingue de forma fiable.','Evitar por principio las clavarias coloreadas (naranja/amarillas); solo las pequeñas clavarias blancas de sabor suave son aptas para principiantes — sabor amargo o coloración rojiza = venenosa.','{"Clavulina coralloide (Clavulina coralloides/cristata): grácil, blanca a crema, con puntas de las ramas finamente dentadas/en forma de cresta; la Ramaria formosa es netamente más grande, carnosa y de color naranja-salmón.","La Clavulina coralloide permanece blanquecina y no se torna rojo vinoso; la Ramaria formosa vira a rojizo-parduzco a la presión.","Clavulina coralloide suave y pequeña (pocos cm); Ramaria formosa amarga y más maciza.","La Ramaria formosa tiene ramas naranjas con puntas amarillas — el color excluye a la blanca Clavulina coralloide.","La Ramaria formosa es gastrointestinalmente venenosa/laxante; la confusión solo es prácticamente concebible en estado juvenil."}',false),
('clavulina_coralloides','ramaria_formosa','fr','Clavaire crêtée blanchâtre et délicate aux pointes dentelées en forme de crête ; la Clavaire jolie est grande, de couleur orange-saumon avec des pointes de rameaux jaunes.','Les deux ont une odeur douce et fongique, aucune odeur ne permet de les distinguer.','Les deux poussent au sol forestier ; la Clavaire crêtée souvent en bordure de chemins et en forêt de feuillus/conifères, la Clavaire jolie préfère la forêt de feuillus — l''habitat ne permet pas une distinction fiable.','Clavaire crêtée : sporée blanche ; Clavaire jolie : sporée ocre-jaunâtre — la couleur de la sporée permet une distinction fiable.','Éviter par principe les clavaires colorées (orange/jaune) ; seules les petites clavaires blanches au goût doux conviennent aux débutants — goût amer ou coloration rougeâtre = vénéneuse.','{"Clavaire crêtée (Clavulina coralloides/cristata) : gracile, blanche à crème, avec des pointes de rameaux finement dentelées/en forme de crête ; la Clavaire jolie est nettement plus grande, charnue et de couleur orange-saumon.","La Clavaire crêtée reste blanchâtre et ne se colore pas en rouge vineux ; la Clavaire jolie se colore en rougeâtre-brunâtre à la pression.","Clavaire crêtée douce et petite (quelques cm) ; Clavaire jolie amère et plus massive.","La Clavaire jolie a des rameaux orange à pointes jaunes — la couleur exclut la Clavaire crêtée blanche.","La Clavaire jolie est gastro-intestinale/laxative ; la confusion n''est pratiquement envisageable qu''au stade juvénile."}',false),
('clavulina_coralloides','ramaria_formosa','it','Clavulina coralloide biancastra e delicata con punte dentellate a forma di cresta; la Ramaria formosa è grande, di colore arancio-salmone con punte dei rami gialle.','Entrambe hanno odore lieve e fungino, nessun odore distintivo.','Entrambe sul suolo del bosco; la Clavulina coralloide spesso ai bordi dei sentieri e in bosco di latifoglie/conifere, la Ramaria formosa predilige il bosco di latifoglie — l''habitat non distingue in modo affidabile.','Clavulina coralloide: sporata bianca; Ramaria formosa: sporata ocra-giallastra — il colore della sporata distingue in modo affidabile.','Evitare per principio le ramarie colorate (arancio/gialle); solo le piccole ramarie bianche dal sapore mite sono adatte ai principianti — sapore amaro o colorazione rossastra = velenosa.','{"Clavulina coralloide (Clavulina coralloides/cristata): esile, bianca o crema, con punte dei rami finemente dentellate/a cresta; la Ramaria formosa è nettamente più grande, carnosa e di colore arancio-salmone.","La Clavulina coralloide resta biancastra e non si colora di rosso vinoso; la Ramaria formosa vira al rossastro-brunastro sotto pressione.","Clavulina coralloide mite e piccola (pochi cm); Ramaria formosa amara e più massiccia.","La Ramaria formosa ha rami arancioni con punte gialle — il colore esclude la bianca Clavulina coralloide.","La Ramaria formosa è gastrointestinale/lassativa; la confusione è praticamente possibile solo allo stadio giovanile."}',false),
('clitocybe_nebularis','ampulloclitocybe_clavipes','en','Large, fleshy clouded funnel cap, grey-frosted vs. smaller clavipes, white-grey to grey-brown; both with club-shaped base.','Clouded funnel cap strongly and peculiarly perfumed; clavipes faintly fruity.','Clouded funnel cap often in fairy rings in coniferous/deciduous forest in late autumn; clavipes in similar locations, no reliable separating feature.','Clouded funnel cap pale cream spore print, clavipes white.','Do not combine small, soft funnel caps with a club-shaped, spongy base with alcohol; always cook the clouded funnel cap thoroughly.','{"Both have a club-shaped thickened stem base — the key feature lies in the habit and cap colour: clouded funnel cap distinctly larger and fleshier (cap up to 20 cm), grey-frosted; clavipes smaller with white-grey to grey-brown cap and darker centre.","Clouded funnel cap with elastic flesh and gills that can be pushed off the cap flesh easily as in blewits; clavipes gills whitish and widely decurrent.","Smell separates them: clouded funnel cap strong, peculiarly perfumed-sweetish; clavipes only faintly fruity-mushroomy.","clavipes causes a coprine syndrome with alcohol; the clouded funnel cap is only of limited digestibility and indigestible for many (cook thoroughly, not raw)."}',false),
('clitocybe_nebularis','ampulloclitocybe_clavipes','es','Gran clitocibe nebuloso carnoso, gris pruinoso vs. clavipes más pequeño, gris-blanco a gris-pardo; ambos con base claviforme.','Clitocibe nebuloso fuerte y extrañamente perfumado; clavipes débilmente afrutado.','Clitocibe nebuloso a menudo en corros de brujas en bosque de coníferas/frondosas a finales de otoño; clavipes en estaciones similares, ningún criterio de separación seguro.','Clitocibe nebuloso: esporada crema pálido; clavipes: esporada blanca.','No combinar con alcohol los pequeños clitocibes blandos con base claviforme esponjosa; cocinar bien el clitocibe nebuloso.','{"Ambos tienen la base del pie engrosada en maza — el criterio clave está en el porte y el color del sombrero: clitocibe nebuloso netamente más grande y carnoso (sombrero hasta 20 cm), gris pruinoso; clavipes más pequeño con sombrero gris-blanco a gris-pardo y centro más oscuro.","Clitocibe nebuloso de carne elástica y láminas que se desprenden fácilmente de la carne del sombrero como en los tricolomas; las láminas del clavipes blanquecinas y muy decurrentes.","El olor distingue: clitocibe nebuloso fuerte, extrañamente perfumado-dulzón; clavipes solo débilmente afrutado-fúngico.","El clavipes provoca un síndrome coprínico con el alcohol; el clitocibe nebuloso solo es parcialmente tolerado e indigesto para muchos (cocinar bien, no crudo)."}',false),
('clitocybe_nebularis','ampulloclitocybe_clavipes','fr','Grand clitocybe nébuleux gris pruineux, charnu vs. clavipes plus petit, blanc-gris à gris-brun ; les deux avec une base en massue.','Clitocybe nébuleux fortement parfumé de façon particulière ; clavipes faiblement fruité.','Clitocybe nébuleux souvent en ronds de sorcières en forêt de conifères/feuillus à la fin de l''automne ; clavipes mêmes stations, pas de critère de séparation sûr.','Clitocybe nébuleux à sporée crème pâle, clavipes blanche.','Ne pas combiner les petits clitocybes mous à base en massue spongieuse avec de l''alcool ; pour le clitocybe nébuleux, toujours bien cuire.','{"Les deux ont une base du pied épaissie en massue – le critère clé réside dans le port et la couleur du chapeau : clitocybe nébuleux nettement plus grand et plus charnu (chapeau jusqu''à 20 cm), gris pruineux ; clavipes plus petit avec un chapeau blanc-gris à gris-brun et un centre plus sombre.","Clitocybe nébuleux à chair élastique et lamelles qui se détachent facilement de la chair du chapeau comme chez les lépistes ; lamelles de clavipes blanchâtres et largement décurrentes.","L''odeur sépare : clitocybe nébuleux fort, parfumé-sucré de façon particulière ; clavipes seulement faiblement fruité-fongique.","clavipes provoque avec l''alcool un syndrome coprinien ; le clitocybe nébuleux n''est que partiellement tolérable et indigeste pour beaucoup (bien cuire, pas cru)."}',false),
('clitocybe_nebularis','ampulloclitocybe_clavipes','it','Grande Clitocybe nebularis carnoso, grigio pruinoso vs. clavipes più piccolo, grigio-bianco a grigio-bruno; entrambi con base claviforme.','Clitocybe nebularis fortemente e stranamente profumato; clavipes debolmente fruttato.','Clitocybe nebularis spesso in cerchi delle streghe in bosco di conifere/latifoglie nel tardo autunno; clavipes in stazioni simili, nessun criterio di separazione sicuro.','Clitocybe nebularis: sporata crema pallido; clavipes: sporata bianca.','Non abbinare all''alcol i piccoli clitocybi molli con base claviforme spugnosa; cuocere bene il Clitocybe nebularis.','{"Entrambi hanno la base del gambo ingrossata a clava — il criterio chiave sta nel portamento e nel colore del cappello: Clitocybe nebularis nettamente più grande e carnoso (cappello fino a 20 cm), grigio pruinoso; clavipes più piccolo con cappello grigio-bianco a grigio-bruno e centro più scuro.","Clitocybe nebularis con carne elastica e lamelle che si staccano facilmente dalla carne del cappello come nei tricolomi; le lamelle del clavipes biancastre e nettamente decorrenti.","L''odore distingue: Clitocybe nebularis forte, stranamente profumato-dolciastro; clavipes solo debolmente fruttato-fungino.","Il clavipes provoca una sindrome coprinica con l''alcol; il Clitocybe nebularis è solo parzialmente tollerato e indigesto per molti (cuocere bene, non crudo)."}',false),
('clitocybe_odora','clitocybe_fragrans','en','Blue-green colouration of the aniseed funnel cap vs. fragrans small, pale watery-grey.','Both smell of aniseed; odora stronger/more persistent, fragrans weaker and more fleeting.','Both in deciduous/coniferous/mixed forest; no reliable separating feature via habitat.','Both white to pale cream spore print; not distinctive.','Aniseed smell alone does not protect — never collect small, pale, watery aniseed funnel caps because of muscarine.','{"The aniseed funnel cap is distinctly blue-green to grey-green coloured, more robust in habit; fragrans is pale grey-brown/light watery and smaller, without blue/green tones.","fragrans contains muscarine (sweating, salivation/lacrimation, miosis, gastrointestinal upset); the aniseed funnel cap is edible cooked (as a seasoning, in small amounts) — poisonous raw.","Both smell of aniseed; the green one usually smells more intensely/persistently, in fragrans the aniseed smell evaporates quickly on drying.","fragrans cap pale with often translucently striate margin and darker centre; odora coloured more uniformly blue-green."}',false),
('clitocybe_odora','clitocybe_fragrans','es','Coloración azul-verde del clitocibe anisado verde vs. fragrans pequeño, gris acuoso pálido.','Ambos con olor a anís; odora más fuerte/persistente, fragrans más débil y más fugaz.','Ambos en bosque de frondosas/coníferas/mixto; ningún criterio de separación fiable a través del hábitat.','Ambos con esporada blanca a crema pálido; no distintiva.','El olor a anís por sí solo no protege — no recolectar nunca pequeños clitocibes anisados pálidos y acuosos por la muscarina.','{"El clitocibe anisado verde está netamente coloreado de azul-verde a gris-verde, más robusto de porte; fragrans es gris-pardo pálido/claro acuoso y más pequeño, sin tonos azules/verdes.","fragrans contiene muscarina (sudoración, salivación/lagrimeo, miosis, trastornos gastrointestinales); el clitocibe anisado verde es comestible cocinado (como condimento, en pequeñas cantidades) — venenoso crudo.","Ambos huelen a anís; el verde huele por lo general más intensa/duraderamente, en fragrans el olor a anís se desvanece rápidamente al secarse.","Sombrero de fragrans pálido con margen a menudo estriado por transparencia y centro más oscuro; odora coloreado más uniformemente de azul-verde."}',false),
('clitocybe_odora','clitocybe_fragrans','fr','Coloration bleu-vert du clitocybe anisé vs. fragrans pâle, gris aqueux, petit.','Les deux d''anis ; odora plus fort/plus durable, fragrans plus faible et plus volatile.','Les deux en forêt de feuillus/conifères/mixte ; pas de critère de séparation fiable via l''habitat.','Les deux à sporée blanche à crème pâle ; non discriminant.','L''odeur d''anis seule ne protège pas - ne jamais récolter les petits clitocybes anisés pâles, aqueux à cause de la muscarine.','{"Le clitocybe anisé est nettement coloré en bleu-vert à gris-vert, plus robuste de port ; fragrans est gris-brun pâle/aqueux clair et plus petit, sans teintes bleues/vertes.","fragrans contient de la muscarine (sudation, salivation/larmoiement, myosis, troubles gastro-intestinaux) ; le clitocybe anisé est comestible cuit (comme condiment, en petites quantités) - cru toxique.","Les deux sentent l''anis ; l''anisé sent généralement plus intensément/durablement, chez fragrans l''odeur d''anis s''évapore vite au séchage.","Chapeau de fragrans pâle avec un bord souvent strié par transparence et un centre plus sombre ; odora coloré en bleu-vert plus uniforme."}',false),
('clitocybe_odora','clitocybe_fragrans','it','Colorazione blu-verde del Clitocybe odora vs. fragrans piccolo, grigio acquoso pallido.','Entrambi odore di anice; odora più forte/persistente, fragrans più debole e più fugace.','Entrambi in bosco di latifoglie/conifere/misto; nessun criterio di separazione affidabile tramite l''habitat.','Entrambi sporata bianca a crema pallido; non distintiva.','L''odore di anice da solo non protegge — non raccogliere mai piccoli clitocybi anisati pallidi e acquosi a causa della muscarina.','{"Il Clitocybe odora è nettamente colorato di blu-verde a grigio-verde, più robusto nel portamento; fragrans è grigio-bruno pallido/chiaro acquoso e più piccolo, senza toni blu/verdi.","fragrans contiene muscarina (sudorazione, salivazione/lacrimazione, miosi, disturbi gastrointestinali); il Clitocybe odora è commestibile cotto (come aromatizzante, in piccole quantità) — velenoso crudo.","Entrambi odorano di anice; il verde odora di solito più intensamente/durevolmente, in fragrans l''odore di anice svanisce rapidamente all''essiccamento.","Cappello di fragrans pallido con margine spesso striato per trasparenza e centro più scuro; odora colorato più uniformemente di blu-verde."}',false),
('clitopilus_prunulus','clitocybe_fragrans','en','The miller cream-white with soft gills later flushed pink; fragrans pale grey, gills stay white.','The miller intensely mealy-cucumber; fragrans aniseed — clearly different.','Both in forest and at forest edges; no reliable separating feature via habitat.','The miller pink/salmon-pink, fragrans white — the most reliable distinguishing feature.','Always make a spore print AND check the smell separately: white-spored, non-mealy funnel caps are potentially highly poisonous — when in doubt, leave them entirely.','{"Decisive is the spore print: the miller pink/salmon-pink, fragrans pure white — the spore print makes the difference unambiguous.","Smell separates additionally: the miller strongly of fresh flour/cucumber, fragrans of aniseed.","The miller''s gills become pink-tinged with maturity from the spores and are conspicuously soft; fragrans gills stay whitish.","fragrans contains muscarine (sweating, salivation, miosis); the miller is a good edible — the main danger, however, is confusion with highly poisonous white funnel caps."}',false),
('clitopilus_prunulus','clitocybe_fragrans','es','El molinero blanco-crema con láminas blandas más tarde teñidas de rosa; fragrans gris pálido, las láminas permanecen blancas.','El molinero intensamente harinoso-pepino; fragrans anisado — claramente diferente.','Ambos en bosque y en bordes de bosque; ningún criterio de separación fiable a través del hábitat.','El molinero rosa/rosa salmón, fragrans blanco — el criterio de distinción más seguro.','Hacer siempre una esporada Y comprobar el olor por separado: los clitocibes de esporas blancas y no harinosos son potencialmente muy venenosos — en caso de duda, dejarlos por completo en el sitio.','{"Decisiva es la esporada: el molinero rosa/rosa salmón, fragrans blanco puro — la esporada hace la diferencia inequívoca.","El olor distingue además: el molinero fuertemente a harina fresca/pepino, fragrans a anís.","Las láminas del molinero se tornan rosadas con la madurez por las esporas y son notablemente blandas; las láminas de fragrans permanecen blanquecinas.","fragrans contiene muscarina (sudoración, salivación, miosis); el molinero es un buen comestible — el peligro principal, sin embargo, es la confusión con los clitocibes blancos muy venenosos."}',false),
('clitopilus_prunulus','clitocybe_fragrans','fr','Meunier crème-blanc avec des lamelles molles plus tard teintées de rose ; fragrans gris pâle, lamelles restant blanches.','Meunier intensément farineux-concombre ; fragrans d''anis - clairement différent.','Les deux en forêt et aux lisières ; pas de critère de séparation fiable via l''habitat.','Meunier rose/rose saumon, fragrans blanche - le critère de distinction le plus sûr.','Toujours faire une sporée ET vérifier l''odeur séparément : les clitocybes à spores blanches, non farineux, sont potentiellement très toxiques - en cas de doute laisser entièrement sur place.','{"Le décisif est la sporée : meunier rose/rose saumon, fragrans blanc pur - la sporée rend la différence sans équivoque.","L''odeur sépare en plus : meunier fortement de farine fraîche/concombre, fragrans d''anis.","Les lamelles du meunier deviennent roses avec la maturité par les spores et sont remarquablement molles ; les lamelles de fragrans restent blanchâtres.","fragrans contient de la muscarine (sudation, salivation, myosis) ; le meunier est un bon comestible - le danger principal est cependant la confusion avec des clitocybes blancs très toxiques."}',false),
('clitopilus_prunulus','clitocybe_fragrans','it','Clitopilus prunulus bianco-crema con lamelle molli più tardi sfumate di rosa; fragrans grigio pallido, le lamelle restano bianche.','Clitopilus prunulus intensamente farinoso-cetriolo; fragrans anisato — chiaramente diverso.','Entrambi in bosco e ai margini del bosco; nessun criterio di separazione affidabile tramite l''habitat.','Clitopilus prunulus rosa/rosa salmone, fragrans bianco — il criterio di distinzione più sicuro.','Fare sempre la sporata E verificare l''odore separatamente: i clitocybi con spore bianche e non farinosi sono potenzialmente molto velenosi — in caso di dubbio lasciare completamente sul posto.','{"Decisiva è la sporata: Clitopilus prunulus rosa/rosa salmone, fragrans bianco puro — la sporata rende la differenza inequivocabile.","L''odore distingue in più: Clitopilus prunulus fortemente di farina fresca/cetriolo, fragrans anisato.","Le lamelle del Clitopilus prunulus diventano rosate con la maturità per le spore e sono notevolmente molli; le lamelle di fragrans restano biancastre.","fragrans contiene muscarina (sudorazione, salivazione, miosi); il Clitopilus prunulus è un buon commestibile — il pericolo principale è tuttavia la confusione con i clitocybi bianchi molto velenosi."}',false),
('coprinopsis_atramentaria','coprinopsis_picacea','en','Magpie inkcap spotted black and white vs. common inkcap uniformly grey, longitudinally pleated, without white veil flecks.','Magpie inkcap musty-tarry; common inkcap inconspicuously mushroomy.','Magpie inkcap solitary in humus-/lime-rich beech/deciduous woods; common inkcap clustered on stumps, path edges and in gardens.','Both black, deliquescing spore print; not distinctive.','White, wipeable veil flecks on a dark cap characterise the inedible magpie inkcap; and never consume common inkcaps with alcohol.','{"Young magpie inkcaps can be confused with the common inkcap: the magpie inkcap bears white, wipeable veil scales on a dark ground (black-and-white pattern); the common inkcap is uniformly grey to grey-brown with a longitudinally pleated/furrowed cap without white flecks.","The magpie inkcap smells musty-tarry and is inedible; the common inkcap is (only without alcohol) edible with reservations.","Magpie inkcap more slender and taller with a fragile stem; common inkcap more squat and mostly growing in clusters.","Caution: the common inkcap contains coprine and is poisonous with alcohol — not a ''safe'' edible."}',false),
('coprinopsis_atramentaria','coprinopsis_picacea','es','Coprino pícaro moteado de negro y blanco vs. coprino de tinta uniformemente gris, con pliegues longitudinales, sin escamas de velo blancas.','Coprino pícaro olor a moho-alquitrán; coprino de tinta olor fúngico discreto.','Coprino pícaro solitario en hayedos/bosques de frondosas ricos en humus/cal; coprino de tinta en grupos sobre tocones, bordes de senderos y en jardines.','Ambos con esporada negra y deliciscente; no distintiva.','Escamas de velo blancas y desprendibles sobre sombrero oscuro caracterizan al coprino pícaro no comestible; y no consumir nunca los coprinos de tinta con alcohol.','{"Los coprinos pícaros jóvenes pueden confundirse con el coprino de tinta: el coprino pícaro lleva escamas de velo blancas y desprendibles sobre fondo oscuro (patrón negro-blanco); el coprino de tinta es uniformemente gris a gris-pardo con sombrero de pliegues longitudinales/surcado sin manchas blancas.","El coprino pícaro huele a moho-alquitrán y es no comestible; el coprino de tinta es (solo sin alcohol) comestible con reservas.","Coprino pícaro más esbelto y más alto con pie frágil; coprino de tinta más rechoncho y creciendo por lo general en grupos.","Atención: el coprino de tinta contiene coprina y es venenoso con el alcohol — no un comestible «seguro»."}',false),
('coprinopsis_atramentaria','coprinopsis_picacea','fr','Coprin pie tacheté noir-blanc vs. coprin noir d''encre uniformément gris, longitudinalement plissé, sans flocons de voile blancs.','Coprin pie de moisi-goudronné ; coprin noir d''encre discret-fongique.','Coprin pie isolé dans les forêts de hêtres/feuillus riches en humus/calcaire ; coprin noir d''encre en touffes sur les souches, bords de chemins et dans les jardins.','Les deux à sporée noire, déliquescente ; non discriminant.','Les flocons de voile blancs, essuyables, sur chapeau sombre caractérisent le coprin pie non comestible ; et ne jamais consommer les coprins noirs d''encre avec de l''alcool.','{"Les jeunes coprins pies peuvent être confondus avec le coprin noir d''encre : le coprin pie porte des écailles de voile blanches, essuyables, sur fond sombre (motif noir-blanc) ; le coprin noir d''encre est uniformément gris à gris-brun avec un chapeau longitudinalement plissé/sillonné sans taches blanches.","Le coprin pie sent le moisi-goudronné et est non comestible ; le coprin noir d''encre est (seulement sans alcool) comestible avec réserve.","Coprin pie plus élancé et plus haut avec un pied fragile ; coprin noir d''encre plus trapu et poussant le plus souvent en touffes.","Attention : le coprin noir d''encre contient de la coprine et est lui-même toxique avec l''alcool - pas un comestible « sûr »."}',false),
('coprinopsis_atramentaria','coprinopsis_picacea','it','Coprinopsis picacea macchiato di nero e bianco vs. Coprinopsis atramentaria uniformemente grigio, a pieghe longitudinali, senza fiocchi di velo bianchi.','Coprinopsis picacea odore di muffa-catrame; Coprinopsis atramentaria odore fungino discreto.','Coprinopsis picacea isolato in faggete/boschi di latifoglie ricchi di humus/calcare; Coprinopsis atramentaria in ciuffi su ceppi, bordi dei sentieri e nei giardini.','Entrambi sporata nera e deliquescente; non distintiva.','Fiocchi di velo bianchi e asportabili su cappello scuro caratterizzano il Coprinopsis picacea non commestibile; e non consumare mai i Coprinopsis atramentaria con l''alcol.','{"I giovani Coprinopsis picacea possono essere confusi con il Coprinopsis atramentaria: il Coprinopsis picacea porta squame di velo bianche e asportabili su fondo scuro (motivo nero-bianco); il Coprinopsis atramentaria è uniformemente grigio a grigio-bruno con cappello a pieghe longitudinali/solcato senza macchie bianche.","Il Coprinopsis picacea odora di muffa-catrame ed è non commestibile; il Coprinopsis atramentaria è (solo senza alcol) commestibile con riserva.","Coprinopsis picacea più slanciato e più alto con gambo fragile; Coprinopsis atramentaria più tozzo e che cresce per lo più in ciuffi.","Attenzione: il Coprinopsis atramentaria contiene coprina ed è velenoso con l''alcol — non un commestibile «sicuro»."}',false),
('cortinarius_praestans','cortinarius_traganus','en','C. praestans large, wrinkled violet-brown cap with whitish veil and scales; C. traganus smaller, lilac throughout with club-shaped stem.','C. praestans mild; C. traganus repulsively goaty – the smell warns against traganus.','C. praestans in lime-rich deciduous forest (beech/oak); C. traganus rather in acidic coniferous forest.','Both rust-brown – the spore print does NOT separate here; only habit, smell and gill colour distinguish.','Have cortinars validated only by experienced mushroom inspectors (VAPKO) – the genus contains deadly species; as a beginner, leave ALL webcaps.','{"C. praestans is large and robust with a wrinkled violet-brown cap, whitish veil scales and pale clay-coloured, later rust-brown gills; C. traganus is lilac-coloured throughout and more slender.","Smell: C. praestans mild/pleasant; C. traganus unpleasantly goaty.","C. traganus has saffron-ochre to lilac flesh tones and a club-shaped thickened stem; C. praestans firm whitish flesh.","Both are cortinars with rust-brown spore print – the identification of edible cortinars is permitted ONLY to experts."}',false),
('cortinarius_praestans','cortinarius_traganus','es','C. praestans grande, sombrero pardo-violeta rugoso con velo blanquecino y escamas; C. traganus más pequeño, enteramente lila con pie claviforme.','C. praestans suave; C. traganus olor caprino repugnante – el olor advierte sobre traganus.','C. praestans en bosque de frondosas calcáreo (haya/roble); C. traganus más bien en bosque de coníferas ácido.','Ambos pardo-herrumbre – la esporada aquí NO distingue; solo el porte, el olor y el color de las láminas distinguen.','Hacer validar los cortinarios solo por controladores de setas experimentados (VAPKO) – el género contiene especies mortales; como principiante, dejar TODOS los cortinarios en el sitio.','{"C. praestans es grande y robusto con sombrero pardo-violeta rugoso, escamas de velo blanquecinas y láminas pálido color arcilla, más tarde pardo-herrumbre; C. traganus está enteramente coloreado de lila y es más esbelto.","Olor: C. praestans suave/agradable; C. traganus desagradable, caprino.","C. traganus tiene tonos de carne azafrán-ocre a lila y pie engrosado en maza; C. praestans carne firme blanquecina.","Ambos son cortinarios con esporada pardo-herrumbre – la determinación de cortinarios comestibles está permitida SOLO a expertos."}',false),
('cortinarius_praestans','cortinarius_traganus','fr','C. praestans grand, chapeau brun-violet ridé avec un voile blanchâtre et des écailles ; C. traganus plus petit, entièrement lilas avec un pied en massue.','C. praestans doux ; C. traganus répugnant, de bouc – l''odeur met en garde contre traganus.','C. praestans en forêt de feuillus calcaire (hêtre/chêne) ; C. traganus plutôt en forêt de conifères acide.','Les deux brun rouille – la sporée ne sépare PAS ici ; seuls le port, l''odeur et la couleur des lamelles distinguent.','Ne faire valider les cortinaires en général que par des contrôleurs de champignons expérimentés (VAPKO) – le genre contient des espèces mortelles ; en tant que débutant, laisser TOUS les cortinaires sur place.','{"C. praestans est grand et robuste avec un chapeau brun-violet ridé, des écailles de voile blanchâtres et des lamelles ocre pâle, plus tard brun rouille ; C. traganus est coloré en lilas de façon uniforme et plus élancé.","Odeur : C. praestans douce/agréable ; C. traganus désagréable, de bouc-chèvre.","C. traganus a des teintes de chair safran-ocre à lilas et un pied épaissi en massue ; C. praestans une chair blanchâtre ferme.","Les deux sont des cortinaires à sporée brun rouille – la détermination des cortinaires comestibles n''est permise QU''aux experts."}',false),
('cortinarius_praestans','cortinarius_traganus','it','C. praestans grande, cappello bruno-violetto rugoso con velo biancastro e squame; C. traganus più piccolo, interamente lilla con gambo claviforme.','C. praestans mite; C. traganus odore caprino ripugnante – l''odore mette in guardia da traganus.','C. praestans in bosco di latifoglie calcareo (faggio/quercia); C. traganus piuttosto in bosco di conifere acido.','Entrambi bruno-ruggine – la sporata qui NON distingue; solo il portamento, l''odore e il colore delle lamelle distinguono.','Far validare i cortinari solo da controllori di funghi esperti (VAPKO) – il genere contiene specie mortali; da principiante, lasciare TUTTI i cortinari sul posto.','{"C. praestans è grande e robusto con cappello bruno-violetto rugoso, squame di velo biancastre e lamelle pallido color argilla, più tardi bruno-ruggine; C. traganus è interamente colorato di lilla e più slanciato.","Odore: C. praestans mite/gradevole; C. traganus sgradevole, caprino-becco.","C. traganus ha toni di carne zafferano-ocra a lilla e gambo ingrossato a clava; C. praestans carne soda biancastra.","Entrambi sono cortinari con sporata bruno-ruggine – la determinazione dei cortinari commestibili è permessa SOLO agli esperti."}',false),
('cuphophyllus_pratensis','hygrocybe_conica','en','The eponymous blackening (cap/stem turn ink-black on pressure or with age) characterises the conical waxcap; the meadow waxcap stays pale apricot-coloured and never blackens.','Both largely odourless – no separating feature.','Both on unfertilised meadows/poor grassland – habitat does not separate; therefore pay attention to shape and blackening.','Both with white spore print – no separating feature.','Pressure test: if the fruiting body blackens at contact points or if the cap is sharply conical and fire-coloured, leave it (conical waxcap). Only collect blunt, pale-orange, non-blackening waxcaps with decurrent waxy gills.','{"Conical waxcap: sharply conical, vivid yellow-orange-red cap that turns BLACK on touch/with age (whole fruiting body blackening) – characteristic blackening","Meadow waxcap: bluntly convex to flattening, pale ochre-orange/apricot-coloured cap, does NOT blacken","Meadow waxcap with widely decurrent, distant, thickish waxy gills; conical waxcap with rather free/adnate gills","The conical waxcap is regarded as slightly poisonous/suspected of causing gastrointestinal upset – the meadow waxcap is a good edible"}',false),
('cuphophyllus_pratensis','hygrocybe_conica','es','El ennegrecimiento epónimo (sombrero/pie se vuelven negro tinta a la presión o con la edad) caracteriza al higróforo cónico; el higróforo de los prados permanece de color albaricoque pálido y no ennegrece nunca.','Ambos prácticamente inodoros – ningún criterio de separación.','Ambos sobre prados no abonados/pastos pobres – el hábitat no distingue; por ello atender a la forma y al ennegrecimiento.','Ambos con esporada blanca – ningún criterio de separación.','Prueba de presión: si el cuerpo fructífero ennegrece en los puntos de contacto o si el sombrero es cónico puntiagudo y color fuego, dejarlo en el sitio (higróforo cónico). Recolectar solo los higróforos obtusos, naranja pálido, que no ennegrecen, con láminas cerosas decurrentes.','{"Higróforo cónico: sombrero cónico puntiagudo, vivo amarillo-naranja-rojo, que se vuelve NEGRO al tacto/con la edad (todo el cuerpo fructífero ennegreciendo) – ennegrecimiento característico","Higróforo de los prados: sombrero obtuso-convexo a aplanándose, ocre-naranja pálido/color albaricoque, NO ennegrece","Higróforo de los prados con láminas cerosas ampliamente decurrentes, espaciadas y engrosadas; higróforo cónico con láminas más bien libres/adnatas","El higróforo cónico se considera ligeramente venenoso/sospechoso de causar trastornos gastrointestinales – el higróforo de los prados es un buen comestible"}',false),
('cuphophyllus_pratensis','hygrocybe_conica','fr','Le noircissement éponyme (chapeau/pied deviennent noir d''encre à la pression ou avec l''âge) caractérise l''hygrocybe conique ; le hygrophore des prés reste abricot pâle et ne noircit jamais.','Les deux largement inodores – pas un critère de séparation.','Les deux sur prairies non fertilisées/pelouses maigres – l''habitat ne sépare pas ; donc faire attention à la forme et au noircissement.','Les deux à sporée blanche – pas un critère de séparation.','Test de pression : si le carpophore noircit aux points de contact ou si le chapeau est conique-pointu et couleur de feu, laisser sur place (hygrocybe conique). Ne récolter que les hygrophores obtus, orange pâle, ne noircissant pas, à lamelles cireuses décurrentes.','{"Hygrocybe conique : chapeau conique-pointu, jaune-orange-rouge vif, qui NOIRCIT au toucher/avec l''âge (tout le carpophore noircissant) – noircissement caractéristique","Hygrophore des prés : chapeau obtus-convexe à s''aplatissant, ocre-orange/abricot pâle, ne noircit PAS","Hygrophore des prés à lamelles cireuses largement décurrentes, espacées, épaissies ; hygrocybe conique à lamelles plutôt libres/adnexées","Hygrocybe conique considérée comme faiblement toxique/suspecte gastro-intestinale – hygrophore des prés bon comestible"}',false),
('cuphophyllus_pratensis','hygrocybe_conica','it','L''annerimento eponimo (cappello/gambo diventano nero inchiostro alla pressione o con l''età) caratterizza l''Hygrocybe conica; il Cuphophyllus pratensis resta di colore albicocca pallido e non annerisce mai.','Entrambi pressoché inodori – nessun criterio di separazione.','Entrambi su prati non concimati/magri – l''habitat non distingue; quindi badare alla forma e all''annerimento.','Entrambi con sporata bianca – nessun criterio di separazione.','Test di pressione: se il corpo fruttifero annerisce nei punti di contatto o se il cappello è conico appuntito e color fuoco, lasciare sul posto (Hygrocybe conica). Raccogliere solo gli igrofori ottusi, arancio pallido, non anneriti, con lamelle cerose decorrenti.','{"Hygrocybe conica: cappello conico appuntito, vivace giallo-arancio-rosso, che ANNERISCE al tatto/con l''età (intero corpo fruttifero annerente) – annerimento caratteristico","Cuphophyllus pratensis: cappello ottuso-convesso a spianantesi, ocra-arancio pallido/color albicocca, NON annerisce","Cuphophyllus pratensis con lamelle cerose largamente decorrenti, distanziate e ingrossate; Hygrocybe conica con lamelle piuttosto libere/adnate","L''Hygrocybe conica è considerato debolmente velenoso/sospetto di disturbi gastrointestinali – il Cuphophyllus pratensis è un buon commestibile"}',false),
('cuphophyllus_virgineus','hygrocybe_conica','en','The snowy waxcap is small, white and does not blacken; the conical waxcap is sharply conical, fiery-coloured and blackens.','Both nearly odourless – not a distinguishing feature.','Both on poor meadows/lawns – habitat does not distinguish; colour and blackening are decisive.','Both with white spore print – not a distinguishing feature.','Blackening + sharply conical fiery colour = conical waxcap (leave it). Use only white, non-blackening waxcaps with decurrent gills.','{"Conical waxcap: sharply conical cap, vividly coloured yellow/orange/red, blackens on touch and completely with age","Snowy waxcap: smaller, whitish-ivory, bluntly convex cap, does NOT blacken","Snowy waxcap with white waxy, distant, widely decurrent gills; conical waxcap vividly coloured and blackening","Conical waxcap mildly poisonous/suspected of gastrointestinal effects – snowy waxcap a mild edible"}',false),
('cuphophyllus_virgineus','hygrocybe_conica','es','La higróforo virginal es pequeña, blanca y no ennegrece; la higróforo cónico es cónico-puntiagudo, color fuego y ennegrece.','Ambos casi inodoros – no es un carácter distintivo.','Ambos en prados/céspedes pobres – el hábitat no distingue; el color y el ennegrecimiento son determinantes.','Ambos con esporada blanca – no es un carácter distintivo.','Ennegrecimiento + color fuego cónico-puntiagudo = higróforo cónico (dejarlo). Usar solo los higróforos blancos, no ennegrecientes, con láminas decurrentes.','{"Higróforo cónico: sombrero cónico-puntiagudo, vivamente coloreado amarillo/naranja/rojo, ennegrece al tacto y por completo con la edad","Higróforo virginal: sombrero más pequeño, blanquecino-marfil, convexo obtuso, NO ennegrece","Higróforo virginal con láminas cerosas blancas, espaciadas, ampliamente decurrentes; higróforo cónico vivamente coloreado y ennegreciente","Higróforo cónico levemente tóxico/sospechoso de efectos gastrointestinales – higróforo virginal comestible suave"}',false),
('cuphophyllus_virgineus','hygrocybe_conica','fr','Le hygrophore blanc de neige est petit, blanc et ne noircit pas ; l''hygrocybe conique est conique-pointu, couleur de feu et noircit.','Les deux presque inodores – pas un critère de séparation.','Les deux sur prairies/pelouses maigres – la station ne sépare pas ; la couleur et le noircissement sont déterminants.','Les deux à sporée blanche – pas un critère de séparation.','Noircissement + couleur de feu conique-pointue = hygrocybe conique (laisser sur place). N''utiliser que les hygrophores blancs, ne noircissant pas, à lamelles décurrentes.','{"Hygrocybe conique : chapeau conique-pointu, fortement coloré en jaune/orange/rouge, noircit au toucher et avec l''âge complètement","Hygrophore blanc de neige : chapeau plus petit, blanchâtre-ivoire, obtus-convexe, ne noircit PAS","Hygrophore blanc de neige à lamelles cireuses largement décurrentes, espacées, blanches ; hygrocybe conique vivement colorée et noircissante","Hygrocybe conique faiblement toxique/suspecte gastro-intestinale – hygrophore blanc de neige comestible doux"}',false),
('cuphophyllus_virgineus','hygrocybe_conica','it','La cuffia verginea è piccola, bianca e non annerisce; l''igroforo conico è conico-appuntito, color fuoco e annerisce.','Entrambi quasi inodori – nessun carattere distintivo.','Entrambi su prati/tappeti erbosi magri – l''habitat non distingue; colore e annerimento sono determinanti.','Entrambi con sporata bianca – nessun carattere distintivo.','Annerimento + color fuoco conico-appuntito = igroforo conico (da lasciare). Usare solo le cuffie bianche, non anneribili, con lamelle decorrenti.','{"Igroforo conico: cappello conico-appuntito, vivacemente colorato giallo/arancio/rosso, annerisce al tatto e completamente con l''età","Cuffia verginea: cappello più piccolo, biancastro-avorio, convesso ottuso, NON annerisce","Cuffia verginea con lamelle cerose bianche, distanziate, ampiamente decorrenti; igroforo conico vivacemente colorato e anneribile","Igroforo conico leggermente tossico/sospetto di disturbi gastrointestinali – cuffia verginea commestibile mite"}',false),
('cyclocybe_aegerita','gymnopilus_junonius','en','Pioppino has a lighter, often cracked-areolate brown cap and paler gills; G. junonius is uniformly bright orange with rust-brown gills.','Pioppino pleasantly spicy; G. junonius mealy-rancid with strongly bitter taste.','Pioppino prefers hardwood (especially poplar, often cultivated); G. junonius on stumps and trunk bases of hardwood and conifers.','Pioppino: tobacco-brown spore print. G. junonius: rust-brown spore print – similar, so additionally check bitterness/cap colour.','Taste test (spit out): strongly bitter = rustgill = do not eat. Pioppino is mild and mostly on hardwood.','{"Spore print: pioppino tobacco-/olive-brown, G. junonius pure rust-brown; taste of pioppino mild, G. junonius extremely bitter.","Cap colour: pioppino light ochre to dark brown, often cracked-areolate; G. junonius bright orange rust-yellow.","Stem: pioppino tough-fibrous, pale with a membranous ring; G. junonius thicker, fibrous, orange-tinged.","Pioppino grows mostly on hardwood (especially poplar); G. junonius more often on stumps and trunk bases of conifers and hardwood."}',false),
('cyclocybe_aegerita','gymnopilus_junonius','es','El piopino tiene un sombrero pardo más claro, a menudo agrietado-areolado, y láminas más pálidas; G. junonius es uniformemente naranja brillante con láminas pardo-herrumbre.','Piopino agradablemente especiado; G. junonius harinoso-rancio con sabor fuertemente amargo.','El piopino prefiere la madera de frondosas (sobre todo álamo, a menudo cultivado); G. junonius sobre tocones y bases de troncos de frondosas y coníferas.','Piopino: esporada pardo-tabaco. G. junonius: esporada pardo-herrumbre – similar, por eso verificar además el amargor/color del sombrero.','Prueba de sabor (escupir): fuertemente amargo = gimnopilo = no comer. El piopino es suave y por lo general sobre madera de frondosas.','{"Esporada: piopino pardo-tabaco/oliváceo, G. junonius pardo-herrumbre puro; sabor del piopino suave, G. junonius extremadamente amargo.","Color del sombrero: piopino de ocre claro a pardo oscuro, a menudo agrietado-areolado; G. junonius naranja-amarillo herrumbre brillante.","Pie: piopino tenaz-fibroso, claro con anillo membranoso; G. junonius más grueso, fibroso, con tonos naranja.","El piopino crece en su mayoría sobre madera de frondosas (sobre todo álamo); G. junonius más a menudo sobre tocones y bases de troncos de coníferas y frondosas."}',false),
('cyclocybe_aegerita','gymnopilus_junonius','fr','Le pholiote du peuplier a un chapeau brun plus clair, souvent crevassé-aréolé, et des lamelles plus pâles ; G. junonius est uniformément orange vif avec des lamelles brun rouille.','Pholiote du peuplier agréablement épicé ; G. junonius farineux-rance avec un goût fortement amer.','Pholiote du peuplier préfère le bois de feuillus (surtout peuplier, souvent cultivé) ; G. junonius sur souches et bases de troncs de feuillus et de conifères.','Pholiote du peuplier : sporée brun tabac. G. junonius : sporée brun rouille – semblable, donc vérifier en plus l''amertume/la couleur du chapeau.','Test gustatif (recracher) : fortement amer = gymnopile = ne pas manger. Le pholiote du peuplier est doux et le plus souvent sur bois de feuillus.','{"Sporée : pholiote du peuplier brun tabac/olive, G. junonius brun rouille pur ; goût du pholiote du peuplier doux, G. junonius extrêmement amer.","Couleur du chapeau : pholiote du peuplier ocre clair à brun foncé, souvent crevassé-aréolé ; G. junonius orange-jaune rouille éclatant.","Pied : pholiote du peuplier coriace-fibrilleux, clair avec un anneau membraneux ; G. junonius plus épais, fibrilleux, teinté d''orange.","Pholiote du peuplier pousse le plus souvent sur bois de feuillus (surtout peuplier) ; G. junonius plus fréquent sur souches et bases de troncs de conifères et de feuillus."}',false),
('cyclocybe_aegerita','gymnopilus_junonius','it','Il piopparello ha un cappello bruno più chiaro, spesso screpolato-areolato, e lamelle più pallide; G. junonius è uniformemente arancio brillante con lamelle bruno-ruggine.','Piopparello gradevolmente speziato; G. junonius farinoso-rancido con gusto fortemente amaro.','Il piopparello predilige il legno di latifoglie (soprattutto pioppo, spesso coltivato); G. junonius su ceppi e basi dei tronchi di latifoglie e conifere.','Piopparello: sporata bruno-tabacco. G. junonius: sporata bruno-ruggine – simile, quindi verificare in più amarezza/colore del cappello.','Prova di assaggio (sputare): fortemente amaro = gimnopilo = non mangiare. Il piopparello è mite e per lo più su legno di latifoglie.','{"Sporata: piopparello bruno-tabacco/olivastro, G. junonius bruno-ruggine puro; gusto del piopparello mite, G. junonius estremamente amaro.","Colore del cappello: piopparello da ocra chiaro a bruno scuro, spesso screpolato-areolato; G. junonius arancio-giallo ruggine brillante.","Gambo: piopparello tenace-fibroso, chiaro con anello membranoso; G. junonius più spesso, fibroso, tinto d''arancio.","Il piopparello cresce per lo più su legno di latifoglie (soprattutto pioppo); G. junonius più spesso su ceppi e basi dei tronchi di conifere e latifoglie."}',false),
('disciotis_venosa','gyromitra_gigas','en','The bleach cup is a flat brown bowl lying on the ground with a veined inner surface; the snow morel (giant false morel) is an upright brain-shaped cap.','The bleach cup smells distinctly of chlorine (typical, especially at breakage points); the snow morel smells unspecifically mushroomy.','The bleach cup in spring on moist, calcareous soils/floodplain forest; the snow morel a wood saprobiont – the appearance times overlap.','Both ascomycetes with pale spore print – not a distinguishing feature.','The chlorine smell and the flat cup shape characterise the bleach cup. Leave anything upright and brain-shaped (false morel risk of confusion) and consume both species only well cooked.','{"Bleach cup: bowl-/cup-shaped, spread out flat, inner surface brown with veined-wrinkled surface, short/absent stem, characteristic chlorine smell","Snow morel: upright, tuberous, brain-like convoluted cap on a distinct thick stem, no cup-shaped structure","Bleach cup edible only well cooked (raw indigestible); the snow morel itself contains hardly any gyromitrin, but can scarcely be distinguished from deadly false morel species – therefore avoid","Bleach cup surface veined-ribbed but flat; false morel surface strongly three-dimensional, bulging"}',false),
('disciotis_venosa','gyromitra_gigas','es','La disciotis venosa es un cuenco pardo plano, apoyado en el suelo, con la cara interna venosa; la giromitra gigante es un sombrero erecto en forma de cerebro.','La disciotis venosa huele claramente a cloro (típico, sobre todo en los puntos de rotura); la giromitra gigante huele de forma inespecífica fúngica.','La disciotis venosa en primavera sobre suelos húmedos, ricos en cal/bosque de ribera; la giromitra gigante saprobionte de la madera – los periodos de aparición se solapan.','Ambos ascomicetos con esporada clara – no es un carácter distintivo.','El olor a cloro y la forma plana de cuenco caracterizan a la disciotis venosa. Dejar todo lo erecto en forma de cerebro (riesgo de confusión con giromitras) y consumir ambas especies solo bien cocinadas.','{"Disciotis venosa: en forma de cuenco/copa, extendida plana, cara interna parda con superficie venosa-rugosa, pie corto/ausente, olor a cloro característico","Giromitra gigante: sombrero erecto, tuberoso, sinuoso como un cerebro, sobre un pie grueso definido, sin estructura de cuenco","Disciotis venosa comestible solo bien cocinada (cruda indigesta); la giromitra gigante misma apenas contiene giromitrina, pero apenas se distingue de las especies de giromitra mortales – por eso evitar","Superficie de la disciotis venosa venosa-acostillada pero plana; superficie de la giromitra fuertemente tridimensional, abombada"}',false),
('disciotis_venosa','gyromitra_gigas','fr','Le pézize veiné est une coupe brune plate, posée au sol, à face interne veinée ; le gyromitre géant un chapeau dressé en forme de cerveau.','Le pézize veiné sent nettement le chlore (typique, surtout aux cassures) ; le gyromitre géant sent fongique non spécifique.','Pézize veiné au printemps sur sols humides, riches en calcaire/forêt alluviale ; gyromitre géant comme saprobionte lignicole – la période d''apparition se chevauche.','Les deux ascomycètes à sporée claire – pas un critère de séparation.','L''odeur de chlore et la forme plate-en coupe caractérisent le pézize veiné. Laisser sur place tout ce qui est dressé en forme de cerveau (risque de confusion avec les gyromitres) et ne consommer les deux espèces que bien cuites.','{"Pézize veiné : en forme de coupe/cupule, étalé à plat, face interne brune à surface veinée-ridée, pied court/absent, odeur de chlore caractéristique","Gyromitre géant : chapeau dressé, bosselé-circonvolué en forme de cerveau sur un pied épais net, pas de structure en coupe","Pézize veiné comestible seulement bien cuit (cru mal toléré) ; gyromitre géant lui-même contenant peu de gyromitrine, mais à peine séparable des espèces de gyromitres mortelles – donc à éviter","Surface du pézize veiné veinée-côtelée mais plate ; surface du gyromitre fortement tridimensionnelle bombée"}',false),
('disciotis_venosa','gyromitra_gigas','it','Il disciotis venato è una coppa bruna piatta, adagiata al suolo, con faccia interna venata; la gyromitra gigante è un cappello eretto a forma di cervello.','Il disciotis venato odora nettamente di cloro (tipico, specie nei punti di rottura); la gyromitra gigante odora in modo aspecifico fungino.','Il disciotis venato in primavera su suoli umidi, ricchi di calcare/bosco golenale; la gyromitra gigante saprobionte del legno – i periodi di comparsa si sovrappongono.','Entrambi ascomiceti con sporata chiara – nessun carattere distintivo.','L''odore di cloro e la forma piatta a coppa caratterizzano il disciotis venato. Lasciare tutto ciò che è eretto a forma di cervello (rischio di confusione con le gyromitre) e consumare entrambe le specie solo ben cotte.','{"Disciotis venato: a forma di coppa/cupola, disteso piatto, faccia interna bruna con superficie venata-rugosa, gambo corto/assente, odore di cloro caratteristico","Gyromitra gigante: cappello eretto, tuberoso, sinuoso a forma di cervello, su un gambo spesso distinto, senza struttura a coppa","Disciotis venato commestibile solo ben cotto (crudo indigesto); la gyromitra gigante stessa contiene a malapena giromitrina, ma si distingue a malapena dalle gyromitre mortali – quindi da evitare","Superficie del disciotis venato venata-costoluta ma piatta; superficie della gyromitra fortemente tridimensionale, bombata"}',false),
('gymnopus_dryophilus','gymnopus_peronatus','en','The wood woollyfoot looks tougher, leather-brown to yellow-brown, with a distinctly strigose-felted stem base; the russet toughshank is more delicate with a glabrous stem.','Both rather unspecifically mushroomy; the wood woollyfoot often smells vinegary-sour when rubbed and tastes burning-acrid – the acrid taste (sample, spit out) is the decisive distinguishing feature.','Both in hardwood/conifer forest litter, often in troops – habitat does not distinguish; the wood woollyfoot prefers drier litter and appears longer into autumn.','Both with white to cream spore print – not a distinguishing feature.','Small taste test (chew, do NOT swallow, spit out): if after a short time it burns peppery-acrid, it is the suspect wood woollyfoot. Only collect small brown litter mushrooms if you know them unambiguously.','{"Wood woollyfoot: taste acrid-burning peppery (the taste test burns after a short time), stem base strigose-felted white-felted, flesh tough-leathery","Russet toughshank: taste mild, stem glabrous/smooth without strigose base, stem often yellowish-reddish","Wood woollyfoot often in troops in dense hardwood litter, appears longer into autumn; russet toughshank cap hygrophanous red-brown fading","Wood woollyfoot regarded as inedible to mildly poisonous (acrid, stomach-irritating, indications of hydrocyanic compounds) – russet toughshank mildly edible"}',false),
('gymnopus_dryophilus','gymnopus_peronatus','es','La colibia ardiente parece más tenaz, pardo-cuero a pardo-amarillo, con base del pie marcadamente estrigosa-afieltrada; la colibia de los robles es más delicada con pie glabro.','Ambas de olor fúngico más bien inespecífico; la colibia ardiente huele a menudo al frotarla a vinagre-ácido y sabe ardiente-acre – el sabor acre (prueba, escupir) es el carácter distintivo decisivo.','Ambas en la hojarasca de bosque de frondosas/coníferas, a menudo en grupos – el hábitat no distingue; la colibia ardiente prefiere hojarasca más seca y aparece más tiempo entrado el otoño.','Ambas con esporada de blanca a crema – no es un carácter distintivo.','Pequeña prueba de sabor (masticar, NO tragar, escupir): si tras un breve momento arde a pimienta-acre, es la sospechosa colibia ardiente. Recoger pequeños hongos pardos de hojarasca solo si se conocen inequívocamente.','{"Colibia ardiente: sabor acre-ardiente a pimienta (la prueba de sabor arde tras un breve momento), base del pie estrigosa-afieltrada blanco-afieltrada, carne tenaz-coriácea","Colibia de los robles: sabor suave, pie glabro/liso sin base estrigosa, pie a menudo amarillento-rojizo","Colibia ardiente a menudo en grupos en densa hojarasca de frondosas, aparece más tiempo entrado el otoño; colibia de los robles sombrero higrófano pardo-rojo que se decolora","Colibia ardiente considerada no comestible a levemente tóxica (acre, irritante para el estómago, indicios de compuestos cianhídricos) – colibia de los robles comestible suave"}',false),
('gymnopus_dryophilus','gymnopus_peronatus','fr','Le collybie à pied feutré paraît plus coriace, brun-cuir à jaune-brun, avec une base du pied nettement strigueuse-feutrée ; le collybie des chênes est plus délicat avec un pied glabre.','Les deux plutôt fongiques non spécifiques ; le collybie à pied feutré sent souvent acide-vinaigré au frottement et a un goût brûlant-âcre – le goût âcre (échantillon, recracher) est le critère de séparation décisif.','Les deux dans la litière de forêt de feuillus/conifères, souvent en troupe – l''habitat ne sépare pas ; le collybie à pied feutré préfère les litières plus sèches et apparaît plus tard dans l''automne.','Les deux à sporée blanche à crème – pas un critère de séparation.','Petit échantillon gustatif (mâcher, NE PAS avaler, recracher) : si après peu de temps cela brûle de façon poivrée-âcre, c''est le collybie à pied feutré suspect de toxicité. Ne récolter les petits champignons bruns de litière que si on les connaît sans équivoque.','{"Collybie à pied feutré : goût âcre-brûlant poivré (l''échantillon gustatif brûle après peu de temps), base du pied strigueuse-feutrée blanc-feutrée, chair coriace-cuir","Collybie des chênes : goût doux, pied glabre/lisse sans base strigueuse, pied souvent jaunâtre-rougeâtre","Collybie à pied feutré souvent en troupe dans une litière de feuillus dense, apparaît plus tard dans l''automne ; chapeau du collybie des chênes hygrophane brun-rouge se décolorant","Collybie à pied feutré considéré comme non comestible à faiblement toxique (âcre, irritant pour l''estomac, indices de composés cyanogènes) – collybie des chênes doux comestible"}',false),
('gymnopus_dryophilus','gymnopus_peronatus','it','La gymnopus bruciante appare più tenace, bruno-cuoio-bruno-giallo, con base del gambo nettamente strigosa-feltrata; la gymnopus amica dei boschi è più delicata con gambo glabro.','Entrambe d''odore fungino piuttosto aspecifico; la gymnopus bruciante odora spesso allo sfregamento di aceto-acidulo e ha gusto bruciante-acre – il gusto acre (assaggio, sputare) è il carattere distintivo decisivo.','Entrambe nella lettiera di bosco di latifoglie/conifere, spesso in gruppi – l''habitat non distingue; la gymnopus bruciante predilige lettiere più asciutte e compare più a lungo nell''autunno.','Entrambe con sporata da bianca a crema – nessun carattere distintivo.','Piccola prova di assaggio (masticare, NON deglutire, sputare): se dopo poco brucia pepato-acre, è la gymnopus bruciante sospetta. Raccogliere i piccoli funghi bruni di lettiera solo se li si conosce con certezza.','{"Gymnopus bruciante: gusto acre-bruciante pepato (l''assaggio brucia dopo poco), base del gambo strigosa-feltrata bianco-feltrata, carne tenace-coriacea","Gymnopus amica dei boschi: gusto mite, gambo glabro/liscio senza base strigosa, gambo spesso giallastro-rossastro","Gymnopus bruciante spesso in gruppi in fitta lettiera di latifoglie, compare più a lungo nell''autunno; gymnopus amica dei boschi cappello igrofano bruno-rosso che impallidisce","Gymnopus bruciante considerata non commestibile a leggermente tossica (acre, irritante per lo stomaco, indizi di composti cianidrici) – gymnopus amica dei boschi commestibile mite"}',false),
('hallimasch','gymnopilus_junonius','en','Honey fungus has a honey- to brown-coloured cap with dark scales and a white ring; G. junonius is bright orange rust-yellow with rust-brown gills.','Honey fungus mild-mushroomy in smell; G. junonius mealy-rancid and very bitter in taste.','Both clustered on/around wood and roots; honey fungus parasitic on living trees and stumps, G. junonius on stumps and trunk bases.','Honey fungus: white spore print. G. junonius: rust-brown spore print – this is the decisive distinguishing feature.','Make a spore print: white = possibly edible species (honey fungus only well cooked, raw poisonous!), rust-brown = rustgill = discard. Additionally, taste test: bitter = poisonous.','{"Spore print: honey fungus WHITE to cream, G. junonius rust-brown – the spore print distinguishes reliably.","Gills: honey fungus whitish to pale flesh-pink, decurrent on the stem; G. junonius yellow when young, later rust-brown.","Taste: G. junonius extremely bitter; honey fungus (raw poisonous!) mild to slightly tart, must be thoroughly cooked.","Honey fungus often has dark scales on a pale cap and a white ring; G. junonius uniformly orange rust-yellow."}',false),
('hallimasch','gymnopilus_junonius','es','La armilaria tiene sombrero de miel a pardo con pequeñas escamas oscuras y un anillo blanco; G. junonius es naranja-amarillo herrumbre brillante con láminas pardo-herrumbre.','La armilaria de olor suave-fúngico; G. junonius harinoso-rancio y muy amargo al gusto.','Ambos en grupos sobre/alrededor de la madera y las raíces; la armilaria parásita de árboles vivos y tocones, G. junonius sobre tocones y bases de troncos.','Armilaria: esporada blanca. G. junonius: esporada pardo-herrumbre – este es el carácter distintivo decisivo.','Hacer una esporada: blanca = especie posiblemente comestible (armilaria solo bien cocinada, ¡cruda tóxica!), pardo-herrumbre = gimnopilo = desechar. Además, prueba de sabor: amargo = tóxico.','{"Esporada: armilaria BLANCA a crema, G. junonius pardo-herrumbre – la esporada distingue con seguridad.","Láminas: armilaria blanquecinas a rosa carne pálido, decurrentes sobre el pie; G. junonius de joven amarillas, luego pardo-herrumbre.","Sabor: G. junonius extremadamente amargo; armilaria (¡cruda tóxica!) suave a ligeramente áspera, debe cocinarse bien.","La armilaria tiene a menudo escamas oscuras sobre sombrero claro y un anillo blanco; G. junonius uniformemente naranja-amarillo herrumbre."}',false),
('hallimasch','gymnopilus_junonius','fr','Armillaire au chapeau miel à brun avec de petites écailles sombres et un anneau blanc ; G. junonius orange-jaune rouille éclatant avec des lamelles brun rouille.','Armillaire doux-fongique ; G. junonius farineux-rance et très amer au goût.','Les deux en touffes sur/autour du bois et des racines ; armillaire parasite sur arbres vivants et souches, G. junonius sur souches et bases de troncs.','Armillaire : sporée blanche. G. junonius : sporée brun rouille – c''est le critère de séparation décisif.','Faire une sporée : blanche = espèce éventuellement comestible (armillaire seulement bien cuit, cru toxique !), brun rouille = gymnopile = jeter. En plus, test gustatif : amer = toxique.','{"Sporée : armillaire BLANCHE à crème, G. junonius brun rouille – la sporée sépare sûrement.","Lamelles : armillaire blanchâtre à rose-chair pâle, décurrentes au pied ; G. junonius jeune jaune, plus tard brun rouille.","Goût : G. junonius extrêmement amer ; armillaire (cru toxique !) doux à légèrement âpre, doit être bien cuit.","L''armillaire a souvent de petites écailles sombres sur un chapeau clair et un anneau blanc ; G. junonius uniformément orange-jaune rouille."}',false),
('hallimasch','gymnopilus_junonius','it','Il chiodino ha cappello dal miele al bruno con piccole squame scure e un anello bianco; G. junonius è arancio-giallo ruggine brillante con lamelle bruno-ruggine.','Il chiodino dall''odore mite-fungino; G. junonius farinoso-rancido e molto amaro al gusto.','Entrambi cespitosi su/attorno al legno e alle radici; il chiodino parassita di alberi vivi e ceppi, G. junonius su ceppi e basi dei tronchi.','Chiodino: sporata bianca. G. junonius: sporata bruno-ruggine – è il carattere distintivo decisivo.','Fare una sporata: bianca = specie possibilmente commestibile (chiodino solo ben cotto, crudo tossico!), bruno-ruggine = gimnopilo = da buttare. Inoltre, prova di assaggio: amaro = tossico.','{"Sporata: chiodino BIANCA a crema, G. junonius bruno-ruggine – la sporata distingue con sicurezza.","Lamelle: chiodino biancastre a rosa carne pallido, decorrenti sul gambo; G. junonius da giovani gialle, poi bruno-ruggine.","Gusto: G. junonius estremamente amaro; chiodino (crudo tossico!) mite a leggermente aspro, deve essere ben cotto.","Il chiodino ha spesso squame scure su cappello chiaro e un anello bianco; G. junonius uniformemente arancio-giallo ruggine."}',false),
('hypholoma_capnoides','hypholoma_lateritium','en','Edible conifer tuft with grey/grey-blue gills and a honey-ochre cap; brick tuft (brick cap) with olive-grey to olive-grey-brown gills and a brick-red cap centre. Caution: greenish-yellow gills mean the deadly sulphur tuft with green gills, not the brick tuft.','Both mushroomy-mild in smell; the brick tuft, however, tastes distinctly bitter (sample, spit out).','Conifer tuft on conifer stumps, brick tuft predominantly on hardwood (beech, oak).','In both purple-brown to violet-brown — unsuitable as a distinguishing feature.','Never identify tufts without a taste test (spit out): bitter = leave it. Conifer substrate + mild taste argue for the edible conifer tuft. Greenish-yellow gills indicate the deadly sulphur tuft with green gills.','{"Conifer tuft (edible) has grey to grey-blue gills; the brick tuft has olive-grey to olive-grey-brown gills (NOT greenish-yellow — that would be the deadly-poisonous sulphur tuft with green gills, Hypholoma fasciculare)","Cap colour of the edible one lighter, honey-yellow to ochre-brown; in the brick tuft brick-red with a lighter margin","Taste of the edible one mild, the brick tuft bitter","Conifer tuft grows on conifers (spruce/pine), brick tuft prefers hardwood (beech/oak)","Spore print in both purple-brown — not a distinguishing feature; therefore pay attention to gill hue, substrate and taste"}',false),
('hypholoma_capnoides','hypholoma_lateritium','es','Hifoloma comestible con láminas grises/gris-azuladas y sombrero miel-ocre; hifoloma color ladrillo con láminas gris-oliva a gris-pardo oliváceo y centro del sombrero color ladrillo. Atención: láminas verde-amarillentas significan el hifoloma de láminas verdes mortal, no el hifoloma color ladrillo.','Ambos de olor fúngico-suave; el hifoloma color ladrillo, sin embargo, sabe claramente amargo (prueba, escupir).','Hifoloma de láminas grises sobre tocones de coníferas, hifoloma color ladrillo predominantemente sobre madera de frondosas (haya, roble).','En ambos púrpura-pardo a pardo-violáceo — inadecuado como carácter distintivo.','Nunca determinar los hifolomas sin prueba de sabor (escupir): amargo = dejarlo. Sustrato de coníferas + sabor suave hablan a favor del hifoloma de láminas grises comestible. Láminas verde-amarillentas indican el hifoloma de láminas verdes mortal.','{"El hifoloma de láminas grises (comestible) tiene láminas grises a gris-azuladas; el hifoloma color ladrillo tiene láminas gris-oliva a gris-pardo oliváceo (NO verde-amarillentas — eso sería el hifoloma de láminas verdes mortalmente tóxico, Hypholoma fasciculare)","Color del sombrero del comestible más claro, amarillo miel a pardo ocre; en el hifoloma color ladrillo color ladrillo con margen más claro","Sabor del comestible suave, el hifoloma color ladrillo amargo","El hifoloma de láminas grises crece sobre coníferas (abeto rojo/pino), el hifoloma color ladrillo prefiere la madera de frondosas (haya/roble)","Esporada en ambos púrpura-pardo — no es un carácter distintivo; por eso prestar atención al matiz de las láminas, al sustrato y al sabor"}',false),
('hypholoma_capnoides','hypholoma_lateritium','fr','Hypholome comestible à lames couleur de fumée avec des lamelles gris/gris-bleu et un chapeau miel-ocre ; hypholome couleur de brique avec des lamelles olive-gris à olive-gris-brun et un centre du chapeau couleur de brique. Attention : des lamelles vert-jaunâtre signifient l''hypholome en touffes mortel, pas l''hypholome couleur de brique.','Les deux fongiques-doux à l''odeur ; l''hypholome couleur de brique a cependant un goût nettement amer (échantillon gustatif à recracher).','Hypholome à lames couleur de fumée sur souches de conifères, hypholome couleur de brique surtout sur bois de feuillus (hêtre, chêne).','Chez les deux brun pourpre à brun violet — non adapté comme critère de séparation.','Ne jamais déterminer les hypholomes sans échantillon gustatif (à recracher) : amer = laisser sur place. Substrat bois de conifères + goût doux plaident pour l''hypholome à lames couleur de fumée comestible. En cas de lamelles vert-jaunâtre, il s''agit de l''hypholome en touffes mortel.','{"Hypholome à lames couleur de fumée (comestible) a des lamelles grises à gris-bleu ; l''hypholome couleur de brique a des lamelles gris-olive à olive-gris-brun (PAS vert-jaunâtre — ce serait l''hypholome en touffes mortellement toxique, Hypholoma fasciculare)","Couleur du chapeau du comestible plus claire miel-jaune à brun-ocre, chez l''hypholome couleur de brique couleur de brique avec un bord plus clair","Goût du comestible doux, l''hypholome couleur de brique amer","Hypholome à lames couleur de fumée pousse sur bois de conifères (épicéa/pin), hypholome couleur de brique préfère le bois de feuillus (hêtre/chêne)","Sporée chez les deux brun pourpre — pas un critère distinctif ; donc faire attention à la nuance des lamelles, au substrat et au goût"}',false),
('hypholoma_capnoides','hypholoma_lateritium','it','Ipoloma commestibile con lamelle grigie/grigio-blu e cappello miele-ocra; ipoloma color mattone con lamelle grigio-oliva a grigio-bruno olivastro e centro del cappello color mattone. Attenzione: lamelle verde-giallastre indicano l''ipoloma fascicolare mortale a lamelle verdi, non l''ipoloma color mattone.','Entrambi d''odore fungino-mite; l''ipoloma color mattone ha però un gusto nettamente amaro (assaggio da sputare).','Ipoloma a lamelle grigie su ceppi di conifere, ipoloma color mattone prevalentemente su legno di latifoglie (faggio, quercia).','In entrambi porpora-bruno a bruno-violaceo — inadatto come carattere distintivo.','Non determinare mai gli ipolomi senza prova di assaggio (sputare): amaro = da lasciare. Substrato di conifere + gusto mite parlano per l''ipoloma a lamelle grigie commestibile. Lamelle verde-giallastre indicano l''ipoloma fascicolare mortale a lamelle verdi.','{"L''ipoloma a lamelle grigie (commestibile) ha lamelle grigie a grigio-blu; l''ipoloma color mattone ha lamelle grigio-oliva a grigio-bruno olivastro (NON verde-giallastre — sarebbe l''ipoloma fascicolare mortalmente tossico a lamelle verdi, Hypholoma fasciculare)","Colore del cappello del commestibile più chiaro, giallo miele a bruno ocra, nell''ipoloma color mattone color mattone con margine più chiaro","Gusto del commestibile mite, l''ipoloma color mattone amaro","L''ipoloma a lamelle grigie cresce su conifere (abete rosso/pino), l''ipoloma color mattone predilige il legno di latifoglie (faggio/quercia)","Sporata in entrambi porpora-bruno — nessun carattere distintivo; quindi fare attenzione alla tonalità delle lamelle, al substrato e al gusto"}',false),
('infundibulicybe_geotropa','ampulloclitocybe_clavipes','en','The large trooping funnel is cream-white to ochre with a central umbo and a firm stem vs. the small clavipes, white-grey to grey-brown with a soft clavate base.','The trooping funnel smells pleasantly spicy-sweet; clavipes faintly fruity.','The trooping funnel in fairy rings on grassy sites/woodland edges; clavipes in mixed and coniferous forest.','Both with white to cream spore print; not distinguishing.','With small, soft funnels with a spongy-clavate stem, as a rule keep your hands off and never combine with alcohol.','{"The trooping funnel is much larger and more robust (cap up to about 20 cm) with firm-tough, dry flesh and a firm, NON-spongy stem; clavipes small with a soft, watery-spongy clavate stem base.","The trooping funnel has a typically central flat umbo in an otherwise depressed cap and cream-white to ochre colouring; clavipes white-grey to grey-brown with a darker centre.","The trooping funnel grows mostly in large fairy rings/rows at woodland edges and grassy sites; clavipes rather scattered in the forest.","Clavipes is poisonous with alcohol (coprine syndrome); the trooping funnel is a good edible when cooked."}',false),
('infundibulicybe_geotropa','ampulloclitocybe_clavipes','es','El gran platera blanco-crema a ocre con mamelón central y pie firme vs. el pequeño clavipes blanco-gris a gris-pardo con base claviforme blanda.','La platera huele agradablemente especiada-dulzona; el clavipes débilmente afrutado.','La platera en corros de brujas sobre lugares herbosos/bordes de bosque; el clavipes en bosque mixto y de coníferas.','Ambos con esporada de blanca a crema; no distintivo.','Ante pequeños clitocibes blandos con pie esponjoso-claviforme, por principio no tocar y nunca combinar con alcohol.','{"La platera es mucho más grande y robusta (sombrero hasta unos 20 cm) con carne firme-tenaz, seca, y pie firme, NO esponjoso; el clavipes pequeño con base del pie claviforme blanda, acuosa-esponjosa.","La platera tiene un mamelón central típicamente plano en un sombrero por lo demás deprimido y coloración blanco-crema a ocre; el clavipes blanco-gris a gris-pardo con centro más oscuro.","La platera crece en su mayoría en grandes corros de brujas/hileras en bordes de bosque y lugares herbosos; el clavipes más bien disperso en el bosque.","El clavipes es tóxico con alcohol (síndrome coprínico); la platera es un buen comestible una vez cocinada."}',false),
('infundibulicybe_geotropa','ampulloclitocybe_clavipes','fr','Grand clitocybe géotrope crème-blanc-ocré avec un mamelon central et un pied ferme vs. petit clavipes blanc-gris à gris-brun avec une base molle en massue.','Clitocybe géotrope agréablement épicé-sucré ; clavipes faiblement fruité.','Clitocybe géotrope en ronds de sorcières sur stations herbeuses/lisières de forêt ; clavipes en forêt mixte et de conifères.','Les deux à sporée blanche à crème ; non discriminant.','Pour les petits clitocybes mous à pied spongieux en massue, par principe ne pas toucher et ne jamais combiner avec de l''alcool.','{"Le clitocybe géotrope est bien plus grand et robuste (chapeau jusqu''à env. 20 cm) avec une chair ferme-coriace, sèche, et un pied ferme, NON spongieux ; clavipes petit avec une base du pied molle, aqueuse-spongieuse, en massue.","Le clitocybe géotrope a un mamelon central typique, plat, dans un chapeau par ailleurs déprimé et une coloration crème-blanc-ocré ; clavipes blanc-gris à gris-brun avec un centre plus sombre.","Le clitocybe géotrope pousse le plus souvent en grands ronds de sorcières/rangées aux lisières de forêt et stations herbeuses ; clavipes plutôt dispersé en forêt.","clavipes toxique avec l''alcool (syndrome coprinien) ; le clitocybe géotrope cuit est un bon comestible."}',false),
('infundibulicybe_geotropa','ampulloclitocybe_clavipes','it','Il grande clitocybe geotropo bianco-crema-ocra con umbone centrale e gambo sodo vs. il piccolo clavipes bianco-grigio a grigio-bruno con base clavata molle.','Il clitocybe geotropo profuma gradevolmente speziato-dolciastro; il clavipes debolmente fruttato.','Il clitocybe geotropo in cerchi delle streghe su stazioni erbose/margini boschivi; il clavipes in bosco misto e di conifere.','Entrambi con sporata da bianca a crema; non distintivo.','Di fronte ai piccoli clitocybe molli con gambo spugnoso-clavato, per principio non toccare e mai combinare con l''alcol.','{"Il clitocybe geotropo è molto più grande e robusto (cappello fino a circa 20 cm) con carne soda-tenace, asciutta, e gambo sodo, NON spugnoso; il clavipes piccolo con base del gambo clavata molle, acquosa-spugnosa.","Il clitocybe geotropo ha un umbone centrale tipicamente piatto in un cappello per il resto depresso e colorazione bianco-crema-ocra; il clavipes bianco-grigio a grigio-bruno con centro più scuro.","Il clitocybe geotropo cresce per lo più in grandi cerchi delle streghe/file ai margini boschivi e su stazioni erbose; il clavipes piuttosto sparso nel bosco.","Il clavipes è tossico con l''alcol (sindrome coprinica); il clitocybe geotropo è un buon commestibile da cotto."}',false),
('infundibulicybe_gibba','ampulloclitocybe_clavipes','en','The club-shaped, swollen stem base is the key feature of clavipes; the ochre-brown funnel cap (gibba) has a slender, even stem with a central cap umbo.','The ochre-brown funnel cap is almost odourless to faintly sweetish; clavipes is pleasantly mushroomy with a faint fruity note.','Both in deciduous/coniferous/mixed forest (summer to late autumn); habitat is not a reliable distinguishing feature.','Both have a white spore print; not distinguishing.','Discard any whitish-grey funnel cap with a thick, club-shaped, spongy stem base, and never eat it together with alcohol.','{"Ochre-brown funnel cap: stem base NOT club-thickened, evenly slender/cylindrical; clavipes has a strikingly club-swollen, inflated, spongy-watery stem base.","The cap of the ochre-brown is warm ochre/flesh-brown with a small central umbo/papilla; clavipes is whitish-grey to grey-brown with a distinctly darker cap centre and a pale, long-inrolled margin.","The flesh of the ochre-brown is thin, tough-elastic and dry; clavipes flesh is soft, spongy, strongly water-soaked when wet.","clavipes causes a coprine/acetaldehyde syndrome in combination with alcohol; the ochre-brown is edible and alcohol-tolerant."}',false),
('infundibulicybe_gibba','ampulloclitocybe_clavipes','es','La base del pie engrosada en maza es el carácter clave de clavipes; el clitocibe acopado ocre-pardo (gibba) tiene un pie esbelto y regular con umbón central en el sombrero.','El clitocibe ocre-pardo es casi inodoro o ligeramente dulzón; clavipes tiene olor agradable a hongo con una débil nota afrutada.','Ambos en bosque de frondosas/coníferas/mixto (de verano a finales de otoño); el hábitat no es un carácter distintivo fiable.','Ambos con esporada blanca; no distintivo.','Descartar todo clitocibe blanquecino-gris con base del pie gruesa, en maza y esponjosa, y no consumirlo nunca junto con alcohol.','{"Clitocibe ocre-pardo: base del pie NO engrosada en maza, regularmente esbelta/cilíndrica; clavipes tiene una base del pie llamativamente engrosada en maza, hinchada, esponjosa-acuosa.","El sombrero del ocre-pardo es ocre/pardo-carne cálido con un pequeño umbón/papila central; clavipes es blanco-grisáceo a gris-pardo con el centro del sombrero claramente más oscuro y un margen claro largo tiempo enrollado.","La carne del ocre-pardo es delgada, tenaz-elástica y seca; la carne de clavipes es blanda, esponjosa, fuertemente empapada de agua con la humedad.","clavipes provoca, en combinación con alcohol, un síndrome coprínico/de acetaldehído; el ocre-pardo es comestible y tolerante al alcohol."}',false),
('infundibulicybe_gibba','ampulloclitocybe_clavipes','fr','La base du pied en massue, renflée, est le critère clé de clavipes ; le clitocybe en entonnoir a un pied élancé, régulier, avec un mamelon central sur le chapeau.','Clitocybe en entonnoir presque inodore à légèrement sucré ; clavipes fongique-agréable avec une faible note fruitée.','Les deux en forêt de feuillus/conifères/mixte (été à fin d''automne) ; pas de critère de séparation fiable via l''habitat.','Les deux à sporée blanche ; non discriminant.','Écarter tout clitocybe blanchâtre-gris à base du pied épaisse en massue, spongieuse, et ne jamais le consommer avec de l''alcool.','{"Clitocybe en entonnoir : base du pied NON épaissie en massue, régulièrement élancée/cylindrique ; clavipes a une base du pied visiblement renflée en massue, spongieuse-aqueuse.","Le chapeau du clitocybe en entonnoir est ocre/brun-chair chaud avec un petit mamelon/papille central ; clavipes blanc-grisâtre à gris-brun avec un centre nettement plus sombre et un bord clair longtemps enroulé.","La chair du clitocybe en entonnoir est mince, coriace-élastique et sèche ; la chair de clavipes molle, spongieuse, fortement imbibée d''eau par temps humide.","clavipes provoque en liaison avec l''alcool un syndrome coprinien/acétaldéhyde ; le clitocybe en entonnoir est comestible et tolérant à l''alcool."}',false),
('infundibulicybe_gibba','ampulloclitocybe_clavipes','it','La base del gambo ingrossata a clava è il carattere chiave di clavipes; il clitocybe a imbuto ocra-bruno ha un gambo slanciato e regolare con umbone centrale sul cappello.','Il clitocybe ocra-bruno è quasi inodore o leggermente dolciastro; clavipes ha odore gradevole di fungo con una debole nota fruttata.','Entrambi in bosco di latifoglie/conifere/misto (dall''estate al tardo autunno); l''habitat non è un carattere distintivo affidabile.','Entrambi con sporata bianca; non distintivo.','Scartare ogni clitocybe biancastro-grigio con base del gambo grossa, a clava e spugnosa, e non consumarlo mai insieme ad alcol.','{"Clitocybe ocra-bruno: base del gambo NON ingrossata a clava, regolarmente slanciata/cilindrica; clavipes ha una base del gambo vistosamente ingrossata a clava, gonfia, spugnosa-acquosa.","Il cappello dell''ocra-bruno è ocra/bruno-carne caldo con un piccolo umbone/papilla centrale; clavipes è bianco-grigiastro fino a grigio-bruno con il centro del cappello nettamente più scuro e un margine chiaro a lungo arrotolato.","La carne dell''ocra-bruno è sottile, tenace-elastica e asciutta; la carne di clavipes è molle, spugnosa, fortemente imbevuta d''acqua con l''umidità.","clavipes provoca, in combinazione con l''alcol, una sindrome coprinica/da acetaldeide; l''ocra-bruno è commestibile e tollerante all''alcol."}',false),
('infundibulicybe_gibba','clitocybe_fragrans','en','Warm ochre-brown, deeply funnel-shaped gibba with a small point vs. pale grey, small fragrans with a striate margin.','fragrans smells of aniseed; the ochre-brown funnel cap is nearly odourless - a clear distinguishing feature.','Both widespread in woodland; habitat is not a reliable distinguishing feature.','Both have a white spore print; not distinguishing.','Lack of odour argues against fragrans, but as a rule leave small aniseed-smelling funnel caps alone (muscarine).','{"The ochre-brown funnel cap is warm ochre/flesh-brown, larger, with a deeply funnel-shaped cap and a small central point; fragrans is small, pale grey-brown and watery-pale.","fragrans smells distinctly of aniseed and contains muscarine; the ochre-brown funnel cap is nearly odourless and edible.","The cap margin of fragrans is translucently striate; in the ochre-brown it is non-striate.","Ochre-brown with tough-elastic, thin flesh; fragrans flesh fragile and thin."}',false),
('infundibulicybe_gibba','clitocybe_fragrans','es','gibba ocre-pardo cálido, profundamente acopado con pequeña punta, frente a fragrans gris pálido, pequeño, con margen estriado.','fragrans huele a anís; el clitocibe ocre-pardo es casi inodoro - un carácter distintivo claro.','Ambos ampliamente extendidos en los bosques; el hábitat no es un carácter distintivo fiable.','Ambos con esporada blanca; no distintivo.','La ausencia de olor descarta fragrans, pero por regla general dejar en su sitio los pequeños clitocibes con olor a anís (muscarina).','{"El clitocibe ocre-pardo es de un ocre/pardo-carne cálido, más grande, con sombrero profundamente acopado y una pequeña punta central; fragrans es pequeño, gris-pardo pálido y claro-acuoso.","fragrans huele claramente a anís y contiene muscarina; el clitocibe ocre-pardo es casi inodoro y comestible.","El margen del sombrero de fragrans es estriado por transparencia; en el ocre-pardo es no estriado.","Ocre-pardo con carne tenaz-elástica y delgada; carne de fragrans frágil y delgada."}',false),
('infundibulicybe_gibba','clitocybe_fragrans','fr','gibba ocre-brun chaud, profondément en entonnoir avec un petit mamelon vs. fragrans gris pâle, petit, à bord strié.','fragrans d''anis ; clitocybe en entonnoir presque inodore - un critère de séparation clair.','Les deux largement répandus en forêt ; pas de critère de séparation fiable via l''habitat.','Les deux à sporée blanche ; non discriminant.','L''absence d''odeur va contre fragrans, mais laisser sur place en général les petits clitocybes à odeur d''anis (muscarine).','{"Le clitocybe en entonnoir est ocre/brun-chair chaud, plus grand, avec un chapeau profondément en entonnoir et un petit mamelon central ; fragrans est petit, gris-brun pâle et aqueux clair.","fragrans sent nettement l''anis et contient de la muscarine ; le clitocybe en entonnoir est presque inodore et comestible.","Bord du chapeau strié par transparence chez fragrans ; non strié chez le clitocybe en entonnoir.","Clitocybe en entonnoir à chair coriace-élastique, mince ; chair de fragrans fragile et mince."}',false),
('infundibulicybe_gibba','clitocybe_fragrans','it','gibba ocra-bruno caldo, profondamente a imbuto con piccolo umbone, contro fragrans grigio pallido, piccolo, con margine striato.','fragrans odora di anice; il clitocybe ocra-bruno è pressoché inodore - un carattere distintivo netto.','Entrambi ampiamente diffusi nei boschi; l''habitat non è un carattere distintivo affidabile.','Entrambi con sporata bianca; non distintivo.','L''assenza di odore esclude fragrans, ma in generale lasciare sul posto i piccoli clitocybe con odore di anice (muscarina).','{"Il clitocybe ocra-bruno è di un ocra/bruno-carne caldo, più grande, con cappello profondamente a imbuto e un piccolo umbone centrale; fragrans è piccolo, grigio-bruno pallido e chiaro-acquoso.","fragrans odora nettamente di anice e contiene muscarina; il clitocybe ocra-bruno è pressoché inodore e commestibile.","Il margine del cappello di fragrans è striato per trasparenza; nell''ocra-bruno è non striato.","Ocra-bruno con carne tenace-elastica e sottile; carne di fragrans fragile e sottile."}',false),
('kuehneromyces_mutabilis','gymnopilus_junonius','en','G. junonius is distinctly larger, uniformly orange and finely scaly; the sheathed woodtuft is small with a hygrophanous two-coloured cap and a brown-scaly stem below the ring.','Sheathed woodtuft pleasantly mushroomy; G. junonius mealy-rancid, plus an extremely bitter taste.','Both clustered on wood/stumps; G. junonius on stumps of broadleaf and conifer trees as well as at trunk bases, the sheathed woodtuft mostly on broadleaf stumps.','Both rust-brown - the spore colour does NOT separate these two. IMPORTANT: the real deadly risk for the sheathed woodtuft is the deadly galerina (Galerina marginata), which also drops a rust-brown spore print - a separate, life-threatening confusion topic.','Bitter taste (spit out the taste test) and conspicuous size = rustgill = throw away. Only collect the sheathed woodtuft if the identification is absolutely certain - the deadly galerina risk must be considered separately.','{"Gymnopilus junonius grows very large (cap 5-15 cm) and in dense clusters; the sheathed woodtuft stays small (cap 2-6 cm).","Taste: G. junonius extremely bitter; sheathed woodtuft mild.","Cap surface: the sheathed woodtuft has a two-coloured, hygrophanous cap with a translucently striate margin; G. junonius uniformly orange-rust-yellow, finely scaly.","Stem: sheathed woodtuft distinctly brown-scaly/snake-patterned below the ring; G. junonius fibrillose without snake-patterning.","Caution: both have a rust-brown spore print - the spore print does NOT separate them here, so check size/bitterness."}',false),
('kuehneromyces_mutabilis','gymnopilus_junonius','es','G. junonius es claramente más grande, uniformemente naranja y finamente escamoso; la seta de chopo (kuehneromyces) es pequeña, con sombrero higrófano bicolor y pie pardo-escamoso bajo el anillo.','Seta de chopo con olor agradable a hongo; G. junonius harinoso-rancio, además con sabor extremadamente amargo.','Ambos cespitosos sobre madera/tocones; G. junonius sobre tocones de frondosas y coníferas así como en la base de troncos, la seta de chopo sobre todo en tocones de frondosas.','Ambos pardo-herrumbre - el color de la esporada NO separa estas dos especies. IMPORTANTE: el verdadero riesgo mortal asociado a la seta de chopo es la Galerina marginata, que también esporula pardo-herrumbre - un tema de confusión distinto y potencialmente mortal.','Sabor amargo (escupir la prueba de sabor) y tamaño llamativo = gimnopilo = desechar. Recolectar la seta de chopo solo si la determinación es absolutamente segura - el riesgo mortal de la Galerina marginata debe considerarse por separado.','{"Gymnopilus junonius llega a ser muy grande (sombrero 5-15 cm) y crece en densos cespitosos; la seta de chopo permanece pequeña (sombrero 2-6 cm).","Sabor: G. junonius extremadamente amargo; seta de chopo suave.","Superficie del sombrero: la seta de chopo tiene un sombrero bicolor, higrófano, con margen estriado por transparencia; G. junonius uniformemente naranja-amarillo-herrumbre, finamente escamoso.","Pie: seta de chopo claramente pardo-escamoso/con dibujo de serpiente bajo el anillo; G. junonius fibriloso sin dibujo de serpiente.","Atención: ambos tienen esporada pardo-herrumbre - la esporada aquí NO los separa, por lo que hay que comprobar tamaño/amargor."}',false),
('kuehneromyces_mutabilis','gymnopilus_junonius','fr','G. junonius est nettement plus grand, uniformément orange et finement écailleux ; la pholiote changeante est petite avec un chapeau hygrophane bicolore et un pied brun-écailleux sous l''anneau.','Pholiote changeante agréablement fongique ; G. junonius farineux-rance, avec en plus un goût extrêmement amer.','Les deux en touffes sur bois/souches ; G. junonius sur souches de feuillus et de conifères ainsi que sur bases de troncs, pholiote changeante le plus souvent sur souches de feuillus.','Les deux brun rouille – la couleur des spores ne sépare PAS ces deux-là. IMPORTANT : le véritable risque mortel de la pholiote changeante est la galère marginée (Galerina marginata), qui sporule aussi en brun rouille – un sujet de confusion séparé, mortel.','Goût amer (test gustatif à recracher) et taille remarquable = gymnopile = jeter. Ne récolter la pholiote changeante que si la détermination est absolument sûre – le risque mortel de la galère marginée doit être considéré séparément.','{"Gymnopilus junonius devient très grand (chapeau 5–15 cm) et pousse en touffes denses ; la pholiote changeante reste petite (chapeau 2–6 cm).","Goût : G. junonius extrêmement amer ; pholiote changeante doux.","Surface du chapeau : pholiote changeante a un chapeau bicolore, hygrophane avec un bord strié par transparence ; G. junonius uniformément orange-jaune rouille, finement écailleux.","Pied : pholiote changeante nettement brun-écailleux/chiné sous l''anneau ; G. junonius fibrilleux sans chinure.","Attention : les deux ont une sporée brun rouille – la sporée ne sépare PAS ici, donc vérifier la taille/l''amertume."}',false),
('kuehneromyces_mutabilis','gymnopilus_junonius','it','G. junonius è nettamente più grande, uniformemente arancio e finemente squamoso; la pholiota mutevole è piccola, con cappello igrofano bicolore e gambo bruno-squamoso sotto l''anello.','Pholiota mutevole con odore gradevole di fungo; G. junonius farinoso-rancido, inoltre con sapore estremamente amaro.','Entrambi cespitosi su legno/ceppi; G. junonius su ceppi di latifoglie e conifere nonché alla base dei tronchi, la pholiota mutevole per lo più su ceppi di latifoglie.','Entrambi bruno-ruggine - il colore della sporata NON distingue queste due specie. IMPORTANTE: il vero rischio mortale legato alla pholiota mutevole è la Galerina marginata, che pure sporula bruno-ruggine - un tema di confusione distinto e potenzialmente mortale.','Sapore amaro (sputare la prova gustativa) e dimensione vistosa = gimnopilo = da gettare. Raccogliere la pholiota mutevole solo se la determinazione è assolutamente sicura - il rischio mortale della Galerina marginata va considerato separatamente.','{"Gymnopilus junonius diventa molto grande (cappello 5-15 cm) e cresce in densi cespi; la pholiota mutevole resta piccola (cappello 2-6 cm).","Sapore: G. junonius estremamente amaro; pholiota mutevole mite.","Superficie del cappello: la pholiota mutevole ha cappello bicolore, igrofano, con margine striato per trasparenza; G. junonius uniformemente arancio-giallo-ruggine, finemente squamoso.","Gambo: pholiota mutevole nettamente bruno-squamoso/zigrinato sotto l''anello; G. junonius fibrilloso senza zigrinatura.","Attenzione: entrambi hanno sporata bruno-ruggine - la sporata qui NON distingue, quindi verificare dimensione/amarezza."}',false),
('kuehneromyces_mutabilis','hypholoma_lateritium','en','Sheathed woodtuft with a scaly stem and ring zone, hygrophanous fading cap; brick cap (lateritium) with a smooth stem without scales, uniformly brick-red.','Sheathed woodtuft pleasantly mushroomy and mild, brick cap bitter in taste.','Both clustered on broadleaf stumps - habitat does not separate them, but stem scales and spore colour do.','Sheathed woodtuft rust-/tobacco-brown, brick cap purple-brown - an important distinguishing feature.','Stem scales below the ring zone are the key feature of the sheathed woodtuft - if they are missing, hands off. Even more important: the sheathed woodtuft is confused with the DEADLY galerina (Galerina marginata), so only collect when absolutely certain.','{"The sheathed woodtuft (edible) has a snake-patterned/scaly stem below the ring zone; the brick caps (Hypholoma) have at most a fleeting ring zone without scales","Sheathed woodtuft with a hygrophanous cap drying out two-coloured (water-spot effect), brick cap uniformly brick-red","Taste sheathed woodtuft mild, brick cap bitter","Spore print sheathed woodtuft tobacco-brown/rust-brown, brick cap purple-brown","Both grow clustered on wood - growth form alone is deceptive, so stem scales and spore colour are decisive"}',false),
('kuehneromyces_mutabilis','hypholoma_lateritium','es','Seta de chopo con pie escamoso y zona anular, sombrero higrófano que se decolora; hifoloma color ladrillo (lateritium) con pie liso sin escamas, uniformemente rojo-ladrillo.','Seta de chopo con olor agradable a hongo y suave, hifoloma color ladrillo amargo al gusto.','Ambos cespitosos sobre tocones de frondosas - el hábitat no los separa, sino las escamas del pie y el color de la esporada.','Seta de chopo pardo-herrumbre/tabaco, hifoloma color ladrillo pardo-púrpura - carácter distintivo importante.','Las escamas del pie por debajo de la zona anular son el carácter clave de la seta de chopo - si faltan, no tocar. Más importante aún: la seta de chopo se confunde con la Galerina marginata MORTAL, por lo que solo se debe recolectar con absoluta certeza.','{"La seta de chopo (comestible) tiene un pie con dibujo de serpiente/escamoso por debajo de la zona anular; los hifolomas (cabezas de azufre) tienen como mucho una zona anular fugaz sin escamas","Seta de chopo con sombrero higrófano que al secarse se vuelve bicolor (efecto mancha de agua), hifoloma color ladrillo uniformemente rojo-ladrillo","Sabor seta de chopo suave, hifoloma color ladrillo amargo","Esporada seta de chopo pardo-tabaco/pardo-herrumbre, hifoloma color ladrillo pardo-púrpura","Ambos crecen cespitosos sobre madera - la forma de crecimiento por sí sola engaña, por eso las escamas del pie y el color de la esporada son decisivos"}',false),
('kuehneromyces_mutabilis','hypholoma_lateritium','fr','Pholiote changeante à pied écailleux et zone annulaire, chapeau hygrophane se décolorant ; hypholome couleur de brique à pied lisse sans écailles, uniformément couleur de brique.','Pholiote changeante agréablement fongique et douce, hypholome couleur de brique amer au goût.','Les deux en touffes sur souches de feuillus — l''habitat ne sépare pas, mais les écailles du pied et la couleur des spores.','Pholiote changeante brun rouille/tabac, hypholome couleur de brique brun pourpre — critère de séparation important.','Les écailles du pied sous la zone annulaire sont le critère clé de la pholiote changeante — si elles manquent, ne pas toucher. Plus important encore : la pholiote changeante est confondue avec la galère marginée MORTELLE (Galerina marginata), donc ne récolter qu''avec une certitude absolue.','{"Pholiote changeante (comestible) a un pied chiné/écailleux sous la zone annulaire, les hypholomes ont tout au plus une zone annulaire fugace sans écailles","Pholiote changeante à chapeau hygrophane, séchant bicolore (effet de tache d''eau), hypholome couleur de brique uniformément couleur de brique","Goût pholiote changeante doux, hypholome couleur de brique amer","Sporée pholiote changeante brun tabac/brun rouille, hypholome couleur de brique brun pourpre","Les deux poussent en touffes sur bois — la forme de croissance seule trompe, donc les écailles du pied et la couleur des spores sont décisives"}',false),
('kuehneromyces_mutabilis','hypholoma_lateritium','it','Pholiota mutevole con gambo squamoso e zona anulare, cappello igrofano che si scolora; hypholoma color mattone con gambo liscio senza squame, uniformemente bruno-mattone.','Pholiota mutevole con odore gradevole di fungo e mite, hypholoma color mattone amaro al gusto.','Entrambi cespitosi su ceppi di latifoglie - l''habitat non distingue, bensì le squame del gambo e il colore della sporata.','Pholiota mutevole bruno-ruggine/tabacco, hypholoma color mattone bruno-purpureo - carattere distintivo importante.','Le squame del gambo sotto la zona anulare sono il carattere chiave della pholiota mutevole - se mancano, non toccare. Ancora più importante: la pholiota mutevole viene confusa con la Galerina marginata MORTALE, quindi raccogliere solo in caso di assoluta certezza.','{"La pholiota mutevole (commestibile) ha un gambo zigrinato/squamoso sotto la zona anulare, gli hypholoma (teste di zolfo) hanno al massimo una zona anulare fugace senza squame","Pholiota mutevole con cappello igrofano che si scolora in bicolore (effetto macchia d''acqua), hypholoma color mattone uniformemente bruno-mattone","Sapore pholiota mutevole mite, hypholoma color mattone amaro","Sporata pholiota mutevole bruno-tabacco/bruno-ruggine, hypholoma color mattone bruno-purpureo","Entrambi crescono cespitosi sul legno - la sola forma di crescita inganna, perciò squame del gambo e colore della sporata sono decisivi"}',false),
('lactarius_rufus','lactarius_helvus','en','Maggi milkcap (helvus) pale ochre-grey-brown with watery-colourless milk; rufous milkcap (rufus) deep red-brown with white milk.','The Maggi milkcap smells characteristically of Maggi/lovage (especially when dried); the rufous is practically odourless.','Maggi milkcap in bogs/wet Sphagnum, the rufous in drier acidic coniferous forest.','Both cream-coloured - no distinguishing feature.','Watery-colourless instead of white milk plus Maggi smell = Maggi milkcap, leave it. Do not eat any milkcaps with clear/watery milk.','{"Maggi milkcap (toxic) smells intensely of Maggi/lovage when drying - a unique feature; rufous milkcap odourless to faint","Maggi milkcap with an ochre-grey-brown, finely velvety, often dry cap and WATERY, colourless milk; the rufous with a deep red-brown cap and white milk","Maggi milkcap grows in bog/Sphagnum under pine/birch, the rufous in acidic coniferous forest","Taste rufous burning-acrid (inedible), Maggi milkcap mild - so taste is no protection here"}',false),
('lactarius_rufus','lactarius_helvus','es','Lactario con olor a apio de monte (helvus) ocre-gris-pardo pálido con leche acuosa-incolora; lactario rojizo (rufus) pardo-rojizo intenso con leche blanca.','El lactario con olor a apio de monte huele característicamente a Maggi/levístico (sobre todo seco); el rojizo es prácticamente inodoro.','Lactario con olor a apio de monte en turberas/Sphagnum húmedo, el rojizo en bosque de coníferas ácido más seco.','Ambos de color crema - ningún carácter distintivo.','Leche acuosa-incolora en lugar de blanca más olor a Maggi = lactario con olor a apio de monte, dejarlo. No consumir ningún lactario con leche clara/acuosa.','{"Lactario con olor a apio de monte (tóxico) huele intensamente al secarse a Maggi/levístico - carácter único; lactario rojizo inodoro a débilmente oloroso","Lactario con olor a apio de monte con sombrero ocre-gris-pardo, finamente aterciopelado, a menudo seco, y leche ACUOSA, incolora; el rojizo con sombrero pardo-rojizo intenso y leche blanca","Lactario con olor a apio de monte crece en turbera/Sphagnum bajo pino/abedul, el rojizo en bosque de coníferas ácido","Sabor del rojizo ardiente-acre (no comestible), del lactario con olor a apio de monte suave - por eso el sabor aquí no protege"}',false),
('lactarius_rufus','lactarius_helvus','fr','Lactaire à odeur de chicorée ocre-gris-brun pâle avec un lait aqueux-incolore ; lactaire roux fortement brun-rouge avec un lait blanc.','Lactaire à odeur de chicorée sent de façon caractéristique le Maggi/livèche (surtout séché) ; le roux pratiquement inodore.','Lactaire à odeur de chicorée dans les tourbières/sphaigne humide, le roux en forêt de conifères acide plus sèche.','Les deux crème — pas un critère de séparation.','Lait aqueux-incolore au lieu de blanc plus odeur de Maggi = lactaire à odeur de chicorée, laisser sur place. Ne pas consommer les lactaires à lait clair/aqueux.','{"Lactaire à odeur de chicorée/odeur de Maggi (toxique) sent intensément le Maggi/livèche au séchage — caractère unique ; lactaire roux inodore à faible","Lactaire à odeur de chicorée à chapeau ocre-gris-brun, finement velouté, souvent sec, et lait AQUEUX, incolore ; le roux à chapeau fortement brun-rouge et lait blanc","Lactaire à odeur de chicorée pousse en tourbière/sphaigne sous pin/bouleau, le roux en forêt de conifères acide","Goût roux brûlant-âcre (non comestible), lactaire à odeur de chicorée doux — donc le goût n''est ici pas une protection"}',false),
('lactarius_rufus','lactarius_helvus','it','Lattario con odore di levistico ocra-grigio-bruno pallido con latte acquoso-incolore; lattario dal latte rosso bruno-rosso vivo con latte bianco.','Il lattario con odore di levistico odora caratteristicamente di Maggi/levistico (soprattutto essiccato); il rosso è praticamente inodore.','Lattario con odore di levistico nelle torbiere/sfagni umidi, il rosso in bosco di conifere acido più asciutto.','Entrambi crema - nessun carattere distintivo.','Latte acquoso-incolore invece che bianco più odore di Maggi = lattario con odore di levistico, da lasciare. Non consumare alcun lattario a latte chiaro/acquoso.','{"Lattario con odore di levistico (tossico) odora intensamente nell''essiccazione di Maggi/levistico - carattere unico; lattario dal latte rosso inodore o debolmente odoroso","Lattario con odore di levistico con cappello ocra-grigio-bruno, finemente vellutato, spesso asciutto, e latte ACQUOSO, incolore; il rosso con cappello bruno-rosso vivo e latte bianco","Lattario con odore di levistico cresce in torbiera/sfagno sotto pino/betulla, il rosso in bosco di conifere acido","Sapore del rosso bruciante-acre (immangiabile), del lattario con odore di levistico mite - quindi il sapore qui non protegge"}',false),
('lactarius_subdulcis','lactarius_blennius','en','Grey-green milkcap (blennius) with a slimy, greenish-grey, spotted cap; mild milkcap (subdulcis) with a dry, red-brown, unzoned cap.','Both inconspicuous; decisive is the acrid taste of the grey-green against the mild taste of the mild one.','Both under beech - habitat does not separate them; watch the cap surface (slimy vs dry) and the milk''s colour change.','Both cream to pale ochre - no reliable distinguishing feature.','Slimy grey-green cap + acrid milk drying greenish = toxic grey-green milkcap. Acrid milkcaps generally do not belong in the basket.','{"Grey-green milkcap (toxic) with a greasy-slimy, grey-olive-green cap, often with concentric spots; mild beech milkcap dry, red-brown to cinnamon-coloured","Milk of the grey-green white, drying grey-green in air and acrid/burning; milk of the mild white, mild to slightly bitterish, not changing colour","Grey-green distinctly larger and more robust, the mild one small and fragile","Taste grey-green acrid-scratchy, mild one mild-sweetish (hence the name)"}',false),
('lactarius_subdulcis','lactarius_blennius','es','Lactario gris-verde (blennius) con sombrero viscoso, verde-grisáceo, manchado; lactario dulce (subdulcis) con sombrero seco, pardo-rojizo, no zonado.','Ambos insignificantes; decisivo es el sabor acre del gris-verde frente al suave del dulce.','Ambos bajo haya - el hábitat no los separa; observar la superficie del sombrero (viscosa vs seca) y el cambio de color de la leche.','Ambos crema a ocre pálido - ningún carácter distintivo fiable.','Sombrero gris-verde viscoso + leche acre que seca verdosa = lactario gris-verde tóxico. Los lactarios de leche acre en general no van en la cesta.','{"Lactario gris-verde (tóxico) con sombrero grasiento-viscoso, gris-verde oliva, a menudo con manchas concéntricas; lactario dulce del haya seco, pardo-rojizo a color canela","Leche del gris-verde blanca, que seca gris-verde al aire y acre/ardiente; leche del dulce blanca, suave a ligeramente amarga, sin cambiar de color","Gris-verde claramente más grande y más robusto, el dulce pequeño y frágil","Sabor gris-verde acre-raspante, dulce suave-dulzón (de ahí el nombre)"}',false),
('lactarius_subdulcis','lactarius_blennius','fr','Lactaire muqueux à chapeau visqueux, gris-verdâtre, tacheté ; lactaire subdoux à chapeau sec, brun-rouge, non zoné.','Les deux discrets ; décisif est le goût âcre du muqueux contre le doux du subdoux.','Les deux sous le hêtre — l''habitat ne sépare pas ; faire attention à la surface du chapeau (visqueux vs. sec) et à la décoloration du lait.','Les deux crème à ocre pâle — pas un critère de séparation fiable.','Chapeau gris-vert visqueux + lait âcre séchant en vert = lactaire muqueux toxique. Les lactaires âcres n''ont en général pas leur place dans le panier.','{"Lactaire muqueux (toxique) à chapeau gluant-visqueux, gris-vert-olive, souvent à taches concentriques ; lactaire subdoux du hêtre sec, brun-rouge à cannelle","Lait du muqueux blanc, séchant gris-vert à l''air et âcre/brûlant ; lait du subdoux blanc, doux à légèrement amer, non décolorant","Muqueux nettement plus grand et plus robuste, subdoux petit et fragile","Goût muqueux âcre-râpeux, subdoux doux-subdoux (d''où le nom)"}',false),
('lactarius_subdulcis','lactarius_blennius','it','Lattario grigio-verde con cappello viscido, verde-grigio, macchiato; lattario dolce con cappello asciutto, bruno-rosso, non zonato.','Entrambi insignificanti; decisivo è il sapore acre del grigio-verde contro quello mite del dolce.','Entrambi sotto faggio - l''habitat non distingue; osservare la superficie del cappello (viscida vs asciutta) e il viraggio del latte.','Entrambi crema fino a ocra pallido - nessun carattere distintivo affidabile.','Cappello grigio-verde viscido + latte acre che secca verdastro = lattario grigio-verde tossico. I lattari a latte acre in generale non vanno nel cesto.','{"Lattario grigio-verde (tossico) con cappello viscido-mucillaginoso, grigio-verde oliva, spesso con macchie concentriche; lattario dolce del faggio asciutto, bruno-rosso fino a color cannella","Latte del grigio-verde bianco, che secca grigio-verde all''aria e acre/bruciante; latte del dolce bianco, mite fino a leggermente amarognolo, non virante","Grigio-verde nettamente più grande e più robusto, dolce piccolo e fragile","Sapore grigio-verde acre-graffiante, dolce mite-dolciastro (da cui il nome)"}',false),
('lepista_glaucocana','clitocybe_fragrans','en','Large blewit (Lepista) with a lavender-violet flush vs. small pale grey fragrans.','The blewit smells pleasantly perfumed; fragrans smells of aniseed.','Both in woodland in late autumn; habitat is not a reliable distinguishing feature.','Lavender blewit with a pinkish-white spore print, fragrans white.','On principle, discard small, aniseed-smelling, white-spored funnel caps because of muscarine.','{"The lavender-coloured blewit is distinctly larger, fleshier and flushed with pale violet-lavender; fragrans is small, thin-fleshed and pale grey-brown with no violet tones.","fragrans smells of aniseed and contains muscarine; the lavender blewit smells pleasantly perfumed and is edible.","The gills of the blewit are emarginate-adnexed and easily pushed off; fragrans gills are decurrent.","The spore print distinguishes: blewit pinkish-white, fragrans white."}',false),
('lepista_glaucocana','clitocybe_fragrans','es','Gran lepista (pie azul) con velo lavanda-violeta frente a fragrans pequeño y gris pálido.','La lepista huele agradablemente perfumada; fragrans huele a anís.','Ambos en el bosque a finales de otoño; el hábitat no es un carácter distintivo fiable.','Lepista lavanda con esporada blanco-rosada, fragrans blanca.','Descartar por principio los pequeños clitocibes de esporada blanca con olor a anís, a causa de la muscarina.','{"La lepista de color lavanda es claramente más grande, más carnosa y con velo lavanda-violeta pálido; fragrans es pequeño, de carne delgada y gris-pardo pálido sin tonos violetas.","fragrans huele a anís y contiene muscarina; la lepista lavanda huele agradablemente perfumada y es comestible.","Las láminas de la lepista son escotadas-adnadas y se desprenden fácilmente; las láminas de fragrans son decurrentes.","La esporada distingue: lepista blanco-rosada, fragrans blanca."}',false),
('lepista_glaucocana','clitocybe_fragrans','fr','Grand lépiste teinté de lavande-violet vs. petit fragrans gris pâle.','Lépiste agréablement parfumé ; fragrans d''anis.','Les deux à la fin de l''automne en forêt ; pas de critère de séparation fiable via l''habitat.','Lépiste lavande à sporée rose-blanchâtre, fragrans blanche.','Écarter en général les petits clitocybes à spores blanches, à odeur d''anis, à cause de la muscarine.','{"Le lépiste couleur lavande est nettement plus grand, plus charnu et teinté de violet-lavande pâle ; fragrans est petit, à chair mince et gris-brun pâle sans teintes violettes.","fragrans sent l''anis et contient de la muscarine ; le lépiste lavande sent agréablement parfumé et est comestible.","Lamelles du lépiste échancrées-adnées et facilement détachables ; lamelles de fragrans décurrentes.","La sporée sépare : lépiste rose-blanchâtre, fragrans blanche."}',false),
('lepista_glaucocana','clitocybe_fragrans','it','Grande lepista soffusa di lavanda-violetto contro fragrans piccolo e grigio pallido.','La lepista profuma gradevolmente; fragrans odora di anice.','Entrambi nel bosco nel tardo autunno; l''habitat non è un carattere distintivo affidabile.','Lepista lavanda con sporata bianco-rosata, fragrans con sporata bianca.','Scartare per principio i piccoli clitocybe a sporata bianca con odore di anice, a causa della muscarina.','{"La lepista color lavanda è nettamente più grande, più carnosa e soffusa di lavanda-violetto pallido; fragrans è piccolo, a carne sottile e grigio-bruno pallido senza toni violetti.","fragrans odora di anice e contiene muscarina; la lepista lavanda profuma gradevolmente ed è commestibile.","Le lamelle della lepista sono smarginate-adnate e si staccano facilmente; le lamelle di fragrans sono decorrenti.","La sporata distingue: lepista bianco-rosata, fragrans bianca."}',false),
('lepista_glaucocana','cortinarius_traganus','en','Both are a pale lilac-lavender, but C. traganus has a clavate stem with a veil zone and ochre rust-brown gills, while Lepista glaucocana has pale, removable gills without a veil.','Lepista glaucocana smells mild and pleasant; C. traganus repulsively goaty.','C. traganus in coniferous-forest litter; Lepista glaucocana in deciduous/mixed and coniferous forest at nutrient-rich sites, often at higher elevations.','Lepista glaucocana: pale pink-cream. C. traganus: rust-brown — the spore print separates reliably.','Rust-brown spore print or veil remnants on the stem = Cortinarius = do not eat. Never rely on colour alone.','{"Lepista glaucocana without veil/cortina; C. traganus with a fibrillose veil zone on the clavate stem.","Spore print: Lepista glaucocana pale pink-cream, C. traganus rust-brown.","Smell: Lepista glaucocana mild-pleasant; C. traganus goaty, unpleasant.","Gills: C. traganus young saffron-ochre, never blue-violet, later rust-brown; Lepista glaucocana whitish to pale lavender/lilac, easily removable."}',false),
('lepista_glaucocana','cortinarius_traganus','es','Ambos son de un lila-lavanda pálido, pero C. traganus tiene un pie claviforme con una zona velada y láminas ocre pardo-herrumbre, mientras que Lepista glaucocana tiene láminas claras, separables, sin velo.','Lepista glaucocana huele suave y agradable; C. traganus repugnantemente a macho cabrío.','C. traganus en la hojarasca de bosques de coníferas; Lepista glaucocana en bosque de frondosas/mixto y de coníferas en lugares ricos en nutrientes, a menudo en altitudes elevadas.','Lepista glaucocana: rosa-crema pálido. C. traganus: pardo-herrumbre — la esporada separa de forma fiable.','Esporada pardo-herrumbre o restos de velo en el pie = Cortinarius = no consumir. Nunca te fíes solo del color.','{"Lepista glaucocana sin velo/cortina; C. traganus con una zona de velo fibrillosa en el pie claviforme.","Esporada: Lepista glaucocana rosa-crema pálido, C. traganus pardo-herrumbre.","Olor: Lepista glaucocana suave-agradable; C. traganus a macho cabrío/cabra, desagradable.","Láminas: C. traganus joven azafrán-ocre, nunca azul-violeta, luego pardo-herrumbre; Lepista glaucocana blanquecina hasta lavanda/lila pálido, fácilmente separable."}',false),
('lepista_glaucocana','cortinarius_traganus','fr','Les deux lilas-lavande pâle, mais C. traganus a un pied en massue avec une zone de voile et des lamelles ocre-brun rouille, Lepista glaucocana a des lamelles claires, détachables, sans voile.','Lepista glaucocana sent doux et agréable ; C. traganus répugnant, de bouc.','C. traganus dans la litière de forêt de conifères ; Lepista glaucocana en forêt de feuillus/mixte et de conifères sur stations riches en nutriments, souvent en altitude.','Lepista glaucocana : rose-crème pâle. C. traganus : brun rouille – la sporée sépare sûrement.','Sporée brun rouille ou restes de voile au pied = cortinaire = ne pas manger. Ne te fie jamais à la seule couleur.','{"Lepista glaucocana sans voile/cortine ; C. traganus avec une zone de voile fibrilleuse au pied en massue.","Sporée : Lepista glaucocana rose-crème pâle, C. traganus brun rouille.","Odeur : Lepista glaucocana douce-agréable ; C. traganus de bouc/chèvre désagréable.","Lamelles : C. traganus jeune safran-ocre, jamais bleu-violet, plus tard brun rouille ; Lepista glaucocana blanchâtre à lavande/lilas pâle, facilement détachables."}',false),
('lepista_glaucocana','cortinarius_traganus','it','Entrambi sono di un lilla-lavanda pallido, ma C. traganus ha un gambo clavato con zona velata e lamelle ocra-bruno ruggine, mentre Lepista glaucocana ha lamelle chiare, asportabili, prive di velo.','Lepista glaucocana ha odore mite e gradevole; C. traganus odore ripugnante di becco.','C. traganus nella lettiera dei boschi di conifere; Lepista glaucocana in boschi di latifoglie/misti e di conifere in stazioni ricche di nutrienti, spesso in quota.','Lepista glaucocana: rosa-crema pallido. C. traganus: bruno-ruggine — la sporata separa con sicurezza.','Sporata bruno-ruggine o residui di velo sul gambo = Cortinarius = non consumare. Non fidarti mai del solo colore.','{"Lepista glaucocana senza velo/cortina; C. traganus con zona velata fibrillosa sul gambo clavato.","Sporata: Lepista glaucocana rosa-crema pallido, C. traganus bruno-ruggine.","Odore: Lepista glaucocana mite-gradevole; C. traganus di becco/caprino, sgradevole.","Lamelle: C. traganus da giovane zafferano-ocra, mai blu-violetto, poi bruno-ruggine; Lepista glaucocana biancastra fino a lavanda/lilla pallido, facilmente asportabile."}',false),
('lepista_nuda','cortinarius_traganus','en','Both are violet when young, but C. traganus has a clavate, thickened stem with a veil zone and never has violet gills, whereas Lepista nuda shows entirely violet, slightly removable gills without a veil.','Lepista nuda smells pleasantly aromatic and perfumed; C. traganus smells repulsively goaty — a reliable warning sign.','C. traganus prefers coniferous forest (especially under spruce/fir in moss); Lepista nuda grows more in deciduous/mixed forest and on compost heaps, often in fairy rings.','Lepista nuda: pink-cream spore print. C. traganus: rust-brown spore print. The spore print is the decisive safety criterion.','For EVERY violet mushroom make a spore print: rust-brown = Cortinarius = leave it. Only a pink-cream spore print with no veil remnants speaks for the edible wood blewit.','{"Lepista nuda has NO veil/cortina and no veil remnants on the stem; C. traganus shows a fibrillose, veil-like ring zone (a Cortinarius feature).","Spore print: Lepista nuda pink-cream, C. traganus rust-brown — the spore print makes the confusion reliably distinguishable.","Smell: Lepista nuda pleasantly perfumed-aromatic; C. traganus unpleasantly goaty.","Gills: Lepista nuda remaining entirely violet, detach easily; C. traganus young saffron-ochre, never violet, later rust-brown.","Flesh: Lepista nuda violet-coloured throughout; C. traganus saffron-brownish/ochre when cut."}',false),
('lepista_nuda','cortinarius_traganus','es','Ambos son violetas cuando jóvenes, pero C. traganus tiene un pie claviforme engrosado con una zona velada y nunca tiene láminas violetas, mientras que Lepista nuda muestra láminas enteramente violetas, ligeramente separables, sin velo.','Lepista nuda huele agradablemente aromático y perfumado; C. traganus huele repugnantemente a macho cabrío/cabra — una señal de alarma fiable.','C. traganus prefiere el bosque de coníferas (sobre todo bajo abetos/píceas en el musgo); Lepista nuda crece más bien en bosque de frondosas/mixto y en montones de compost, a menudo en corros de brujas.','Lepista nuda: esporada rosa-crema. C. traganus: esporada pardo-herrumbre. La esporada es el criterio de seguridad decisivo.','Para CADA hongo violeta hacer una esporada: pardo-herrumbre = Cortinarius = dejarlo. Solo una esporada rosa-crema sin restos de velo habla a favor del comestible pie azul.','{"Lepista nuda NO tiene velo/cortina ni restos de velo en el pie; C. traganus presenta una zona anular fibrillosa y velada (carácter de los Cortinarius).","Esporada: Lepista nuda rosa-crema, C. traganus pardo-herrumbre — la esporada hace la confusión distinguible con seguridad.","Olor: Lepista nuda agradablemente perfumado-aromático; C. traganus desagradable, a macho cabrío/cabra.","Láminas: Lepista nuda permanecen enteramente violetas, se separan fácilmente; C. traganus joven azafrán-ocre, nunca violeta, luego pardo-herrumbre.","Carne: Lepista nuda teñida de violeta en toda su masa; C. traganus azafrán-parduzco/ocre al corte."}',false),
('lepista_nuda','cortinarius_traganus','fr','Les deux jeunes violets, mais C. traganus a un pied épaissi en massue avec une zone de voile et jamais de lamelles violettes, tandis que Lepista nuda montre des lamelles entièrement violettes, facilement détachables, sans voile.','Lepista nuda sent agréablement aromatique-parfumé ; C. traganus sent répugnant, de bouc/chèvre – un signe d''alarme fiable.','C. traganus préfère la forêt de conifères (surtout sous épicéas/sapins dans la mousse) ; Lepista nuda pousse plutôt en forêt de feuillus/mixte et tas de compost, souvent en ronds de sorcières.','Lepista nuda : sporée rose-crème. C. traganus : sporée brun rouille. La sporée est le critère de sécurité décisif.','Pour TOUT champignon violet, faire une sporée : brun rouille = cortinaire = laisser sur place. Seule une sporée rose-crème sans restes de voile plaide pour le pied violet comestible.','{"Lepista nuda n''a AUCUN voile/cortine ni restes de voile au pied ; C. traganus montre une zone annulaire fibrilleuse-voilée (caractère de cortinaire).","Sporée : Lepista nuda rose-crème, C. traganus brun rouille – la sporée rend la confusion distinguable sûrement.","Odeur : Lepista nuda agréablement parfumée-aromatique ; C. traganus désagréable, de bouc/chèvre.","Lamelles : Lepista nuda restant entièrement violettes, se détachent facilement ; C. traganus jeune safran-ocre, jamais violet, plus tard brun rouille.","Chair : Lepista nuda colorée de violet à cœur ; C. traganus safran-brunâtre/ocre à la coupe."}',false),
('lepista_nuda','cortinarius_traganus','it','Entrambi da giovani sono violetti, ma C. traganus ha un gambo clavato ingrossato con zona velata e non ha mai lamelle violette, mentre Lepista nuda presenta lamelle interamente violette, leggermente asportabili, prive di velo.','Lepista nuda ha odore gradevole, aromatico e profumato; C. traganus ha odore ripugnante di becco/caprino — un segnale d''allarme affidabile.','C. traganus predilige i boschi di conifere (soprattutto sotto abeti rossi/abeti bianchi nel muschio); Lepista nuda cresce piuttosto in boschi di latifoglie/misti e su cumuli di compost, spesso in cerchi delle streghe.','Lepista nuda: sporata rosa-crema. C. traganus: sporata bruno-ruggine. La sporata è il criterio di sicurezza decisivo.','Per OGNI fungo violetto fare la sporata: bruno-ruggine = Cortinarius = lasciare sul posto. Solo una sporata rosa-crema senza residui di velo depone per il commestibile agarico violetto.','{"Lepista nuda NON ha velo/cortina né residui di velo sul gambo; C. traganus presenta una zona anulare fibrillosa e velata (carattere dei Cortinarius).","Sporata: Lepista nuda rosa-crema, C. traganus bruno-ruggine — la sporata rende la confusione distinguibile con sicurezza.","Odore: Lepista nuda gradevolmente profumato-aromatico; C. traganus sgradevole, di becco/caprino.","Lamelle: Lepista nuda rimangono interamente violette, si asportano facilmente; C. traganus da giovane zafferano-ocra, mai violetto, poi bruno-ruggine.","Carne: Lepista nuda colorata di violetto in tutta la sua massa; C. traganus zafferano-brunastro/ocra al taglio."}',false),
('marasmius_oreades','gymnopus_peronatus','en','The fairy ring mushroom (Marasmius oreades) has broad, distant gills and a leather-yellow umbonate cap; the wood woollyfoot (Gymnopus peronatus) has more crowded gills and a strigose stem base.','The fairy ring mushroom smells pleasantly spicy and almond-like; Gymnopus peronatus has an inconspicuous to vinegary smell (when rubbed) and a burning, acrid taste.','The fairy ring mushroom grows in meadows/lawns in fairy rings; Gymnopus peronatus in forest leaf/needle litter — the habitat helps clearly to separate them.','Both have a whitish spore print — no distinguishing feature.','Meadow habitat + distant gills + almond smell = fairy ring mushroom; forest litter + sharp burning taste = Gymnopus peronatus, suspected toxic. Spit out the taste test.','{"Gymnopus peronatus: sharp, burning, peppery taste, crowded gills, in deciduous forest litter, strigose-felty stem base.","Fairy ring mushroom: mild, pleasant smell (spicy, almond-like/hydrocyanic note), broad and DISTANT gills, grows in meadows/lawns (fairy rings), tough flexible stem.","Fairy ring mushroom cap with a distinct blunt umbo, leather-yellow to buff; Gymnopus peronatus yellowish-brown to leather-brown without clove smell.","Gymnopus peronatus acrid/suspected toxic-stomach-irritating — the fairy ring mushroom is a classic mild edible."}',false),
('marasmius_oreades','gymnopus_peronatus','es','El senderuela (Marasmius oreades) tiene láminas anchas y separadas y un sombrero amarillo cuero con mamelón; Gymnopus peronatus tiene láminas más apretadas y una base del pie estrigosa.','La senderuela huele agradablemente especiado y a almendra; Gymnopus peronatus tiene un olor discreto a avinagrado (al frotar) y un sabor ardiente y acre.','La senderuela crece en prados/céspedes en corros de brujas; Gymnopus peronatus en la hojarasca de hojas/acículas del bosque — la estación ayuda claramente a separarlos.','Ambos tienen esporada blanquecina — ningún criterio distintivo.','Estación de pradera + láminas separadas + olor a almendra = senderuela; hojarasca forestal + sabor acre ardiente = Gymnopus peronatus, sospechoso de ser tóxico. Escupir la prueba de sabor.','{"Gymnopus peronatus: sabor acre, ardiente, picante, láminas apretadas, en la hojarasca de frondosas del bosque, base del pie estrigosa-afieltrada.","Senderuela: suave, olor agradable (especiado, a almendra/nota de ácido cianhídrico), láminas anchas y SEPARADAS, crece en prados/céspedes (corros de brujas), pie tenaz y flexible.","Sombrero de la senderuela con un mamelón obtuso neto, amarillo cuero-color pan; Gymnopus peronatus pardo amarillento-pardo cuero sin olor a clavel.","Gymnopus peronatus acre/sospechoso de ser tóxico-irritante para el estómago — la senderuela es un comestible suave clásico."}',false),
('marasmius_oreades','gymnopus_peronatus','fr','Le marasme des Oréades a des lamelles espacées, écartées et un chapeau mamelonné jaune-cuir ; le collybie à pied feutré des lamelles plus serrées et une base du pied strigueuse.','Marasme des Oréades sent agréablement épicé-amande ; le collybie à pied feutré sent discret à vinaigré (au frottement) et a un goût brûlant-âcre.','Marasme des Oréades pousse sur prairies/pelouses en ronds de sorcières ; le collybie à pied feutré dans la litière de feuillus/conifères en forêt – la station aide nettement à séparer.','Les deux à sporée blanchâtre – pas un critère de séparation.','Station prairie + lamelles espacées + odeur d''amande = marasme des Oréades ; litière forestière + goût brûlant-âcre = collybie à pied feutré suspect de toxicité. Recracher l''échantillon gustatif.','{"Collybie à pied feutré : goût âcre-brûlant poivré, lamelles serrées, dans la litière de feuillus en forêt, base du pied strigueuse-feutrée","Marasme des Oréades : doux, odeur agréable (épicée, d''amande/note cyanhydrique), lamelles larges et ÉCARTÉES, pousse sur prairies/pelouses (ronds de sorcières), pied coriace flexible","Chapeau du marasme des Oréades avec un mamelon obtus net, jaune-cuir-fauve ; collybie à pied feutré jaune-brun-brun-cuir sans odeur d''œillet","Collybie à pied feutré âcre/suspect de toxicité-irritant pour l''estomac – marasme des Oréades comestible doux classique"}',false),
('marasmius_oreades','gymnopus_peronatus','it','Il gambosecco (Marasmius oreades) ha lamelle larghe e distanziate e un cappello giallo-cuoio umbonato; Gymnopus peronatus ha lamelle più fitte e una base del gambo strigosa.','Il gambosecco ha odore gradevole, speziato e di mandorla; Gymnopus peronatus ha odore poco appariscente fino ad acetoso (allo sfregamento) e sapore bruciante e acre.','Il gambosecco cresce nei prati/tappeti erbosi in cerchi delle streghe; Gymnopus peronatus nella lettiera di foglie/aghi del bosco — la stazione aiuta nettamente a separarli.','Entrambi hanno sporata biancastra — nessun criterio distintivo.','Stazione di prato + lamelle distanziate + odore di mandorla = gambosecco; lettiera forestale + sapore acre bruciante = Gymnopus peronatus sospetto velenoso. Sputare la prova di assaggio.','{"Gymnopus peronatus: sapore acre-bruciante pepato, lamelle fitte, nella lettiera di latifoglie del bosco, base del gambo strigosa-feltrata.","Gambosecco: mite, odore gradevole (speziato, di mandorla/nota di acido cianidrico), lamelle larghe e DISTANZIATE, cresce nei prati/tappeti erbosi (cerchi delle streghe), gambo tenace e flessibile.","Cappello del gambosecco con umbone ottuso netto, giallo-cuoio-color pane; Gymnopus peronatus bruno-giallastro-bruno cuoio senza odore di garofano.","Gymnopus peronatus acre/sospetto velenoso-irritante per lo stomaco — il gambosecco è un classico fungo commestibile mite."}',false),
('marasmius_oreades','panaeolina_foenisecii','en','The fairy ring mushroom has distant, white, free gills and a leather-yellow umbonate cap; the mower''s mushroom (Panaeolina foenisecii) shows crowded, mottled-spotted, dark-brown gills.','Fairy ring mushroom: often a characteristic bitter-almond/marzipan or spicy smell (not always clearly pronounced). Panaeolina foenisecii: nearly odourless.','Both grow in meadows and lawns; Panaeolina foenisecii prefers fertilised, freshly mown lawns, the fairy ring mushroom often in fairy rings on poorer grassland — the habitat does NOT separate them reliably.','Fairy ring mushroom: white spore print. Panaeolina foenisecii: dark purple-/blackish-brown spore print — the safest distinguishing feature.','Always let small brown-capped mushrooms growing in the lawn drop spores — white spore print = possible fairy ring mushroom, dark brown = mottlegill, then never eat. Never take the smell alone as proof.','{"Fairy ring mushroom: tough, flexible stem that can be twisted without breaking; Panaeolina foenisecii has a brittle, hollow stem.","Fairy ring mushroom: whitish-cream gills, free, broad/distant; Panaeolina foenisecii has spotted grey-brown, speckled (mottled) gills due to uneven spore ripening.","Fairy ring mushroom: pale leather-yellow to buff cap with umbo, hygrophanous; Panaeolina foenisecii smaller, darker grey-brown, without a clear umbo.","Spore print fairy ring mushroom white, Panaeolina foenisecii dark purple-brown to blackish — the decisive safe separation step.","The fairy ring mushroom often smells of bitter almond/hydrocyanic acid or spicy; Panaeolina foenisecii is nearly odourless."}',false),
('marasmius_oreades','panaeolina_foenisecii','es','La senderuela tiene láminas separadas, blancas, libres y un sombrero amarillo cuero con mamelón; el panaeolina de los henos (Panaeolina foenisecii) presenta láminas apretadas, jaspeadas-moteadas, pardo oscuro.','Senderuela: a menudo un olor característico a almendra amarga/mazapán o especiado (no siempre claramente marcado). Panaeolina foenisecii: casi inodoro.','Ambos crecen en prados y céspedes; Panaeolina foenisecii prefiere los céspedes abonados y recién segados, la senderuela a menudo en corros de brujas sobre praderas más pobres — el hábitat NO los separa de forma fiable.','Senderuela: esporada blanca. Panaeolina foenisecii: esporada pardo-purpúrea/negruzca oscura — el rasgo distintivo más seguro.','Dejar siempre esporular los pequeños hongos de sombrero pardo que crecen en el césped — esporada blanca = posible senderuela, pardo oscuro = panaeolina, entonces nunca comer. Nunca tomar el olor solo como prueba.','{"Senderuela: pie tenaz y flexible que se deja retorcer sin romperse; Panaeolina foenisecii tiene un pie frágil y hueco.","Senderuela: láminas blanquecinas-crema, libres, anchas/separadas; Panaeolina foenisecii tiene láminas gris-parduzcas manchadas, moteadas (jaspeadas) por la maduración desigual de las esporas.","Senderuela: sombrero amarillo cuero-color pan claro con mamelón, higrófano; Panaeolina foenisecii más pequeño, más oscuro gris-pardo, sin mamelón claro.","Esporada de la senderuela blanca, Panaeolina foenisecii pardo-púrpura oscuro-negruzca — el paso distintivo decisivo y seguro.","La senderuela huele a menudo a almendra amarga/ácido cianhídrico o especiado; Panaeolina foenisecii es casi inodoro."}',false),
('marasmius_oreades','panaeolina_foenisecii','fr','Le marasme des Oréades a des lames espacées, blanches, libres et un chapeau jaune cuir mamelonné ; le panéole des foins (Panaeolina foenisecii) présente des lames serrées, marbrées-tachetées, brun foncé.','Marasme des Oréades : souvent une odeur caractéristique d''amande amère/de massepain ou épicée (pas toujours nettement marquée). Panaeolina foenisecii : presque inodore.','Les deux poussent dans les prés et pelouses ; Panaeolina foenisecii préfère les pelouses fertilisées fraîchement tondues, le marasme des Oréades souvent en ronds de sorcière sur des prairies plus maigres — l''habitat ne les sépare PAS de façon fiable.','Marasme des Oréades : sporée blanche. Panaeolina foenisecii : sporée brun pourpre/noirâtre foncé — le critère de distinction le plus sûr.','Toujours laisser sporuler les petits champignons à chapeau brun poussant dans la pelouse — sporée blanche = marasme des Oréades possible, brun foncé = panéole, alors ne jamais manger. Ne jamais prendre l''odeur seule comme preuve.','{"Marasme des Oréades : pied tenace et flexible qui se laisse tordre sans casser ; Panaeolina foenisecii a un pied fragile et creux.","Marasme des Oréades : lames blanchâtres-crème, libres, larges/espacées ; Panaeolina foenisecii a des lames gris-brun tachetées, mouchetées (marbrées) du fait d''une maturation inégale des spores.","Marasme des Oréades : chapeau jaune cuir-couleur pain clair avec mamelon, hygrophane ; Panaeolina foenisecii plus petit, plus foncé gris-brun, sans mamelon net.","Sporée du marasme des Oréades blanche, Panaeolina foenisecii brun pourpre foncé-noirâtre — l''étape de séparation décisive et sûre.","Le marasme des Oréades sent souvent l''amande amère/l''acide cyanhydrique ou est épicé ; Panaeolina foenisecii est presque inodore."}',false),
('marasmius_oreades','panaeolina_foenisecii','it','Il gambosecco ha lamelle distanziate, bianche, libere e un cappello giallo-cuoio umbonato; il panaeolina dei fienili (Panaeolina foenisecii) presenta lamelle fitte, marmorizzate-macchiate, bruno scuro.','Gambosecco: spesso un odore caratteristico di mandorla amara/marzapane o speziato (non sempre nettamente marcato). Panaeolina foenisecii: quasi inodore.','Entrambi crescono nei prati e tappeti erbosi; Panaeolina foenisecii predilige i tappeti erbosi concimati e appena falciati, il gambosecco spesso in cerchi delle streghe su prati più magri — l''habitat NON li separa in modo affidabile.','Gambosecco: sporata bianca. Panaeolina foenisecii: sporata bruno-purpurea/nerastra scura — il criterio distintivo più sicuro.','Lasciare sempre sporulare i piccoli funghi a cappello bruno che crescono nel tappeto erboso — sporata bianca = possibile gambosecco, bruno scuro = panaeolina, allora non mangiare mai. Non prendere mai l''odore da solo come prova.','{"Gambosecco: gambo tenace e flessibile che si lascia attorcigliare senza spezzarsi; Panaeolina foenisecii ha un gambo fragile e cavo.","Gambosecco: lamelle biancastre-crema, libere, larghe/distanziate; Panaeolina foenisecii ha lamelle grigio-brune macchiate, screziate (marmorizzate) per la maturazione disuguale delle spore.","Gambosecco: cappello giallo-cuoio-color pane chiaro con umbone, igrofano; Panaeolina foenisecii più piccolo, più scuro grigio-bruno, senza umbone netto.","Sporata del gambosecco bianca, Panaeolina foenisecii bruno-purpurea scura-nerastra — il passo distintivo decisivo e sicuro.","Il gambosecco odora spesso di mandorla amara/acido cianidrico o è speziato; Panaeolina foenisecii è quasi inodore."}',false),
('marasmius_oreades','panaeolus_cinctulus','en','Panaeolus cinctulus shows mottled gills turning grey to black and a moist red-brown, often banded cap margin; the fairy ring mushroom stays uniformly leather-yellow with white gills.','Fairy ring mushroom often of bitter almond/spicy; Panaeolus cinctulus inconspicuous, plain mushroomy smell.','Panaeolus cinctulus grows on dung, compost and fertilised lawns, the fairy ring mushroom in fairy rings on meadows/lawns — overlap on fertilised lawn areas.','Fairy ring mushroom white, Panaeolus cinctulus deep black.','Never collect small lawn/dung mushrooms with grey gills turning black — a black spore print reliably rules out the edible fairy ring mushroom.','{"Fairy ring mushroom: tough, elastic stem; Panaeolus cinctulus has a thinner, more brittle, hollow stem.","Fairy ring mushroom: white, broad and free gills; Panaeolus cinctulus has mottled gills turning cream to grey and finally black.","The fairy ring mushroom''s cap is leather-yellow with umbo, hygrophanous; Panaeolus cinctulus darker red-brown (moist) with an often darker, banded cap margin, lightening to cream-white on drying.","Spore print fairy ring mushroom white, Panaeolus cinctulus deep black — unambiguous separation.","Panaeolus cinctulus grows preferentially on dung, compost and heavily fertilised lawns; contains psilocybin (bluing pressure marks possible)."}',false),
('marasmius_oreades','panaeolus_cinctulus','es','Panaeolus cinctulus presenta láminas abigarradas que se vuelven grises a negras y un margen del sombrero pardo-rojo húmedo, a menudo zonado; la senderuela permanece uniformemente amarillo cuero con láminas blancas.','Senderuela a menudo a almendra amarga/especiado; Panaeolus cinctulus discreto, olor fúngico banal.','Panaeolus cinctulus crece sobre estiércol, compost y céspedes abonados, la senderuela en corros de brujas sobre prados/céspedes — solapamiento en las superficies de césped abonadas.','Senderuela blanca, Panaeolus cinctulus negro profundo.','Nunca recolectar pequeños hongos de césped/de estiércol con láminas grises que se vuelven negras — una esporada negra excluye con seguridad la senderuela comestible.','{"Senderuela: pie tenaz, elástico; Panaeolus cinctulus tiene un pie más delgado, más frágil, hueco.","Senderuela: láminas blancas, anchas y libres; Panaeolus cinctulus tiene láminas abigarradas que se vuelven de crema a grises y finalmente negras.","El sombrero de la senderuela es amarillo cuero con mamelón, higrófano; Panaeolus cinctulus más oscuro pardo-rojo (húmedo) con un margen del sombrero a menudo más oscuro y zonado, que se aclara a blanco-crema al secarse.","Esporada de la senderuela blanca, Panaeolus cinctulus negro profundo — separación inequívoca.","Panaeolus cinctulus crece preferentemente sobre estiércol, compost y céspedes fuertemente abonados; contiene psilocibina (posibles manchas de presión que viran al azul)."}',false),
('marasmius_oreades','panaeolus_cinctulus','fr','Panaeolus cinctulus présente des lames bigarrées devenant grises à noires et un bord du chapeau brun rouge humide, souvent zoné ; le marasme des Oréades reste uniformément jaune cuir avec des lames blanches.','Marasme des Oréades souvent à l''amande amère/épicé ; Panaeolus cinctulus discret, odeur fongique banale.','Panaeolus cinctulus pousse sur le fumier, le compost et les pelouses fertilisées, le marasme des Oréades en ronds de sorcière sur prés/pelouses — chevauchement sur les surfaces de pelouse fertilisées.','Marasme des Oréades blanc, Panaeolus cinctulus noir profond.','Ne jamais récolter les petits champignons de pelouse/de fumier à lames grises devenant noires — une sporée noire exclut de façon sûre le marasme des Oréades comestible.','{"Marasme des Oréades : pied tenace, élastique ; Panaeolus cinctulus a un pied plus mince, plus fragile, creux.","Marasme des Oréades : lames blanches, larges et libres ; Panaeolus cinctulus a des lames bigarrées devenant crème à grises puis finalement noires.","Le chapeau du marasme des Oréades est jaune cuir avec mamelon, hygrophane ; Panaeolus cinctulus plus foncé brun rouge (humide) avec un bord du chapeau souvent plus foncé et zoné, s''éclaircissant en blanc crème en séchant.","Sporée du marasme des Oréades blanche, Panaeolus cinctulus noir profond — séparation sans équivoque.","Panaeolus cinctulus pousse de préférence sur le fumier, le compost et les pelouses fortement fertilisées ; contient de la psilocybine (taches de pression bleuissantes possibles)."}',false),
('marasmius_oreades','panaeolus_cinctulus','it','Panaeolus cinctulus presenta lamelle screziate che diventano grigie fino a nere e un margine del cappello bruno-rosso umido, spesso zonato; il gambosecco resta uniformemente giallo-cuoio con lamelle bianche.','Gambosecco spesso di mandorla amara/speziato; Panaeolus cinctulus poco appariscente, odore fungino banale.','Panaeolus cinctulus cresce su letame, compost e tappeti erbosi concimati, il gambosecco in cerchi delle streghe su prati/tappeti erbosi — sovrapposizione sulle superfici erbose concimate.','Gambosecco bianco, Panaeolus cinctulus nero profondo.','Non raccogliere mai i piccoli funghi di prato/di letame con lamelle grigie che diventano nere — una sporata nera esclude con sicurezza il gambosecco commestibile.','{"Gambosecco: gambo tenace, elastico; Panaeolus cinctulus ha un gambo più sottile, più fragile, cavo.","Gambosecco: lamelle bianche, larghe e libere; Panaeolus cinctulus ha lamelle screziate che diventano da crema a grigie e infine nere.","Il cappello del gambosecco è giallo-cuoio con umbone, igrofano; Panaeolus cinctulus più scuro bruno-rosso (umido) con un margine del cappello spesso più scuro e zonato, che schiarisce a bianco-crema asciugandosi.","Sporata del gambosecco bianca, Panaeolus cinctulus nero profondo — separazione inequivocabile.","Panaeolus cinctulus cresce preferibilmente su letame, compost e tappeti erbosi fortemente concimati; contiene psilocibina (possibili macchie da pressione che virano al blu)."}',false),
('marone','tricholoma_ustale','en','The bay bolete (marone) has tubes/spongy flesh under the cap, the burnt knight (Tricholoma ustale) has gills — the underside of the cap clears up the confusion immediately.','Bay bolete mild-mushroomy, ustale faintly mealy — not a primary distinguishing feature.','Bay bolete under spruce/pine on acidic soil, ustale mainly in deciduous forest (beech/oak).','Bay bolete olive-brown spore print (bolete), ustale white spore print (gilled mushroom) — clearly different.','Always check the underside of the cap: tubes = bolete, gills = gilled mushroom. A gilled mushroom with a brown slimy cap is never a bay bolete.','{"Decisive: the bay bolete (edible) has TUBES/pores under the cap, the burnt knight has GILLS — immediately distinguishable by looking at the underside of the cap.","The bay bolete is a bolete (Boletales) with a thick stem and yellowish tubes that bruise blue under pressure; ustale is a gilled mushroom.","The resemblance exists only from a distance via the brown cap, slimy when moist — so the ustale cap can resemble a bay bolete from above.","Bay bolete flesh tastes mild-nutty, ustale bitterish.","In the bay bolete the tubes can be peeled off as a layer — impossible in knights (true gills)."}',false),
('marone','tricholoma_ustale','es','El boleto bayo (marone) tiene tubos/carne esponjosa bajo el sombrero, el tricoloma quemado (Tricholoma ustale) láminas — la cara inferior del sombrero aclara la confusión inmediatamente.','Boleto bayo suave-fúngico, ustale débilmente harinoso — no es un criterio distintivo primario.','Boleto bayo bajo abeto rojo/pino en suelo ácido, ustale sobre todo en bosque de frondosas (haya/roble).','Boleto bayo esporada pardo-olivácea (boleto), ustale esporada blanca (hongo laminado) — claramente diferentes.','Comprobar siempre la cara inferior del sombrero: tubos = boleto, láminas = hongo laminado. Un hongo laminado con sombrero pardo viscoso nunca es un boleto bayo.','{"Decisivo: el boleto bayo (comestible) tiene TUBOS/poros bajo el sombrero, el tricoloma quemado tiene LÁMINAS — inmediatamente distinguibles mirando la cara inferior del sombrero.","El boleto bayo es un boleto (Boletales) con pie grueso y tubos amarillentos que viran al azul a la presión; ustale es un hongo laminado.","El parecido existe solo de lejos a través del sombrero pardo, viscoso con la humedad — así el sombrero de ustale puede recordar desde arriba a un boleto bayo.","La carne del boleto bayo sabe suave-a nuez, ustale amarguita.","En el boleto bayo los tubos se dejan separar como una capa — imposible en los tricolomas (láminas verdaderas)."}',false),
('marone','tricholoma_ustale','fr','Le bolet bai (marone) a des tubes/une chair spongieuse sous le chapeau, le tricholome brûlé (Tricholoma ustale) des lames — la face inférieure du chapeau lève la confusion immédiatement.','Bolet bai doux-fongique, ustale faiblement farineux — pas de critère distinctif primaire.','Bolet bai sous épicéa/pin sur sol acide, ustale surtout en forêt de feuillus (hêtre/chêne).','Bolet bai sporée brun olive (bolet), ustale sporée blanche (champignon à lames) — nettement différentes.','Toujours vérifier la face inférieure du chapeau : tubes = bolet, lames = champignon à lames. Un champignon à lames à chapeau brun visqueux n''est jamais un bolet bai.','{"Décisif : le bolet bai (comestible) a des TUBES/pores sous le chapeau, le tricholome brûlé a des LAMES — immédiatement distinguables en regardant la face inférieure du chapeau.","Le bolet bai est un bolet (Boletales) à pied épais et à tubes jaunâtres bleuissant à la pression ; ustale est un champignon à lames.","La ressemblance n''existe que de loin via le chapeau brun, visqueux par temps humide — ainsi le chapeau d''ustale peut rappeler de dessus un bolet bai.","La chair du bolet bai a un goût doux-noisette, ustale amère.","Chez le bolet bai, les tubes se laissent retirer en couche — impossible chez les tricholomes (vraies lames)."}',false),
('marone','tricholoma_ustale','it','Il boleto baio (marone) ha tubuli/carne spugnosa sotto il cappello, il tricoloma bruciato (Tricholoma ustale) lamelle — la faccia inferiore del cappello risolve la confusione immediatamente.','Boleto baio mite-fungino, ustale debolmente farinoso — nessun criterio distintivo primario.','Boleto baio sotto abete rosso/pino su suolo acido, ustale soprattutto nel bosco di latifoglie (faggio/quercia).','Boleto baio sporata bruno-olivacea (boleto), ustale sporata bianca (fungo a lamelle) — nettamente diverse.','Controllare sempre la faccia inferiore del cappello: tubuli = boleto, lamelle = fungo a lamelle. Un fungo a lamelle con cappello bruno viscido non è mai un boleto baio.','{"Decisivo: il boleto baio (commestibile) ha TUBULI/pori sotto il cappello, il tricoloma bruciato ha LAMELLE — immediatamente distinguibili guardando la faccia inferiore del cappello.","Il boleto baio è un boleto (Boletales) con gambo spesso e tubuli giallastri che virano al blu alla pressione; ustale è un fungo a lamelle.","La somiglianza esiste solo da lontano tramite il cappello bruno, viscido con l''umidità — così il cappello di ustale può ricordare dall''alto un boleto baio.","La carne del boleto baio ha sapore mite-nocciola, ustale amarognola.","Nel boleto baio i tubuli si lasciano staccare come strato — impossibile nei tricolomi (vere lamelle)."}',false),
('mitrophora_semilibera','gyromitra_gigas','en','The half-free morel shows a small bell-shaped, pitted cap with a free, projecting margin on a long slender stem; the snow morel (Gyromitra gigas) a large, bulging brain-like cap on a short thick stem.','No reliable distinguishing smell feature.','Both are spring mushrooms; the half-free morel on calcareous soils/floodplain forest, the snow morel as a wood saprobiont on rotting stumps — the habitat does not separate reliably.','Both with a pale spore print (ascomycetes) — no distinguishing feature.','Watch for pits (morel) vs. brain-like convolutions (false morel) and always cut lengthwise. Only collect a spring ''morel'' if it is clearly pitted and has a continuous hollow inside; leave convoluted false morels behind.','{"Half-free morel: small bell-shaped to conical, distinctly pitted cap, attached to the long, hollow, whitish stem only to about its lower half (cap margin free, projecting)","Snow morel: massive, brain-like convoluted cap without pits, short thick stem, internally traversed by several hollow chambers","Half-free morel completely hollow in cap and stem; false morel stem chambered/traversed by hollows","IMPORTANT: the half-free morel is edible only when well cooked (indigestible raw). The snow morel itself contains hardly any gyromitrin, but is barely separable from the deadly spring false morel (Gyromitra esculenta) — therefore avoid every brain-like find"}',false),
('mitrophora_semilibera','gyromitra_gigas','es','La colmenilla semilibre muestra un pequeño sombrero campanulado alveolado con margen libre saliente sobre un pie largo y esbelto; la giromitra gigante un gran sombrero cerebriforme abultado sobre un pie corto y grueso.','Ningún criterio olfativo distintivo fiable.','Ambos son hongos primaverales; la colmenilla semilibre sobre suelos calcáreos/bosque de ribera, la giromitra gigante como saprobionte de la madera sobre tocones podridos — el hábitat no separa con seguridad.','Ambos con esporada clara (ascomicetos) — ningún criterio distintivo.','Prestar atención a los alvéolos (colmenilla) vs. circunvoluciones cerebriformes (giromitra) y cortar siempre a lo largo. Recolectar una «colmenilla» primaveral solo si está claramente alveolada y por dentro presenta una cavidad continua; dejar sobre el terreno las giromitras circunvolucionadas.','{"Colmenilla semilibre: pequeño sombrero campanulado-cónico, claramente alveolado, que está soldado solo hasta aproximadamente su mitad inferior al pie largo, hueco y blanquecino (margen del sombrero libre, saliente)","Giromitra gigante: sombrero macizo, de circunvoluciones cerebriformes sin alvéolos, pie corto y grueso, recorrido internamente por varias cavidades","Colmenilla semilibre completamente hueca en el sombrero y el pie; pie de la giromitra tabicado/recorrido por cavidades","IMPORTANTE: la colmenilla semilibre solo es comestible bien cocida (indigesta cruda). La giromitra gigante misma contiene apenas giromitrina, pero es difícilmente separable de la giromitra primaveral mortal (Gyromitra esculenta) — por eso evitar todo hallazgo cerebriforme"}',false),
('mitrophora_semilibera','gyromitra_gigas','fr','La morille demi-libre montre un petit chapeau en cloche alvéolé à bord libre écarté sur un long pied élancé ; le gyromitre géant un grand chapeau en cerveau bosselé sur un pied court et épais.','Pas de critère olfactif fiable de séparation.','Les deux champignons de printemps ; morille demi-libre sur sols riches en calcaire/forêt alluviale, gyromitre géant comme saprobionte lignicole sur souches pourries – l''habitat ne sépare pas sûrement.','Les deux à sporée claire (ascomycètes) – pas un critère de séparation.','Faire attention aux alvéoles (morille) vs. circonvolutions en forme de cerveau (gyromitre) et toujours couper en long. Ne récolter une « morille » de printemps que si elle est nettement alvéolée et qu''elle présente à l''intérieur une cavité continue ; laisser sur place les gyromitres circonvolués.','{"Morille demi-libre : petit chapeau conique-en cloche, nettement alvéolé, qui n''est attaché au long pied creux blanchâtre qu''environ à sa moitié inférieure (bord du chapeau libre, écarté)","Gyromitre géant : chapeau massif, circonvolué en forme de cerveau sans alvéoles, pied court et épais, traversé à l''intérieur de plusieurs cavités","Morille demi-libre creuse de manière continue dans le chapeau et le pied ; pied du gyromitre cloisonné/traversé de cavités","IMPORTANT : morille demi-libre comestible seulement bien cuite (crue mal tolérée). Le gyromitre géant lui-même contient peu de gyromitrine, mais est à peine séparable du gyromitre comestible printanier mortel – c''est pourquoi éviter toute trouvaille en forme de cerveau"}',false),
('mitrophora_semilibera','gyromitra_gigas','it','La spugnola semilibera mostra un piccolo cappello campanulato alveolato con margine libero distaccato su un gambo lungo e slanciato; la gyromitra gigante un grande cappello cerebriforme rigonfio su un gambo corto e grosso.','Nessun criterio olfattivo distintivo affidabile.','Entrambi sono funghi primaverili; la spugnola semilibera su suoli calcarei/bosco ripariale, la gyromitra gigante come saprobionte del legno su ceppi marcescenti — l''habitat non separa con sicurezza.','Entrambi con sporata chiara (ascomiceti) — nessun criterio distintivo.','Fare attenzione agli alveoli (spugnola) vs. circonvoluzioni cerebriformi (gyromitra) e tagliare sempre per il lungo. Raccogliere una «spugnola» primaverile solo se è chiaramente alveolata e all''interno presenta una cavità continua; lasciare sul posto le gyromitre circonvolute.','{"Spugnola semilibera: piccolo cappello campanulato-conico, nettamente alveolato, che è saldato solo fino a circa la metà inferiore al gambo lungo, cavo e biancastro (margine del cappello libero, distaccato)","Gyromitra gigante: cappello massiccio, a circonvoluzioni cerebriformi senza alveoli, gambo corto e grosso, percorso internamente da più cavità","Spugnola semilibera completamente cava nel cappello e nel gambo; gambo della gyromitra concamerato/percorso da cavità","IMPORTANTE: la spugnola semilibera è commestibile solo ben cotta (indigesta cruda). La gyromitra gigante stessa contiene scarsa gyromitrina, ma è a malapena separabile dalla gyromitra primaverile mortale (Gyromitra esculenta) — perciò evitare ogni ritrovamento cerebriforme"}',false),
('mitrophora_semilibera','helvella_crispa','en','The half-free morel has a honeycomb-pitted bell-shaped cap ; the white saddle (Helvella crispa) a pitless, saddle-folded lobed cap on a ribbed-chambered stem.','Both inconspicuously mushroomy – no reliable distinguishing feature.','Half-free morel in spring (floodplain forest/calcareous) ; white saddle mainly summer–autumn in deciduous/mixed forest along path and forest edges – season helps to separate.','Both ascomycetes with pale, cream-white spore print – not a distinguishing feature.','Honeycombed = morel candidate ; saddle-/lobe-shaped without pits = false morel (Helvella) = leave it. Do not treat Helvella species as an edible mushroom.','{"Half-free morel : honeycombed bell-conical cap (true chambers), cap and long stem entirely hollow, pale whitish-ochre","White saddle : multi-lobed saddle-folded/lobed cap WITHOUT pits, whitish-cream, stem deeply longitudinally furrowed/ribbed and chambered (not one smooth hollow)","The white saddle contains gyromitrin → toxic raw ; do not treat it as a harmless edible mushroom","Appearance time : half-free morel in spring, white saddle mainly summer–late autumn (July–November)"}',false),
('mitrophora_semilibera','helvella_crispa','es','La colmenilla semilibre tiene un sombrero acampanado alveolado-hundido ; la helvella crespa un sombrero con lóbulos plegados en silla de montar, sin alvéolos, sobre un pie acostillado-tabicado.','Ambas inodoras-fúngicas – ningún criterio de distinción fiable.','Colmenilla semilibre en primavera (bosque de ribera/calcáreo) ; helvella crespa sobre todo en verano–otoño en bosque caducifolio/mixto en bordes de caminos y linderos – la estación ayuda a separar.','Ambos ascomicetos con esporada clara, blanco-crema – no es un criterio de distinción.','Alveolado = candidato colmenilla ; en forma de silla/con lóbulos sin alvéolos = helvella = dejar en el sitio. No tratar las helvellas como seta comestible.','{"Colmenilla semilibre : sombrero campanulado-cónico alveolado (verdaderas cámaras), sombrero y largo pie completamente huecos, blanquecino-ocre pálido","Helvella crespa : sombrero multilobulado enrollado en silla/con lóbulos SIN alvéolos, blanquecino-crema, pie profundamente surcado/acostillado a lo largo y tabicado (no una cavidad lisa)","La helvella crespa contiene gyromitrina → tóxica cruda ; no tratarla como una seta comestible inofensiva","Período de aparición : colmenilla semilibre en primavera, helvella crespa sobre todo verano–otoño tardío (julio–noviembre)"}',false),
('mitrophora_semilibera','helvella_crispa','fr','La morille demi-libre a un chapeau en cloche alvéolé-creusé ; l''helvelle crépue un chapeau en lobes plié en selle, sans alvéoles, sur un pied côtelé-cannelé.','Les deux fongiques discrets – pas un critère de séparation fiable.','Morille demi-libre au printemps (forêt alluviale/calcaire) ; helvelle crépue surtout été–automne en forêt de feuillus/mixte aux bords de chemins et lisières – la saison aide à séparer.','Les deux ascomycètes à sporée claire, crème-blanchâtre – pas un critère de séparation.','Alvéolé = candidat morille ; en forme de selle/lobes sans alvéoles = helvelle = laisser sur place. Ne pas traiter les helvelles comme comestibles.','{"Morille demi-libre : chapeau en cloche-conique alvéolé (véritables loges), chapeau et long pied complètement creux, blanchâtre-ocre pâle","Helvelle crépue : chapeau circonvolué en selle/lobes, multilobé SANS alvéoles, blanchâtre-crème, pied profondément cannelé-côtelé et cloisonné (pas une cavité lisse)","L''helvelle crépue contient de la gyromitrine → crue toxique ; ne pas la traiter comme un comestible inoffensif","Période d''apparition : morille demi-libre au printemps, helvelle crépue surtout été–fin d''automne (juillet–novembre)"}',false),
('mitrophora_semilibera','helvella_crispa','it','La spugnola semilibera ha un cappello a campana alveolato-scavato ; l''helvella crespa un cappello a lobi pieghettati a sella, senza alveoli, su un gambo costolato-camerato.','Entrambe inodore-fungine – nessun criterio di distinzione affidabile.','Spugnola semilibera in primavera (foresta golenale/calcarea) ; helvella crespa soprattutto in estate–autunno in bosco di latifoglie/misto ai bordi dei sentieri e ai margini – la stagione aiuta a separare.','Entrambi ascomiceti con sporata chiara, bianco-crema – non un criterio di distinzione.','Alveolato = candidato spugnola ; a forma di sella/a lobi senza alveoli = helvella = lasciare sul posto. Non trattare le helvelle come fungo commestibile.','{"Spugnola semilibera : cappello campanulato-conico alveolato (vere camere), cappello e lungo gambo completamente cavi, biancastro-ocra pallido","Helvella crespa : cappello plurilobato avvolto a sella/a lobi SENZA alveoli, biancastro-crema, gambo profondamente solcato/costolato per il lungo e camerato (non una cavità liscia)","L''helvella crespa contiene gyromitrina → tossica da cruda ; non trattarla come un fungo commestibile innocuo","Periodo di comparsa : spugnola semilibera in primavera, helvella crespa soprattutto estate–tardo autunno (luglio–novembre)"}',false),
('morchelchampignon','gyromitra_gigas','en','The edible morel has a regularly pitted-honeycombed cap surface, the giant false morel an irregularly brain-/walnut-kernel-like convoluted, bulging-swollen surface without true pits.','Both rather inconspicuously mushroomy ; smell does NOT separate them reliably.','Edible morel in spring on calcareous soils ; giant false morel a spring wood saprobiont on rotten stumps, buried wood and bark mulch (often conifer). Appearance times overlap – habitat does not separate with certainty.','Both ascomycetes (asci) with pale, cream-coloured spore print – unsuitable for distinction.','Cut lengthwise : the true morel forms ONE continuous hollow from the tip to the stem base and is honeycombed. Leave anything brain-like convoluted with a chambered/cavity-riddled stem – not because this find is surely deadly, but because deadly false morel species cannot be reliably excluded. Never eat false morels raw. When in doubt : Tox Info Suisse 145.','{"Edible morel : cap honeycomb-pitted with true chambers ; cap AND stem form ONE continuous hollow from the stem base to the cap tip (longitudinal cut shows a shared hollow body)","Giant false morel : cap brain-like convoluted, bulging-folded (NO honeycomb pits) ; stem internally riddled with several hollows/chambers, not one single smooth hollow","IMPORTANT : the danger is NOT that Gyromitra gigas itself is strongly toxic (according to more recent research it contains little to no gyromitrin), but that it can hardly be reliably separated from the DEADLY spring false morel (Gyromitra esculenta) – therefore every brain-like convoluted false-morel find is to be avoided","The morel''s cap margin is attached to the stem ; the false morel''s cap is bulging-swollen and partly hangs free","Morel honeycomb walls are evenly ribbed ; false morel surface is irregularly furrowed like a walnut kernel/brain"}',false),
('morchelchampignon','gyromitra_gigas','es','La colmenilla comestible tiene una superficie del sombrero regularmente alveolada-hundida, la gyromitra gigante una superficie irregularmente enrollada como cerebro/nuez, abultada e hinchada, sin verdaderos alvéolos.','Ambas más bien inodoras-fúngicas ; el olor NO las separa de forma fiable.','Colmenilla comestible en primavera sobre suelos calcáreos ; gyromitra gigante saprobionte de la madera en primavera, sobre tocones podridos, madera enterrada y mantillo de corteza (a menudo coníferas). El período de aparición se solapa – el hábitat no separa con certeza.','Ambos ascomicetos (ascas) con esporada pálida, color crema – inadecuado para la distinción.','Cortar a lo largo : la verdadera colmenilla forma UNA sola cavidad continua desde la punta hasta la base del pie y es alveolada. Dejar en el sitio todo lo que esté enrollado como cerebro con pie tabicado/recorrido por cavidades – no porque este hallazgo sea con seguridad mortal, sino porque no se pueden excluir de forma fiable las especies de gyromitra mortales. Nunca consumir las gyromitras crudas. En caso de duda : Tox Info Suisse 145.','{"Colmenilla comestible : sombrero alveolado-hundido con verdaderas cámaras ; sombrero Y pie forman UNA cavidad continua desde la base del pie hasta la punta del sombrero (el corte longitudinal muestra un cuerpo hueco común)","Gyromitra gigante : sombrero enrollado como cerebro, abultado-plegado (SIN alvéolos hundidos) ; pie recorrido internamente por varias cavidades/cámaras, no por una sola cavidad lisa","IMPORTANTE : el peligro NO es que Gyromitra gigas sea en sí muy tóxica (según investigaciones recientes apenas contiene gyromitrina o ninguna), sino que apenas se distingue con certeza de la gyromitra primaveral MORTAL (Gyromitra esculenta) – por ello todo hallazgo de gyromitra enrollada como cerebro debe evitarse","El borde del sombrero de la colmenilla está soldado al pie ; el sombrero de la gyromitra está hinchado-abultado y cuelga en parte libremente","Las paredes de los alvéolos de la colmenilla están regularmente acostilladas ; la superficie de la gyromitra está irregularmente surcada como una nuez/un cerebro"}',false),
('morchelchampignon','gyromitra_gigas','fr','La morille comestible a une surface de chapeau régulièrement alvéolée-creusée, le gyromitre géant une surface irrégulièrement circonvoluée en cerveau/cerneau de noix, bosselée-gonflée sans véritables alvéoles.','Les deux plutôt fongiques discrets ; l''odeur ne les sépare PAS de façon fiable.','Morille comestible au printemps sur sols riches en calcaire ; gyromitre géant un saprobionte lignicole de printemps sur souches pourries, bois enterré et paillis d''écorce (souvent conifères). La période d''apparition se chevauche – l''habitat ne sépare pas sûrement.','Les deux ascomycètes (asques) à sporée pâle, crème – non adapté à la distinction.','Couper en long : la vraie morille est UNE cavité continue de la pointe à la base du pied et alvéolée. Laisser sur place tout ce qui est circonvolué en cerveau avec un pied cloisonné/traversé de cavités – non parce que cette trouvaille est sûrement mortelle, mais parce qu''on ne peut pas exclure de façon fiable les espèces de gyromitres mortelles. Gyromitres jamais crus. En cas de doute : Tox Info Suisse 145.','{"Morille comestible : chapeau alvéolé-creusé avec de véritables loges ; chapeau ET pied forment UNE cavité continue de la base du pied à la pointe du chapeau (la coupe longitudinale montre un corps creux commun)","Gyromitre géant : chapeau circonvolué en cerveau, bosselé-plissé (AUCUNE alvéole creusée) ; pied traversé à l''intérieur de plusieurs cavités/loges, pas une seule cavité lisse","IMPORTANT : le danger n''est PAS que Gyromitra gigas elle-même soit fortement toxique (selon des recherches récentes elle ne contient que peu ou pas de gyromitrine), mais qu''elle soit à peine séparable sûrement du gyromitre comestible MORTEL (Gyromitra esculenta) – c''est pourquoi toute trouvaille de gyromitre circonvoluée en cerveau est à éviter","Le bord du chapeau de la morille est attaché au pied ; le chapeau du gyromitre est bosselé-gonflé et pend en partie librement","Parois des alvéoles de la morille régulièrement côtelées ; surface du gyromitre irrégulièrement creusée comme un cerneau de noix/cerveau"}',false),
('morchelchampignon','gyromitra_gigas','it','La spugnola commestibile ha una superficie del cappello regolarmente alveolata-scavata, la gyromitra gigante una superficie irregolarmente avvolta a cervello/gheriglio di noce, bitorzoluta e rigonfia, senza veri alveoli.','Entrambe piuttosto inodori-fungine ; l''odore NON le separa in modo affidabile.','Spugnola commestibile in primavera su suoli calcarei ; gyromitra gigante saprobionte del legno in primavera, su ceppi marci, legno interrato e pacciame di corteccia (spesso conifere). Il periodo di comparsa si sovrappone – l''habitat non separa con certezza.','Entrambi ascomiceti (aschi) con sporata pallida, color crema – inadatto alla distinzione.','Tagliare per il lungo : la vera spugnola forma UNA sola cavità continua dalla punta fino alla base del gambo ed è alveolata. Lasciare sul posto tutto ciò che è avvolto a cervello con gambo camerato/percorso da cavità – non perché questo ritrovamento sia sicuramente mortale, ma perché non si possono escludere in modo affidabile le specie di gyromitra mortali. Mai consumare le gyromitre crude. In caso di dubbio : Tox Info Suisse 145.','{"Spugnola commestibile : cappello alveolato-scavato con vere camere ; cappello E gambo formano UNA cavità continua dalla base del gambo fino alla punta del cappello (la sezione longitudinale mostra un corpo cavo comune)","Gyromitra gigante : cappello avvolto a cervello, bitorzoluto-pieghettato (NESSUN alveolo scavato) ; gambo percorso internamente da più cavità/camere, non da una sola cavità liscia","IMPORTANTE : il pericolo NON è che Gyromitra gigas sia di per sé fortemente tossica (secondo ricerche recenti contiene quasi o per nulla gyromitrina), ma che si distingua a malapena con certezza dalla gyromitra primaverile MORTALE (Gyromitra esculenta) – perciò ogni ritrovamento di gyromitra avvolta a cervello è da evitare","Il bordo del cappello della spugnola è saldato al gambo ; il cappello della gyromitra è rigonfio e pende in parte liberamente","Le pareti degli alveoli della spugnola sono regolarmente costolate ; la superficie della gyromitra è irregolarmente solcata come un gheriglio di noce/un cervello"}',false),
('morchelchampignon','helvella_crispa','en','The edible morel shows a true honeycomb structure ; the white saddle a pitless, white, saddle-lobed cap and a markedly ribbed-chambered stem.','No reliable smell-based distinguishing feature.','Edible morel mainly spring on calcareous soils ; white saddle mainly summer–autumn along forest paths/edges in deciduous/mixed forest – season usually separates.','Both with pale spore print – no practical distinguishing feature.','Accept as morel only honeycombed caps with an internally continuous hollow. White saddle-/lobe forms with a furrowed chambered stem are false morels – do not eat.','{"Edible morel : rounded-ovoid, honeycomb-pitted cap ; cap and stem form a continuous hollow","White saddle : whitish, saddle-/lobe-folded cap without pits ; stem deeply longitudinally ribbed-furrowed with hollow chambers","The white saddle is gyromitrin-containing/toxic raw, not a harmless edible mushroom ; the morel is edible only cooked (poorly tolerated raw)","The morel surface consists of clear honeycomb pits ; the false morel surface of smooth convoluted lobes"}',false),
('morchelchampignon','helvella_crispa','es','La colmenilla comestible presenta una verdadera estructura alveolar ; la helvella crespa un sombrero blanco, lobulado en silla de montar, sin alvéolos, y un pie marcadamente acostillado-tabicado.','Ningún criterio olfativo de distinción fiable.','Colmenilla comestible sobre todo en primavera en suelos calcáreos ; helvella crespa sobre todo en verano–otoño a lo largo de caminos forestales/linderos en bosque caducifolio/mixto – la estación separa la mayoría de las veces.','Ambas con esporada clara – ningún criterio práctico de distinción.','Aceptar como colmenilla solo los sombreros alveolados con cavidad interna continua. Las formas blancas en silla/con lóbulos con pie tabicado y surcado son helvellas – no comer.','{"Colmenilla comestible : sombrero redondeado-ovoide, alveolado-hundido ; sombrero y pie forman una cavidad continua","Helvella crespa : sombrero blanquecino, plegado en silla/con lóbulos sin alvéolos ; pie profundamente acostillado-surcado a lo largo con cámaras huecas","La helvella crespa contiene gyromitrina/es tóxica cruda, no es una seta comestible inofensiva ; la colmenilla es comestible solo cocinada (mal tolerada cruda)","La superficie de la colmenilla está formada por alvéolos nítidos ; la superficie de la helvella por lóbulos lisos enrollados"}',false),
('morchelchampignon','helvella_crispa','fr','La morille comestible montre une véritable structure alvéolaire ; l''helvelle crépue un chapeau blanc, sans alvéoles, lobé en selle et un pied nettement côtelé-cloisonné.','Pas de critère olfactif fiable de séparation.','Morille comestible surtout au printemps sur sols riches en calcaire ; helvelle crépue surtout été–automne aux bords de chemins forestiers/lisières en forêt de feuillus/mixte – la saison sépare le plus souvent.','Les deux à sporée claire – pas un critère de séparation pratique.','N''accepter comme morille que les chapeaux alvéolés à cavité interne continue. Les formes blanches en selle/lobes à pied creux cloisonné sont des helvelles – ne pas manger.','{"Morille comestible : chapeau arrondi-ovoïde, alvéolé-creusé ; chapeau et pied forment une cavité continue","Helvelle crépue : chapeau blanchâtre, plié en selle/lobes sans alvéoles ; pied profondément côtelé-cannelé avec des loges creuses","L''helvelle crépue est contenant de la gyromitrine/crue toxique, pas un comestible inoffensif ; morille comestible seulement cuite (crue mal tolérée)","Surface de la morille faite d''alvéoles nettes ; surface de l''helvelle faite de lobes lisses circonvolués"}',false),
('morchelchampignon','helvella_crispa','it','La spugnola commestibile presenta una vera struttura alveolare ; l''helvella crespa un cappello bianco, lobato a sella, senza alveoli, e un gambo marcatamente costolato-camerato.','Nessun criterio olfattivo di distinzione affidabile.','Spugnola commestibile soprattutto in primavera su suoli calcarei ; helvella crespa soprattutto in estate–autunno lungo i sentieri forestali/margini in bosco di latifoglie/misto – la stagione separa il più delle volte.','Entrambe con sporata chiara – nessun criterio pratico di distinzione.','Accettare come spugnola solo i cappelli alveolati con cavità interna continua. Le forme bianche a sella/a lobi con gambo camerato e solcato sono helvelle – non mangiare.','{"Spugnola commestibile : cappello arrotondato-ovoidale, alveolato-scavato ; cappello e gambo formano una cavità continua","Helvella crespa : cappello biancastro, pieghettato a sella/a lobi senza alveoli ; gambo profondamente costolato-solcato per il lungo con camere cave","L''helvella crespa contiene gyromitrina/è tossica da cruda, non è un fungo commestibile innocuo ; la spugnola è commestibile solo da cotta (mal tollerata cruda)","La superficie della spugnola è fatta di alveoli netti ; la superficie dell''helvella di lobi lisci avvolti"}',false),
('morchella_elata','gyromitra_gigas','en','The black morel is tall-conical with elongated, ladder-like arranged dark ridges ; the giant false morel is squat-rounded and brain-like folded.','Smell of both species unspecifically mushroomy – not a distinguishing feature.','Black morel in spring on disturbed/calcareous soils and bark mulch ; giant false morel in spring as a wood saprobiont on rotten stumps/buried wood – habitat overlap possible.','Both ascomycetes with pale spore dust – no practical distinguishing feature.','Accept as morel only conical caps with true honeycomb AND a continuous hollow (longitudinal cut). Brain-like convoluted with a cavity-riddled stem = false morel = leave it, because deadly false morel species cannot be excluded with certainty.','{"Black morel : cap conical-pointed with longitudinally aligned, sharply delimited pits/chambers ; cap and stem form a continuous hollow","Giant false morel : cap rounded-bulbous, brain-like convoluted, NO conical tip and no true pits","Giant false morel stem internally riddled with several hollows ; black morel stem one continuous hollow","IMPORTANT : Gyromitra gigas itself contains, according to more recent research, little to no gyromitrin – the critical point is its confusability with the DEADLY spring false morel (G. esculenta) ; therefore avoid all false morel finds"}',false),
('morchella_elata','gyromitra_gigas','es','La colmenilla cónica es alta y cónica con costillas oscuras alargadas dispuestas en escalera ; la gyromitra gigante es achaparrada-redondeada y plegada como cerebro.','Olor de ambas especies fúngico inespecífico – no es un criterio de distinción.','Colmenilla cónica en primavera sobre suelos alterados/calcáreos y mantillo de corteza ; gyromitra gigante en primavera como saprobionte de la madera sobre tocones podridos/madera enterrada – solapamiento de hábitat posible.','Ambos ascomicetos con polvo esporal claro – ningún criterio práctico de distinción.','Aceptar como colmenilla solo los sombreros cónicos con verdaderos alvéolos Y con cavidad continua (corte longitudinal). Enrollado como cerebro con pie recorrido por cavidades = gyromitra = dejar en el sitio, porque las especies de gyromitra mortales no se pueden excluir con certeza.','{"Colmenilla cónica : sombrero cónico-puntiagudo con alvéolos/cámaras orientados longitudinalmente, nítidamente delimitados ; sombrero y pie forman una cavidad continua","Gyromitra gigante : sombrero redondeado-bulboso, enrollado como cerebro, SIN punta cónica y sin verdaderos alvéolos","Pie de la gyromitra gigante recorrido internamente por varias cavidades ; pie de la colmenilla cónica una cavidad continua","IMPORTANTE : Gyromitra gigas en sí contiene, según investigaciones recientes, apenas gyromitrina o ninguna – el punto crítico es la confundibilidad con la gyromitra primaveral MORTAL (G. esculenta) ; por ello evitar todos los hallazgos de gyromitra"}',false),
('morchella_elata','gyromitra_gigas','fr','La morille conique est haute-conique avec des côtes sombres allongées disposées en échelle ; le gyromitre géant est trapu-arrondi et plissé en forme de cerveau.','Odeur des deux espèces fongique non spécifique – pas un critère de séparation.','Morille conique au printemps sur sols perturbés/riches en calcaire et paillis d''écorce ; gyromitre géant au printemps comme saprobionte lignicole sur souches pourries/bois enterré – chevauchement possible dans l''habitat.','Les deux ascomycètes à poussière sporale claire – pas un critère de séparation pratique.','N''accepter comme morille que les chapeaux coniques à véritables alvéoles ET avec une cavité continue (coupe longitudinale). Circonvolué en cerveau avec un pied traversé de cavités = gyromitre = laisser sur place, parce que les espèces de gyromitres mortelles ne peuvent pas être exclues sûrement.','{"Morille conique : chapeau conique-pointu avec alvéoles/loges orientées longitudinalement, nettement délimitées ; chapeau et pied forment une cavité continue","Gyromitre géant : chapeau arrondi-bosselé, circonvolué en cerveau, AUCUNE pointe conique et pas de véritables alvéoles","Pied du gyromitre traversé à l''intérieur de plusieurs cavités ; pied de la morille conique une cavité continue","IMPORTANT : Gyromitra gigas elle-même contient selon des recherches récentes peu ou pas de gyromitrine – critique est la confusion possible avec le gyromitre printanier mortel (G. esculenta) ; c''est pourquoi éviter toutes les trouvailles de gyromitres"}',false),
('morchella_elata','gyromitra_gigas','it','La spugnola conica è alta e conica con costole scure allungate disposte a scala ; la gyromitra gigante è tozza-arrotondata e pieghettata a cervello.','Odore di entrambe le specie fungino aspecifico – non un criterio di distinzione.','Spugnola conica in primavera su suoli disturbati/calcarei e pacciame di corteccia ; gyromitra gigante in primavera come saprobionte del legno su ceppi marci/legno interrato – sovrapposizione di habitat possibile.','Entrambi ascomiceti con polvere sporale chiara – nessun criterio pratico di distinzione.','Accettare come spugnola solo i cappelli conici con veri alveoli E con cavità continua (sezione longitudinale). Avvolto a cervello con gambo percorso da cavità = gyromitra = lasciare sul posto, perché le specie di gyromitra mortali non si possono escludere con certezza.','{"Spugnola conica : cappello conico-appuntito con alveoli/camere orientati longitudinalmente, nettamente delimitati ; cappello e gambo formano una cavità continua","Gyromitra gigante : cappello arrotondato-bulboso, avvolto a cervello, NESSUNA punta conica e nessun vero alveolo","Gambo della gyromitra gigante percorso internamente da più cavità ; gambo della spugnola conica una cavità continua","IMPORTANTE : Gyromitra gigas di per sé contiene, secondo ricerche recenti, quasi o per nulla gyromitrina – il punto critico è la confondibilità con la gyromitra primaverile MORTALE (G. esculenta) ; perciò evitare tutti i ritrovamenti di gyromitra"}',false),
('paralepista_flaccida','ampulloclitocybe_clavipes','en','Strongly funnel-shaped, foxy orange-red-brown cap and slender stem in the Tawny Funnel Cap vs. greyish-white to grey-brown cap and club-swollen stem base in clavipes.','Tawny Funnel Cap inconspicuous to faintly sweetish ; clavipes weakly fruity.','The Tawny often clustered in thick needle/leaf litter ; clavipes in mixed and coniferous forests.','Both with cream-white spore print ; not reliably separating.','Check the stem base : club-shaped, spongy-swollen indicates clavipes ; not for the basket, never with alcohol.','{"Tawny Funnel Cap : deeply funnel-depressed, foxy orange-red-brown (strongly hygrophanous) cap and slender, NOT club-thickened stem ; clavipes with greyish-white to grey-brown cap and club-swollen stem base.","The Tawny often grows clustered/in rows in leaf litter and needle mulch ; clavipes rather single to gregarious.","Gills of the Tawny very crowded, forked and far decurrent, whitish to ochre-yellowish ; clavipes gills whitish, far decurrent.","clavipes toxic with alcohol (coprine syndrome) ; the Tawny is edible cooked (larger amounts can be hard to digest)."}',false),
('paralepista_flaccida','ampulloclitocybe_clavipes','es','Sombrero fuertemente infundibuliforme, pardo-anaranjado leonado a pardo-rojizo, y pie esbelto en el Clitocybe invertido ; sombrero gris-blanco a gris-pardo y base del pie engrosada-claviforme en clavipes.','Clitocybe invertido inodoro o ligeramente dulzón ; clavipes débilmente afrutado.','El invertido a menudo cespitoso en gruesa hojarasca de acículas/hojas ; clavipes en bosques mixtos y de coníferas.','Ambos con esporada blanco-crema ; no separa de forma fiable.','Examinar la base del pie : claviforme-esponjosa e hinchada indica clavipes ; no al cesto, nunca con alcohol.','{"Clitocybe invertido : sombrero profundamente infundibuliforme, pardo-anaranjado leonado a pardo-rojizo (fuertemente higrófano) y pie esbelto NO engrosado en maza ; clavipes con sombrero gris-blanco a gris-pardo y base del pie hinchada en maza.","El invertido crece a menudo cespitoso/en hileras en la hojarasca y el mantillo de acículas ; clavipes más bien solitario a gregario.","Láminas del invertido muy apretadas, bifurcadas y largamente decurrentes, blanquecinas a ocre-amarillentas ; láminas de clavipes blanquecinas, largamente decurrentes.","clavipes tóxico con alcohol (síndrome coprínico) ; el invertido es comestible cocinado (grandes cantidades pueden ser de difícil digestión)."}',false),
('paralepista_flaccida','ampulloclitocybe_clavipes','fr','Chapeau roux orange-rouge-brun, fortement en entonnoir, et pied élancé chez le clitocybe inversé vs. chapeau blanc-gris à gris-brun et base du pied renflée en massue chez clavipes.','Clitocybe inversé discret à légèrement sucré ; clavipes faiblement fruité.','Clitocybe inversé souvent en touffes dans une épaisse litière de conifères/feuillus ; clavipes en forêt mixte et de conifères.','Les deux à sporée blanc-crème ; non discriminant de façon fiable.','Vérifier la base du pied : renflée en massue-spongieuse indique clavipes, pas dans le panier, jamais avec de l''alcool.','{"Clitocybe inversé : chapeau profondément en entonnoir, roux orange-rouge-brun (fortement hygrophane) et pied élancé, NON épaissi en massue ; clavipes avec chapeau blanc-gris à gris-brun et base du pied renflée en massue.","Clitocybe inversé souvent en touffes/rangées dans la litière de feuillus et le paillis de conifères ; clavipes plutôt isolé à grégaire.","Lamelles du clitocybe inversé très serrées, fourchues et largement décurrentes, blanchâtres à ocre-jaunâtre ; lamelles de clavipes blanchâtres, largement décurrentes.","clavipes toxique avec l''alcool (syndrome coprinien) ; le clitocybe inversé est comestible cuit (de grandes quantités peuvent être difficiles à digérer)."}',false),
('paralepista_flaccida','ampulloclitocybe_clavipes','it','Cappello fortemente imbutiforme, bruno-arancio fulvo o bruno-rosso, e gambo slanciato nel Clitocybe rovesciato ; cappello grigio-bianco o grigio-bruno e base del gambo ingrossata-clavata in clavipes.','Clitocybe rovesciato inodore o lievemente dolciastro ; clavipes debolmente fruttato.','Il rovesciato spesso cespitoso in spessa lettiera di aghi/foglie ; clavipes in boschi misti e di conifere.','Entrambi con sporata bianco-crema ; non separa in modo affidabile.','Controllare la base del gambo : clavata-spugnosa e gonfia indica clavipes ; non metterlo nel cestino, mai con alcol.','{"Clitocybe rovesciato : cappello profondamente imbutiforme, bruno-arancio fulvo o bruno-rosso (fortemente igrofano) e gambo slanciato NON ingrossato a clava ; clavipes con cappello grigio-bianco o grigio-bruno e base del gambo gonfiata a clava.","Il rovesciato cresce spesso cespitoso/in file nella lettiera di foglie e nella pacciamatura di aghi ; clavipes piuttosto isolato o gregario.","Lamelle del rovesciato molto fitte, biforcate e lungamente decorrenti, biancastre o ocra-giallastre ; lamelle di clavipes biancastre, lungamente decorrenti.","clavipes tossico con l''alcol (sindrome coprinica) ; il rovesciato è commestibile da cotto (grandi quantità possono essere di difficile digestione)."}',false),
('pluteus_cervinus','megacollybia_platyphylla','en','Deer shield with pink gills (when mature) and free gill attachment ; the broad-gilled fungus with white, broad, adnate gills and white rhizomorphs at the base.','Both inconspicuously mushroomy, not a distinguishing feature.','Both on/in rotten deciduous wood ; the broad-gilled fungus with conspicuous white mycelial cords at the stem foot.','Deer shield pink, broad-gilled fungus white — THE decisive distinguishing feature.','Make a spore print : pink = deer shield, white = broad-gilled fungus. The broad-gilled fungus is regarded as toxic/indigestible (gastrointestinal) and does not belong in the basket.','{"Deer shield (edible) has PINK spore print and, when old, pink gills, free at the stem ; the broad-gilled fungus has WHITE spore print and white gills adnate to the stem","The broad-gilled fungus with conspicuous coarse white rhizomorphs (mycelial cords) at the stem base ; the deer shield without such cords","Gills of the broad-gilled fungus very broad and distant ; deer shield more crowded","The deer shield mostly grows singly on wood, the broad-gilled fungus on wood/roots with cords"}',false),
('pluteus_cervinus','megacollybia_platyphylla','es','Plúteo con láminas rosas (al madurar) y inserción libre de las láminas ; la colibia de láminas anchas con láminas blancas, anchas, adnatas y rizomorfos blancos en la base.','Ambos inodoros-fúngicos, no es un criterio de distinción.','Ambos sobre/en madera caduca podrida ; la colibia de láminas anchas con llamativos cordones miceliares blancos en el pie.','Plúteo rosa, colibia de láminas anchas blanco — EL criterio de distinción decisivo.','Hacer una esporada : rosa = plúteo, blanco = colibia de láminas anchas. La colibia de láminas anchas se considera tóxica/indigesta (gastrointestinal) y no debe ir al cesto.','{"Plúteo color corzo (comestible) tiene esporada ROSA y, con la edad, láminas rosas, libres en el pie ; la colibia de láminas anchas tiene esporada BLANCA y láminas blancas, adnatas al pie","La colibia de láminas anchas con llamativos rizomorfos blancos gruesos (cordones miceliares) en la base del pie ; el plúteo sin tales cordones","Láminas de la colibia de láminas anchas muy anchas y separadas ; plúteo más apretado","El plúteo crece la mayoría de las veces solitario sobre madera, la colibia de láminas anchas sobre madera/raíces con cordones"}',false),
('pluteus_cervinus','megacollybia_platyphylla','fr','Plutée brun de cerf à lamelles roses (mûres) et insertion libre des lamelles ; mégacollybie à lamelles blanches, larges, adnées et rhizomorphes blancs à la base.','Les deux discrets-fongiques, pas un critère de séparation.','Les deux sur/dans le bois de feuillus pourri ; la mégacollybie avec des cordons mycéliens blancs remarquables au pied.','Plutée rose, mégacollybie blanche — LE critère de séparation décisif.','Faire une sporée : rose = plutée, blanche = mégacollybie. La mégacollybie est considérée comme toxique/indigeste (gastro-intestinal) et n''a pas sa place dans le panier.','{"Plutée brun de cerf (comestible) a une sporée ROSE et avec l''âge des lamelles roses, libres au pied ; mégacollybie a une sporée BLANCHE et des lamelles blanches, adnées au pied","Mégacollybie avec des rhizomorphes blancs grossiers remarquables (cordons mycéliens) à la base du pied ; plutée sans de tels cordons","Lamelles de la mégacollybie très larges et espacées ; plutée plus serrées","Plutée pousse le plus souvent isolé sur bois, mégacollybie sur bois/racines avec des cordons"}',false),
('pluteus_cervinus','megacollybia_platyphylla','it','Pluteo con lamelle rosa (a maturità) e attacco libero delle lamelle ; la collibia a lamelle larghe con lamelle bianche, larghe, adnate e rizomorfe bianche alla base.','Entrambi inodori-fungini, non un criterio di distinzione.','Entrambi su/in legno di latifoglie marcio ; la collibia a lamelle larghe con evidenti cordoni miceliari bianchi al piede.','Pluteo rosa, collibia a lamelle larghe bianco — IL criterio di distinzione decisivo.','Fare una sporata : rosa = pluteo, bianco = collibia a lamelle larghe. La collibia a lamelle larghe è considerata tossica/indigesta (disturbi gastrointestinali) e non va nel cestino.','{"Pluteo color cerbiatto (commestibile) ha sporata ROSA e, con l''età, lamelle rosa, libere al gambo ; la collibia a lamelle larghe ha sporata BIANCA e lamelle bianche, adnate al gambo","La collibia a lamelle larghe con evidenti rizomorfe bianche grossolane (cordoni miceliari) alla base del gambo ; il pluteo senza tali cordoni","Lamelle della collibia a lamelle larghe molto larghe e distanziate ; pluteo più fitto","Il pluteo cresce per lo più isolato su legno, la collibia a lamelle larghe su legno/radici con cordoni"}',false),
('pluteus_cervinus','pluteus_salicinus','en','Both have free, flesh-pink gills on dead wood ; the decisive feature is the grey-greenish hue and the possible blue-green discolouration at pressure/cut points of the toxic willow shield, as opposed to the deer-brown, non-bluing edible.','Deer shield mildly radish-/earthy-smelling ; willow shield faintly radish-like — smell does not separate reliably.','Both grow on rotten deciduous wood/dead wood ; the willow shield prefers willows/poplars/alders (floodplain forest), overlap with the deer shield possible.','Both have a pink spore print — identical, therefore not a distinguishing feature ; watch the colour and the blue discolouration.','Leave shields with a grey-greenish cap or blue-green discolouration at cut/pressure points — psychoactive and toxic.','{"Deer shield : warm deer-brown to dark-brown, often radially fibrillose cap ; willow shield paler grey to grey-greenish/bluish-grey, darker towards the cap centre.","The willow shield often discolours bluish-greenish on injury/pressure (especially the stem base) — psilocybin indicator ; the deer shield does not blue.","Both have free gills, white when young, turning flesh-pink through the pink spore print — NOT a distinguishing feature.","The willow shield is usually smaller and more slender than the often sturdy deer shield ; grows preferentially on willow/poplar/alder.","The willow shield contains psilocybin/psilocin and is toxic (psychoactive)."}',false),
('pluteus_cervinus','pluteus_salicinus','es','Ambos tienen láminas libres, rosa carne, sobre madera muerta ; el elemento decisivo es el tono gris-verdoso y el posible viraje azul-verde en los puntos de presión/corte del plúteo gris-verde tóxico, frente al comestible color corzo que no vira al azul.','Plúteo color corzo suavemente rabanoso/terroso ; plúteo gris-verde débilmente rabanoso — el olor no separa de forma fiable.','Ambos crecen sobre madera caduca podrida/madera muerta ; el gris-verde prefiere sauces/álamos/alisos (bosque de ribera), solapamiento con el color corzo posible.','Ambos tienen esporada rosa — idéntica, por lo que no es un criterio de distinción ; prestar atención al color y al viraje azul.','Dejar en el sitio los plúteos con sombrero gris-verdoso o con viraje azul-verde en los puntos de corte/presión — psicoactivo y tóxico.','{"Plúteo color corzo : sombrero pardo-corzo cálido a pardo oscuro, a menudo radialmente fibriloso ; plúteo gris-verde más pálido gris a gris-verdoso/azul-grisáceo, más oscuro hacia el centro del sombrero.","El plúteo gris-verde vira a menudo a azulado-verdoso al herirlo/presionarlo (sobre todo la base del pie) — indicio de psilocibina ; el plúteo color corzo no vira al azul.","Ambos tienen láminas libres, blancas de jóvenes, que se vuelven rosa carne por la esporada rosa — NO es un criterio de distinción.","El plúteo gris-verde es generalmente más pequeño y grácil que el plúteo color corzo a menudo robusto ; crece de preferencia sobre sauce/álamo/aliso.","El plúteo gris-verde contiene psilocibina/psilocina y es tóxico (psicoactivo)."}',false),
('pluteus_cervinus','pluteus_salicinus','fr','Les deux ont des lames libres, rose chair, sur bois mort ; l''élément décisif est la teinte gris-verdâtre et le possible bleuissement vert-bleu aux points de pression/coupure du plutée gris-vert toxique, par opposition au comestible couleur de chevreuil qui ne bleuit pas.','Plutée couleur de chevreuil doucement raviforme/terreux ; plutée gris-vert faiblement raviforme — l''odeur ne sépare pas de façon fiable.','Les deux poussent sur bois feuillu pourri/bois mort ; le gris-vert préfère saules/peupliers/aulnes (forêt alluviale), chevauchement avec le couleur de chevreuil possible.','Les deux ont une sporée rose — identique, donc pas un critère de distinction ; faire attention à la couleur et au bleuissement.','Laisser sur place les plutées à chapeau gris-verdâtre ou à bleuissement vert-bleu aux points de coupure/pression — psychoactif et toxique.','{"Plutée couleur de chevreuil : chapeau brun-chevreuil chaud à brun foncé, souvent radialement fibrilleux ; plutée gris-vert plus pâle gris à gris-verdâtre/bleu-gris, plus foncé vers le centre du chapeau.","Le plutée gris-vert se colore souvent en bleu-vert à la blessure/pression (surtout la base du pied) — indice de psilocybine ; le plutée couleur de chevreuil ne bleuit pas.","Les deux ont des lames libres, blanches jeunes, devenant rose chair par la sporée rose — PAS un critère de distinction.","Le plutée gris-vert est généralement plus petit et plus gracile que le plutée couleur de chevreuil souvent robuste ; pousse de préférence sur saule/peuplier/aulne.","Le plutée gris-vert contient de la psilocybine/psilocine et est toxique (psychoactif)."}',false),
('pluteus_cervinus','pluteus_salicinus','it','Entrambi hanno lamelle libere, rosa carne, su legno morto ; l''elemento decisivo è la tonalità grigio-verdastra e il possibile viraggio blu-verde nei punti di pressione/taglio del pluteo grigio-verde tossico, rispetto al commestibile color cerbiatto che non vira al blu.','Pluteo color cerbiatto delicatamente rafanoide/terroso ; pluteo grigio-verde debolmente rafanoide — l''odore non separa in modo affidabile.','Entrambi crescono su legno di latifoglie marcio/legno morto ; il grigio-verde preferisce salici/pioppi/ontani (foresta golenale), sovrapposizione col color cerbiatto possibile.','Entrambi hanno sporata rosa — identica, quindi non un criterio di distinzione ; fare attenzione al colore e al viraggio blu.','Lasciare sul posto i plutei con cappello grigio-verdastro o con viraggio blu-verde nei punti di taglio/pressione — psicoattivo e tossico.','{"Pluteo color cerbiatto : cappello bruno-cerbiatto caldo o bruno scuro, spesso radialmente fibrilloso ; pluteo grigio-verde più pallido grigio o grigio-verdastro/azzurro-grigio, più scuro verso il centro del cappello.","Il pluteo grigio-verde vira spesso al bluastro-verdastro alla lesione/pressione (soprattutto la base del gambo) — indizio di psilocibina ; il pluteo color cerbiatto non vira al blu.","Entrambi hanno lamelle libere, bianche da giovani, che diventano rosa carne per la sporata rosa — NON un criterio di distinzione.","Il pluteo grigio-verde è generalmente più piccolo e più gracile del pluteo color cerbiatto spesso robusto ; cresce di preferenza su salice/pioppo/ontano.","Il pluteo grigio-verde contiene psilocibina/psilocina ed è tossico (psicoattivo)."}',false),
('ramaria_botrytis','ramaria_formosa','en','Rosso coral / cauliflower coral: fleshy white stem, whitish/buff branches with wine-red/pinkish tips; the beautiful coral (Ramaria formosa) is uniformly orange-salmon with yellow tips and lacks a thick white stem.','Both mild and mushroomy; smell does not distinguish them — watch for the bitter taste of Ramaria formosa.','Both grow on the ground in woodland; Ramaria formosa prefers deciduous forest (often beech), the cauliflower coral deciduous/mixed forest — habitat does not distinguish them.','Both have ochre-yellowish spore print — no practical distinguishing feature; rely on colour, stem shape, colour change and taste.','Never eat corals with an orange body, yellow tips, wine-red bruising on pressure or a bitter taste — only corals with pure white flesh and a mild taste are considered suitable for beginners.','{"Cauliflower coral (Ramaria botrytis): thick, squat whitish stem with cauliflower-like branched arms whose tips are coloured wine-red/purple-pink; Ramaria formosa is overall pale orange-salmon with yellow branch tips.","Ramaria formosa often bruises brownish-wine-red on pressure/injury; the flesh of the cauliflower coral stays white or hardly changes colour.","Ramaria formosa tastes bitter (spit out the taste sample!), cauliflower coral is mild.","Ramaria formosa has thinner, orange-salmon branches with yellow tips; the cauliflower coral has a massive white basal stem and wine-red tones only at the branch tips.","Ramaria formosa is gastrointestinally poisonous (nausea, vomiting, diarrhoea, cramps)."}',false),
('ramaria_botrytis','ramaria_formosa','es','Ramaria botrytis (coliflor): pie carnoso blanco, ramas blanquecinas/ante con puntas rojo-vino/rosadas; la Ramaria formosa es enteramente naranja-salmón con puntas amarillas y sin pie blanco grueso.','Ambas con olor suave a hongo; el olor no las distingue — atender al sabor amargo de la Ramaria formosa.','Ambas crecen en el suelo del bosque; la Ramaria formosa prefiere el bosque de frondosas (a menudo haya), la Ramaria botrytis el bosque de frondosas/mixto — el hábitat no las distingue.','Ambas con esporada amarillo-ocre — sin criterio distintivo práctico; basarse en color, forma del pie, viraje de color y sabor.','Nunca comer ramarias con cuerpo naranja, puntas amarillas, viraje rojo-vino a la presión o sabor amargo — solo las ramarias con carne blanco puro y sabor suave se consideran aptas para principiantes.','{"Ramaria botrytis: pie blanquecino grueso y rechoncho con ramas ramificadas como coliflor cuyas puntas están coloreadas de rojo-vino/púrpura-rosado; la Ramaria formosa en conjunto naranja-salmón pálido con puntas de las ramas amarillas.","La Ramaria formosa vira a menudo al pardusco-rojo-vino a la presión/lesión; la carne de la Ramaria botrytis permanece blanca o apenas vira.","La Ramaria formosa sabe amarga (¡escupir la prueba de sabor!), la Ramaria botrytis es suave.","La Ramaria formosa tiene ramas más finas, naranja-salmón, con puntas amarillas; la Ramaria botrytis tiene un pie basal blanco macizo y tonos rojo-vino solo en las puntas de las ramas.","La Ramaria formosa es tóxica para el aparato gastrointestinal (náuseas, vómitos, diarrea, cólicos)."}',false),
('ramaria_botrytis','ramaria_formosa','fr','Clavaire chou-fleur : pied charnu blanc, rameaux blanchâtres/chamois à pointes lie-de-vin/rosées ; la Clavaire jolie est entièrement orange-saumon avec des pointes jaunes et sans gros pied blanc.','Toutes deux à odeur douce de champignon ; l''odeur ne distingue pas — prêter attention au goût amer de la Clavaire jolie.','Toutes deux poussent au sol en forêt ; la Clavaire jolie préfère la forêt de feuillus (souvent hêtre), la Clavaire chou-fleur la forêt de feuillus/mixte — l''habitat ne distingue pas.','Toutes deux à sporée jaune ocre — pas de critère de distinction pratique ; se fier à la couleur, à la forme du pied, au changement de couleur et au goût.','Ne jamais manger une clavaire à corps orange, à pointes jaunes, à virage lie-de-vin à la pression ou au goût amer — seules les clavaires à chair d''un blanc pur et au goût doux sont considérées comme adaptées aux débutants.','{"Clavaire chou-fleur (Ramaria botrytis) : pied blanchâtre épais et trapu avec des rameaux ramifiés en chou-fleur dont les pointes sont colorées en lie-de-vin/pourpre-rosé ; la Clavaire jolie est dans l''ensemble d''un orange-saumon pâle avec des pointes de rameaux jaunes.","La Clavaire jolie vire souvent au brunâtre-lie-de-vin à la pression/blessure ; la chair de la Clavaire chou-fleur reste blanche ou ne change presque pas de couleur.","La Clavaire jolie a un goût amer (recracher la prise de goût !), la Clavaire chou-fleur est douce.","La Clavaire jolie a des rameaux plus fins, orange-saumon, à pointes jaunes ; la Clavaire chou-fleur a un pied de base blanc massif et des tons lie-de-vin seulement aux pointes des rameaux.","La Clavaire jolie est toxique pour l''appareil gastro-intestinal (nausées, vomissements, diarrhée, coliques)."}',false),
('ramaria_botrytis','ramaria_formosa','it','Ramaria botrytis : gambo carnoso bianco, rami biancastri/camoscio con apici rosso-vinato/rosati ; la Ramaria formosa è interamente arancio-salmone con apici gialli e senza grosso gambo bianco.','Entrambe con odore mite di fungo ; l''odore non distingue — fare attenzione al sapore amaro della Ramaria formosa.','Entrambe crescono al suolo nel bosco ; la Ramaria formosa predilige il bosco di latifoglie (spesso faggio), la Ramaria botrytis il bosco di latifoglie/misto — l''habitat non distingue.','Entrambe con sporata giallo-ocra — nessun criterio distintivo pratico ; basarsi su colore, forma del gambo, viraggio e sapore.','Non mangiare mai ramarie con corpo arancione, apici gialli, viraggio vinato alla pressione o sapore amaro — solo le ramarie con carne bianco puro e sapore mite sono considerate adatte ai principianti.','{"Ramaria botrytis : gambo biancastro spesso e tozzo con rami ramificati a cavolfiore le cui punte sono colorate di rosso-vinato/porpora-rosato ; la Ramaria formosa nel complesso arancio-salmone pallido con apici dei rami gialli.","La Ramaria formosa vira spesso al brunastro-vinato alla pressione/lesione ; la carne della Ramaria botrytis resta bianca ovvero quasi non vira.","La Ramaria formosa ha sapore amaro (sputare la prova di assaggio !), la Ramaria botrytis è mite.","La Ramaria formosa ha rami più sottili, arancio-salmone, con apici gialli ; la Ramaria botrytis ha un massiccio gambo basale bianco e toni vinati solo alle punte dei rami.","La Ramaria formosa è tossica per l''apparato gastro-intestinale (nausea, vomito, diarrea, coliche)."}',false),
('rhodocollybia_butyracea','gymnopus_peronatus','en','The buttery collybia has a greasy-glossy, hygrophanous zonally fading cap; the wood woollyfoot (Gymnopus peronatus) a matt, uniformly leather-brown cap with a felted stem base.','Both inconspicuous; the acrid-burning taste (taste sample) is the reliable distinguishing feature.','Both in conifer/deciduous woodland litter, often in troops — habitat does not distinguish.','Buttery collybia with cream spore print, often with a faint pink tone; wood woollyfoot whitish-cream — only faintly distinguishable in the spore print.','Bite test: if it burns acridly, leave it. The greasy-slimy, mild-tasting cap is the buttery collybia — nevertheless only collect it when identification is certain.','{"Wood woollyfoot: acrid-burning taste, tough stem with strigose-felted base, matt leather-brown cap","Buttery collybia: mild taste, greasy-smooth/''buttery'' glossy slimy cap, hygrophanous, longitudinally grooved-cartilaginous stem without strigose felt","The buttery collybia has a pale, often faintly pink-tinged spore print (Rhodocollybia) and a softer consistency; the wood woollyfoot has a cream-white spore print and is tough-leathery","Wood woollyfoot acrid/suspected toxic-stomach-irritating — buttery collybia mild, edible (gastronomically little esteemed)"}',false),
('rhodocollybia_butyracea','gymnopus_peronatus','es','La colibia mantecosa tiene un sombrero graso-brillante, higrófano que se decolora por zonas; la colibia ardiente (Gymnopus peronatus) un sombrero mate, uniformemente pardo-cuero, con base del pie afieltrada.','Ambas discretas; el sabor acre-ardiente (prueba de sabor) es el carácter distintivo seguro.','Ambas en la hojarasca de bosque de coníferas/frondosas, a menudo en grupos — el hábitat no distingue.','Colibia mantecosa con esporada color crema, a menudo con tono rosado débil; colibia ardiente blanquecino-crema — distinguibles solo débilmente en la esporada.','Prueba de mordisco: si arde acremente, dejarla en el sitio. El sombrero graso-viscoso de sabor suave es la colibia mantecosa — recogerla no obstante solo con determinación segura.','{"Colibia ardiente: sabor acre-ardiente, pie tenaz con base estrigosa-afieltrada, sombrero mate pardo-cuero","Colibia mantecosa: sabor suave, sombrero graso-liso/''mantecoso'' brillante y viscoso, higrófano, pie longitudinalmente estriado-cartilaginoso sin fieltro estrigoso","La colibia mantecosa tiene esporada pálida, a menudo débilmente teñida de rosa (Rhodocollybia) y consistencia más blanda; la colibia ardiente con esporada blanco-crema y tenaz-coriácea","Colibia ardiente acre/sospechosa de toxicidad-irritante para el estómago — colibia mantecosa suave, comestible (gastronómicamente poco apreciada)"}',false),
('rhodocollybia_butyracea','gymnopus_peronatus','fr','Le collybie beurré a un chapeau gras-brillant, hygrophane se décolorant en zones ; le collybie à pied feutré un chapeau mat, uniformément brun-cuir avec une base du pied feutrée.','Les deux discrets ; le goût brûlant-âcre (échantillon) est le critère de séparation sûr.','Les deux dans la litière de forêt de conifères/feuillus, souvent en troupe – l''habitat ne sépare pas.','Collybie beurré crème, souvent avec une faible teinte rose ; collybie à pied feutré blanchâtre-crème – distinguable seulement faiblement à la sporée.','Test de morsure : si cela brûle âcrement, laisser. Pour le chapeau gras-graisseux, doux au goût, il s''agit du collybie beurré – néanmoins ne récolter qu''avec une détermination sûre.','{"Collybie à pied feutré : goût âcre-brûlant, pied coriace avec une base strigueuse-feutrée, chapeau mat brun-cuir","Collybie beurré : goût doux, chapeau gras-lisse/« beurré » graisseux brillant, hygrophane, pied longitudinalement rainuré-cartilagineux sans feutre strigueux","Collybie beurré a une sporée pâle, souvent faiblement teintée de rose (Rhodocollybia) et une consistance plus molle ; collybie à pied feutré à sporée crème-blanche et coriace-cuir","Collybie à pied feutré âcre/suspect de toxicité-irritant pour l''estomac – collybie beurré doux, comestible (peu apprécié gustativement)"}',false),
('rhodocollybia_butyracea','gymnopus_peronatus','it','Il Rhodocollybia butyracea ha un cappello grasso-lucente, igrofano che sbiadisce a zone ; il Gymnopus peronatus un cappello opaco, uniformemente bruno-cuoio, con base del gambo feltrata.','Entrambi poco appariscenti ; il sapore acre-bruciante (prova di assaggio) è il sicuro carattere distintivo.','Entrambi nella lettiera di bosco di conifere/latifoglie, spesso in gruppi — l''habitat non distingue.','Rhodocollybia butyracea a sporata color crema, spesso con debole tono rosa ; Gymnopus peronatus biancastro-crema — distinguibili solo debolmente nella sporata.','Prova di morso : se brucia acremente, lasciare sul posto. Il cappello grasso-vischioso dal sapore mite è il Rhodocollybia butyracea — raccoglierlo comunque solo con determinazione sicura.','{"Gymnopus peronatus : sapore acre-bruciante, gambo tenace con base strigosa-feltrata, cappello opaco bruno-cuoio","Rhodocollybia butyracea : sapore mite, cappello grasso-liscio/''burroso'' lucente e vischioso, igrofano, gambo longitudinalmente striato-cartilagineo senza feltro strigoso","Il Rhodocollybia butyracea ha sporata pallida, spesso debolmente sfumata di rosa (Rhodocollybia) e consistenza più molle ; il Gymnopus peronatus con sporata bianco-crema e tenace-coriaceo","Gymnopus peronatus acre/sospetto di tossicità-irritante per lo stomaco — Rhodocollybia butyracea mite, commestibile (poco apprezzato gustativamente)"}',false),
('schopftintling','coprinopsis_picacea','en','Pure white, scaly shaggy ink cap with ring vs. the brown-black magpie inkcap with white veil flecks and without a ring.','Magpie inkcap unpleasantly musty-tarry; shaggy ink cap neutral and pleasant.','Magpie inkcap prefers humus- and lime-rich deciduous/beech forests and forest-path edges; shaggy ink cap on nutrient-rich meadows, path and road verges, ruderal areas.','Both black spore print (deliquescent); not distinguishing.','A black-and-white spotted inkcap specimen smelling musty-tarry and without a stem ring should as a rule be left standing.','{"Shaggy ink cap: white, cylindrical-elongated cap with erect white scales and a movable ring on the stem; magpie inkcap with dark-brown-black cap covered with white, wipeable veil flecks (magpie/woodpecker pattern), without a ring.","Shaggy ink cap when young neutral and pleasant in smell; magpie inkcap smells unpleasantly musty-tarry.","Magpie inkcap slimmer, taller and more fragile; the young shaggy ink cap stouter/squatter.","The magpie inkcap is inedible (musty-tarry taste); the shaggy ink cap when young (gills still white) is an excellent edible mushroom."}',false),
('schopftintling','coprinopsis_picacea','es','Coprino melenudo de un blanco puro, escamoso, con anillo, frente al coprino picazo pardo-negro con copos de velo blancos y sin anillo.','El coprino picazo huele desagradablemente a moho-alquitrán; el coprino melenudo es neutro y agradable.','El coprino picazo prefiere bosques de frondosas/hayas ricos en humus y cal y los bordes de senderos forestales; el coprino melenudo en praderas ricas en nutrientes, bordes de senderos y caminos, áreas ruderales.','Ambos con esporada negra (delicuescente); no distintivo.','Un ejemplar de coprino moteado de blanco y negro, con olor a moho-alquitrán y sin anillo en el pie, debe por principio dejarse en el sitio.','{"Coprino melenudo: sombrero blanco, cilíndrico-alargado con escamas blancas erguidas y anillo móvil en el pie; coprino picazo con sombrero pardo oscuro-negro cubierto de copos de velo blancos que se pueden frotar (patrón urraca/pico), sin anillo.","Coprino melenudo joven de olor neutro y agradable; el coprino picazo huele desagradablemente a moho-alquitrán.","Coprino picazo más esbelto, más alto y más frágil; el joven coprino melenudo más robusto/rechoncho.","El coprino picazo es incomible (sabor a moho-alquitrán); el coprino melenudo joven (láminas aún blancas) es un excelente hongo comestible."}',false),
('schopftintling','coprinopsis_picacea','fr','Coprin chevelu blanc pur, écailleux avec anneau vs. coprin pie brun-noir avec des flocons de voile blancs et sans anneau.','Coprin pie désagréablement moisi-goudronné ; coprin chevelu neutre et agréable.','Coprin pie préfère les forêts de feuillus/hêtres riches en humus et calcaire et les bords de chemins forestiers ; coprin chevelu sur prairies riches en nutriments, bords de chemins, friches.','Les deux à sporée noire (déliquescente) ; non discriminant.','Laisser par principe sur place tout exemplaire de coprin tacheté noir-blanc à odeur moisi-goudronnée sans anneau au pied.','{"Coprin chevelu : chapeau blanc, cylindrique-allongé avec des écailles blanches dressées et un anneau mobile au pied ; coprin pie avec un chapeau brun foncé-noir couvert de flocons de voile blancs, essuyables (motif pie/écaille), sans anneau.","Coprin chevelu jeune neutre d''odeur et agréable ; coprin pie sent désagréablement le moisi-goudronné.","Coprin pie plus élancé, plus haut et plus fragile ; le jeune coprin chevelu plus robuste/trapu.","Coprin pie non comestible (goût moisi-goudronné) ; coprin chevelu jeune (avec lamelles encore blanches) un excellent comestible."}',false),
('schopftintling','coprinopsis_picacea','it','Coprinus comatus di un bianco puro, squamoso, con anello, contro il Coprinopsis picacea bruno-nero con fiocchi di velo bianchi e senza anello.','Il Coprinopsis picacea odora sgradevolmente di muffa-catrame ; il Coprinus comatus è neutro e gradevole.','Il Coprinopsis picacea predilige boschi di latifoglie/faggi ricchi di humus e calcare e i margini dei sentieri forestali ; il Coprinus comatus su prati ricchi di nutrienti, margini di sentieri e strade, aree ruderali.','Entrambi con sporata nera (deliquescente) ; non distintivo.','Un esemplare di coprino macchiato di bianco e nero, dall''odore di muffa-catrame e senza anello sul gambo, va per principio lasciato sul posto.','{"Coprinus comatus : cappello bianco, cilindrico-allungato con squame bianche erette e anello mobile sul gambo ; Coprinopsis picacea con cappello bruno scuro-nero ricoperto di fiocchi di velo bianchi asportabili (motivo gazza/picchio), senza anello.","Coprinus comatus giovane dall''odore neutro e gradevole ; Coprinopsis picacea odora sgradevolmente di muffa-catrame.","Coprinopsis picacea più slanciato, più alto e più fragile ; il giovane Coprinus comatus più robusto/tozzo.","Il Coprinopsis picacea è immangiabile (sapore di muffa-catrame) ; il Coprinus comatus giovane (lamelle ancora bianche) è un eccellente fungo commestibile."}',false),
('tricholoma_cingulatum','tricholoma_scalpturatum','en','cingulatum with a ring/veil zone on the stem, scalpturatum ringless and yellowing.','both mealy; cingulatum milder.','cingulatum by willows (often moist/floodplain forest), more rarely birches; scalpturatum widely in deciduous/mixed/coniferous forest and park stands.','Both white - not a distinguishing feature.','A distinct ring on the stem AND a willow/birch association argue for cingulatum; if the ring is missing and the flesh yellows, hands off. With grey earth knights in general, maximum caution (deadly tiger knight Tricholoma pardinum similar).','{"T. cingulatum (edible): has a distinct, membranous RING/veil zone on the stem - scalpturatum is ringless. The ring is the most important distinguishing feature from all other earth knights.","T. scalpturatum (suspected toxic/inferior, do NOT collect): no ring, gills and flesh yellow distinctly.","cingulatum lives in mycorrhiza with willows (Salix), more rarely birches (Betula) - often in moist/floodplain sites.","Smell of both mealy; cingulatum mild.","Ring zone present + willow/birch association = cingulatum; ringless + yellowing = scalpturatum."}',false),
('tricholoma_cingulatum','tricholoma_scalpturatum','es','cingulatum con anillo/zona de velo en el pie, scalpturatum sin anillo y amarilleante.','ambos harinosos; cingulatum más suave.','cingulatum bajo los sauces (a menudo húmedo/bosque de ribera), más raramente abedules; scalpturatum ampliamente en bosque de frondosas/mixto/coníferas y masas de parques.','Ambos blancos - no es un criterio distintivo.','Un anillo neto en el pie Y una vinculación con sauce/abedul abogan por cingulatum; si falta el anillo y la carne amarillea, no tocar. En los Tricholoma terrosos grises en general, máxima prudencia (Tricholoma pardinum mortal, parecido).','{"T. cingulatum (comestible): posee un ANILLO/zona de velo membranoso neto en el pie - scalpturatum es sin anillo. El anillo es el carácter distintivo más importante respecto a todos los demás Tricholoma terrosos.","T. scalpturatum (sospechoso de toxicidad/inferior, NO recoger): sin anillo, láminas y carne amarillean netamente.","cingulatum vive en micorriza con los sauces (Salix), más raramente los abedules (Betula) - a menudo en estaciones húmedas/de ribera.","Olor de ambos harinoso; cingulatum suave.","Zona de anillo presente + vinculación sauce/abedul = cingulatum; sin anillo + amarilleante = scalpturatum."}',false),
('tricholoma_cingulatum','tricholoma_scalpturatum','fr','cingulatum avec anneau/zone de voile au pied, scalpturatum sans anneau et jaunissant.','tous deux farineux ; cingulatum plus doux.','cingulatum sous les saules (souvent humide/forêt alluviale), plus rarement bouleaux ; scalpturatum largement en forêt de feuillus/mixte/conifères et peuplements de parcs.','Tous deux blancs - pas un critère de distinction.','Un anneau net au pied ET un lien avec saule/bouleau plaident pour cingulatum ; si l''anneau manque et que la chair jaunit, ne pas toucher. Chez les tricholomes terreux gris en général, prudence maximale (tricholome tigré mortel Tricholoma pardinum semblable).','{"T. cingulatum (comestible) : possède un ANNEAU/zone de voile membraneux net au pied - scalpturatum est sans anneau. L''anneau est le critère de distinction le plus important par rapport à tous les autres tricholomes terreux.","T. scalpturatum (suspect de toxicité/médiocre, NE PAS cueillir) : pas d''anneau, lames et chair jaunissent nettement.","cingulatum vit en mycorhize avec les saules (Salix), plus rarement les bouleaux (Betula) - souvent en stations humides/alluviales.","Odeur des deux farineuse ; cingulatum doux.","Zone d''anneau présente + lien saule/bouleau = cingulatum ; sans anneau + jaunissant = scalpturatum."}',false),
('tricholoma_cingulatum','tricholoma_scalpturatum','it','cingulatum con anello/zona di velo al gambo, scalpturatum senza anello e ingiallente.','entrambi farinosi ; cingulatum più mite.','cingulatum sotto i salici (spesso umido/bosco golenale), più raramente betulle ; scalpturatum ampiamente in bosco di latifoglie/misto/conifere e popolamenti di parchi.','Entrambi bianchi - non un carattere distintivo.','Un anello netto al gambo E un legame con salice/betulla depongono per cingulatum ; se l''anello manca e la carne ingiallisce, non toccare. Nei Tricholoma terrei grigi in generale, massima prudenza (Tricholoma pardinum mortale, simile).','{"T. cingulatum (commestibile) : possiede un ANELLO/zona di velo membranoso netto al gambo - scalpturatum è senza anello. L''anello è il carattere distintivo più importante rispetto a tutti gli altri Tricholoma terrei.","T. scalpturatum (sospetto di tossicità/scadente, NON raccogliere) : nessun anello, lamelle e carne ingialliscono nettamente.","cingulatum vive in micorriza con i salici (Salix), più raramente le betulle (Betula) - spesso in stazioni umide/golenali.","Odore di entrambi farinoso ; cingulatum mite.","Zona d''anello presente + legame salice/betulla = cingulatum ; senza anello + ingiallente = scalpturatum."}',false),
('tricholoma_columbetta','tricholoma_scalpturatum','en','columbetta pure white and silky without yellowing; scalpturatum grey-brown and yellowing.','columbetta almost odourless/mild, scalpturatum mealy.','columbetta prefers deciduous forest (beech, oak) on richer soils; scalpturatum in deciduous/mixed/coniferous forest and parks.','Both white spore print - not a distinguishing feature.','Colour and yellowing reaction are decisive: never dismiss a grey, yellowing knight as a white knight. Pure white knights are in turn confusable with poisonous white funnels/fibrecaps - only collect with identification certainty.','{"T. columbetta (edible): pure white, silky-glossy, gills and flesh do NOT yellow (at most spot-wise blue-/pinkish-greenish on the stem).","T. scalpturatum (suspected toxic/inferior, do NOT collect): grey to grey-brown, yellows distinctly on gills and flesh.","Smell: columbetta almost odourless to faintly mushroomy-mild, scalpturatum mealy.","columbetta has firm, white, non-discolouring flesh; in scalpturatum yellowish discolouration on the cut or when scratched.","Cap colour as a quick test: pure white = check towards columbetta, grey/yellowing = earth knight suspected toxic."}',false),
('tricholoma_columbetta','tricholoma_scalpturatum','es','columbetta de un blanco puro y sedoso sin amarilleo; scalpturatum gris-pardo y amarilleante.','columbetta casi inodoro/suave, scalpturatum harinoso.','columbetta prefiere el bosque de frondosas (haya, roble) sobre suelos mejores; scalpturatum en bosque de frondosas/mixto/coníferas y parques.','Ambos con esporada blanca - no es un criterio distintivo.','El color y la reacción de amarilleo son decisivos: nunca tomar un Tricholoma gris amarilleante por un Tricholoma blanco. Los Tricholoma de un blanco puro son a su vez confundibles con clitocibes/inocibes blancos tóxicos - recoger solo con certeza de determinación.','{"T. columbetta (comestible): de un blanco puro, sedoso-brillante, láminas y carne NO amarillean (a lo sumo puntualmente azul-/rosa-verdoso en el pie).","T. scalpturatum (sospechoso de toxicidad/inferior, NO recoger): gris hasta gris-pardo, amarillea netamente en las láminas y la carne.","Olor: columbetta casi inodoro hasta débilmente a hongo-suave, scalpturatum harinoso.","columbetta tiene carne firme, blanca, no virante; en scalpturatum coloración amarillenta al corte o al rascar.","Color del sombrero como prueba rápida: blanco puro = verificar hacia columbetta, gris/amarilleante = Tricholoma terroso sospechoso de toxicidad."}',false),
('tricholoma_columbetta','tricholoma_scalpturatum','fr','columbetta d''un blanc pur et soyeux sans jaunissement ; scalpturatum gris-brun et jaunissant.','columbetta quasiment inodore/doux, scalpturatum farineux.','columbetta préfère la forêt de feuillus (hêtre, chêne) sur sols plus riches ; scalpturatum en forêt de feuillus/mixte/conifères et parcs.','Tous deux à sporée blanche - pas un critère de distinction.','La couleur et la réaction de jaunissement sont décisives : ne jamais prendre un tricholome gris jaunissant pour un tricholome blanc. Les tricholomes d''un blanc pur sont à leur tour confondables avec des clitocybes/inocybes blancs toxiques - ne cueillir qu''avec une certitude de détermination.','{"T. columbetta (comestible) : d''un blanc pur, soyeux-luisant, lames et chair ne jaunissent PAS (tout au plus ponctuellement bleu-/rose-verdâtre au pied).","T. scalpturatum (suspect de toxicité/médiocre, NE PAS cueillir) : gris à gris-brun, jaunit nettement aux lames et à la chair.","Odeur : columbetta quasiment inodore à faiblement champignon-doux, scalpturatum farineux.","columbetta a une chair ferme, blanche, non décolorante ; chez scalpturatum coloration jaunâtre à la coupe ou au grattage.","Couleur du chapeau comme test rapide : blanc pur = vérifier vers columbetta, gris/jaunissant = tricholome terreux suspect de toxicité."}',false),
('tricholoma_columbetta','tricholoma_scalpturatum','it','columbetta di un bianco puro e setoso senza ingiallimento ; scalpturatum grigio-bruno e ingiallente.','columbetta quasi inodore/mite, scalpturatum farinoso.','columbetta predilige il bosco di latifoglie (faggio, quercia) su suoli migliori ; scalpturatum in bosco di latifoglie/misto/conifere e parchi.','Entrambi con sporata bianca - non un carattere distintivo.','Il colore e la reazione di ingiallimento sono decisivi : non scambiare mai un Tricholoma grigio ingiallente per un Tricholoma bianco. I Tricholoma di un bianco puro sono a loro volta confondibili con clitocybe/inocybe bianchi tossici - raccogliere solo con certezza di determinazione.','{"T. columbetta (commestibile) : di un bianco puro, setoso-lucente, lamelle e carne NON ingialliscono (tutt''al più puntualmente blu-/rosa-verdastro sul gambo).","T. scalpturatum (sospetto di tossicità/scadente, NON raccogliere) : grigio fino a grigio-bruno, ingiallisce nettamente alle lamelle e alla carne.","Odore : columbetta quasi inodore fino a debolmente fungino-mite, scalpturatum farinoso.","columbetta ha carne soda, bianca, non virante ; in scalpturatum colorazione giallastra al taglio ovvero al grattamento.","Colore del cappello come test rapido : bianco puro = verificare verso columbetta, grigio/ingiallente = Tricholoma terreo sospetto di tossicità."}',false),
('tricholoma_portentosum','tricholoma_scalpturatum','en','T. portentosum shows black radial fibres on a grey cap without yellowing; T. scalpturatum yellows on the gills and cut surface when scratched/pressed.','portentosum mild and pleasantly mealy-cucumbery, scalpturatum obtrusively mealy.','portentosum in late autumn under conifers (pine/spruce) on acidic soil, scalpturatum from May to November in deciduous/mixed/coniferous forest, parks and gardens.','Both white spore print - the spore print does NOT distinguish here; use exclusively yellowing (scalpturatum) + cap colour + season.','Any grey-brown earth knight whose gills or cut surface yellow is NOT an edible mushroom - when in doubt, leave it. Grey earth knights in general only with absolute identification certainty; several poisonous to deadly species (e.g. Tricholoma pardinum) look similar.','{"T. portentosum (edible): cap grey-brown with distinctly black-fibrous radial markings, often a violet-/yellowish sheen; flesh and gills do NOT yellow.","T. scalpturatum (suspected toxic/inferior, do NOT collect): gills and flesh yellow distinctly (yellowish spots on pressure, on scratching or with age) - central distinguishing feature.","Smell: portentosum mild to faintly mealy-cucumbery, pleasant; scalpturatum distinctly mealy.","portentosum typically grows late in the year (late autumn/frost) under pine/spruce; scalpturatum from May to November in deciduous/mixed and coniferous forest, parks, gardens.","Cap surface portentosum slimy-glossy when moist, scalpturatum dry-finely scaly/with ingrown fibres."}',false),
('tricholoma_portentosum','tricholoma_scalpturatum','es','T. portentosum muestra fibras radiales negras sobre un sombrero gris sin amarilleo; T. scalpturatum amarillea en las láminas y la superficie de corte al rascar/presionar.','portentosum suave y agradablemente harinoso-pepino, scalpturatum harinoso invasivo.','portentosum a finales de otoño bajo coníferas (pino/abeto rojo) en suelo ácido, scalpturatum de mayo a noviembre en bosque de frondosas/mixto/coníferas, parques y jardines.','Ambos con esporada blanca - la esporada aquí NO distingue; usar exclusivamente el amarilleo (scalpturatum) + el color del sombrero + la temporada.','Todo Tricholoma terroso gris-pardo cuyas láminas o superficie de corte amarillean NO es un hongo comestible - en la duda, dejar en el sitio. Los Tricholoma terrosos grises en general solo con certeza de determinación absoluta; varias especies tóxicas hasta mortales (p. ej. Tricholoma pardinum) se parecen.','{"T. portentosum (comestible): sombrero gris-pardo con diseño radial netamente negro-fibroso, a menudo reflejo violáceo/amarillento; carne y láminas NO amarillean.","T. scalpturatum (sospechoso de toxicidad/inferior, NO recoger): láminas y carne amarillean netamente (manchas amarillentas a la presión, al rascar o con la edad) - carácter distintivo central.","Olor: portentosum suave hasta débilmente harinoso-pepino, agradable; scalpturatum netamente harinoso.","portentosum crece típicamente tarde en el año (finales de otoño/helada) bajo pino/abeto rojo; scalpturatum de mayo a noviembre en bosque de frondosas/mixto y coníferas, parques, jardines.","Superficie del sombrero portentosum viscoso-brillante con tiempo húmedo, scalpturatum seco-finamente escamoso/con fibras incrustadas."}',false),
('tricholoma_portentosum','tricholoma_scalpturatum','fr','T. portentosum montre des fibres radiales noires sur un chapeau gris sans jaunissement ; T. scalpturatum jaunit aux lames et à la surface de coupe au grattage/à la pression.','portentosum doux et agréablement farineux-concombre, scalpturatum farineux envahissant.','portentosum en fin d''automne sous conifères (pin/épicéa) sur sol acide, scalpturatum de mai à novembre en forêt de feuillus/mixte/conifères, parcs et jardins.','Tous deux à sporée blanche - la sporée ne distingue PAS ici ; utiliser exclusivement le jaunissement (scalpturatum) + la couleur du chapeau + la saison.','Tout tricholome terreux gris-brun dont les lames ou la surface de coupe jaunissent n''est PAS un champignon comestible - dans le doute, laisser sur place. Les tricholomes terreux gris ne se cueillent en général qu''avec une certitude de détermination absolue ; plusieurs espèces toxiques à mortelles (p. ex. Tricholoma pardinum) se ressemblent.','{"T. portentosum (comestible) : chapeau gris-brun à motif radial nettement noir-fibreux, souvent reflet violacé/jaunâtre ; chair et lames ne jaunissent PAS.","T. scalpturatum (suspect de toxicité/médiocre, NE PAS cueillir) : lames et chair jaunissent nettement (taches jaunâtres à la pression, au grattage ou avec l''âge) - critère de distinction central.","Odeur : portentosum doux à faiblement farineux-concombre, agréable ; scalpturatum nettement farineux.","portentosum pousse typiquement tard dans l''année (fin d''automne/gel) sous pin/épicéa ; scalpturatum de mai à novembre en forêt de feuillus/mixte et conifères, parcs, jardins.","Surface du chapeau portentosum visqueuse-luisante par temps humide, scalpturatum sèche-finement écailleuse/à fibres incrustées."}',false),
('tricholoma_portentosum','tricholoma_scalpturatum','it','T. portentosum mostra fibre radiali nere su cappello grigio senza ingiallimento ; T. scalpturatum ingiallisce alle lamelle e alla superficie di taglio al grattamento/alla pressione.','portentosum mite e gradevolmente farinoso-cetriolo, scalpturatum farinoso invadente.','portentosum a tardo autunno sotto conifere (pino/abete rosso) su suolo acido, scalpturatum da maggio a novembre in bosco di latifoglie/misto/conifere, parchi e giardini.','Entrambi con sporata bianca - la sporata qui NON distingue ; usare esclusivamente l''ingiallimento (scalpturatum) + il colore del cappello + la stagione.','Ogni Tricholoma terreo grigio-bruno le cui lamelle o superficie di taglio ingialliscono NON è un fungo commestibile - nel dubbio, lasciare sul posto. I Tricholoma terrei grigi si raccolgono in generale solo con assoluta certezza di determinazione ; più specie tossiche fino a mortali (es. Tricholoma pardinum) si somigliano.','{"T. portentosum (commestibile) : cappello grigio-bruno con disegno radiale nettamente nero-fibroso, spesso riflesso violaceo/giallastro ; carne e lamelle NON ingialliscono.","T. scalpturatum (sospetto di tossicità/scadente, NON raccogliere) : lamelle e carne ingialliscono nettamente (macchie giallastre alla pressione, al grattamento o con l''età) - carattere distintivo centrale.","Odore : portentosum mite fino a debolmente farinoso-cetriolo, gradevole ; scalpturatum nettamente farinoso.","portentosum cresce tipicamente tardi nell''anno (tardo autunno/gelo) sotto pino/abete rosso ; scalpturatum da maggio a novembre in bosco di latifoglie/misto e conifere, parchi, giardini.","Superficie del cappello portentosum vischioso-lucente con tempo umido, scalpturatum asciutto-finemente squamoso/a fibre incrostate."}',false),
('tricholoma_portentosum','tricholoma_ustale','en','ustale uniformly red-brown and slimy with gills becoming rust-spotted; portentosum grey with black radial fibrils.','ustale faintly mealy, portentosum mild mealy-cucumbery - smell here distinguishes only weakly, colour decides.','ustale in deciduous forest (beech preferred, also oak); portentosum under pine/spruce on acidic soil in late autumn.','Both white spore print - not a distinguishing feature.','Red-brown, slimy cap with rust-spotted gills and a bitter taste = poisonous burnt knight (Tricholoma ustale), do not collect.','{"T. ustale (poisonous): cap red-brown to chestnut-brown, slimy-mucilaginous when moist; gills quickly become rust-spotted; flesh browns, taste somewhat bitter.","T. portentosum (edible): cap grey with black radial fibres (not red-brown), gills grey-whitish, often tinged yellowish, without rust spots.","Raw taste: ustale unpleasantly bitter, portentosum mild - the taste test (chew, do NOT swallow, spit out) helps but is not a sole criterion.","Season/site: portentosum mainly late autumn until frost under conifers; ustale from high summer to late autumn predominantly in deciduous forest (beech/oak).","ustale stains the flesh brownish, portentosum hardly discolours."}',false),
('tricholoma_portentosum','tricholoma_ustale','es','ustale unicolor pardo-rojo y viscoso con láminas que se manchan de herrumbre; portentosum gris con fibrillas radiales negras.','ustale débilmente harinoso, portentosum suave harinoso-pepino - el olor aquí distingue solo débilmente, el color decide.','ustale en bosque de frondosas (haya preferida, también roble); portentosum bajo pino/abeto rojo en suelo ácido a finales de otoño.','Ambos con esporada blanca - no es un criterio distintivo.','Sombrero pardo-rojo, viscoso, con láminas manchadas de herrumbre y sabor amargo = Tricholoma ustale tóxico, no recoger.','{"T. ustale (tóxico): sombrero pardo-rojo a pardo-castaño, viscoso-mucilaginoso con tiempo húmedo; láminas que se manchan rápidamente de herrumbre; carne que pardea, sabor amarguento.","T. portentosum (comestible): sombrero gris con fibras radiales negras (no pardo-rojo), láminas gris-blanquecinas, a menudo teñidas de amarillento, sin manchas de herrumbre.","Sabor crudo: ustale desagradablemente amargo, portentosum suave - la prueba de sabor (masticar, NO tragar, escupir) ayuda, pero no es un criterio único.","Temporada/estación: portentosum sobre todo finales de otoño hasta la helada bajo coníferas; ustale de pleno verano a finales de otoño predominantemente en bosque de frondosas (haya/roble).","ustale colorea la carne de pardusco, portentosum apenas vira."}',false),
('tricholoma_portentosum','tricholoma_ustale','fr','ustale unicolore brun-rouge et visqueux avec des lames se tachant de rouille ; portentosum gris à fibrilles radiales noires.','ustale faiblement farineux, portentosum doux farineux-concombre - l''odeur ne distingue ici que faiblement, la couleur décide.','ustale en forêt de feuillus (hêtre de préférence, aussi chêne) ; portentosum sous pin/épicéa sur sol acide en fin d''automne.','Tous deux à sporée blanche - pas un critère de distinction.','Chapeau brun-rouge, visqueux, à lames tachées de rouille et goût amer = tricholome brûlant toxique, ne pas cueillir.','{"T. ustale (toxique) : chapeau brun-rouge à brun-châtain, visqueux-gluant par temps humide ; lames se tachant rapidement de rouille ; chair brunissant, goût amarescent.","T. portentosum (comestible) : chapeau gris à fibres radiales noires (non brun-rouge), lames gris-blanchâtre, souvent teintées de jaunâtre, sans taches de rouille.","Goût cru : ustale désagréablement amer, portentosum doux - la prise de goût (mâcher, NE PAS avaler, recracher) aide, mais n''est pas un critère unique.","Saison/station : portentosum surtout fin d''automne jusqu''au gel sous conifères ; ustale du plein été à la fin de l''automne, principalement en forêt de feuillus (hêtre/chêne).","ustale colore la chair en brunâtre, portentosum ne se décolore guère."}',false),
('tricholoma_portentosum','tricholoma_ustale','it','ustale unicolore bruno-rosso e vischioso con lamelle che si macchiano di ruggine ; portentosum grigio con fibrille radiali nere.','ustale debolmente farinoso, portentosum mite farinoso-cetriolo - l''odore qui distingue solo debolmente, il colore decide.','ustale nel bosco di latifoglie (faggio preferito, anche quercia) ; portentosum sotto pino/abete rosso su suolo acido a fine autunno.','Entrambi con sporata bianca - non un carattere distintivo.','Cappello bruno-rosso, vischioso, con lamelle macchiate di ruggine e sapore amaro = Tricholoma ustale tossico, non raccogliere.','{"T. ustale (tossico) : cappello bruno-rosso a bruno-castano, vischioso-viscido con tempo umido ; lamelle che si macchiano rapidamente di ruggine ; carne che imbrunisce, sapore amarognolo.","T. portentosum (commestibile) : cappello grigio con fibre radiali nere (non bruno-rosso), lamelle grigio-biancastre, spesso sfumate di giallastro, senza macchie di ruggine.","Sapore crudo : ustale sgradevolmente amaro, portentosum mite - la prova di assaggio (masticare, NON inghiottire, sputare) aiuta, ma non è un criterio unico.","Stagione/stazione : portentosum soprattutto tardo autunno fino al gelo sotto conifere ; ustale da piena estate a tardo autunno, prevalentemente nel bosco di latifoglie (faggio/quercia).","ustale colora la carne di brunastro, portentosum vira appena."}',false),
('zigeunerpilz','cortinarius_semisanguineus','en','The Gypsy mushroom (Cortinarius caperatus) is large, grey-brown with a frost-like wrinkled cap and a membranous ring; C. semisanguineus is small, olive-brown with blood-red gills and no true ring.','Gypsy mushroom mild and pleasant; C. semisanguineus odourless to faintly radish-like.','Both grow in acidic coniferous/mixed forests, often near blueberry; therefore the gill colour is the decisive distinguishing feature, not the habitat.','Both have a rust-brown spore print – the spore print does NOT distinguish them; decisive are the blood-red gills (semisanguineus, poisonous) versus ochre gills and a membranous ring (caperatus, edible).','Check the gills: any trace of blood-red = webcap (Dermocybe) = leave it. The Gypsy mushroom is the ONLY recommended edible webcap (Cortinarius) – when in doubt, EVERY Cortinarius must be discarded uneaten.','{"C. semisanguineus has bright blood-red gills when young – a clear warning sign; the edible Gypsy mushroom (C. caperatus) has pale ochre-toned gills, NEVER red.","Cap: C. caperatus grey-brown ochre with a silvery, wrinkled ''frost-like'' coating at the crown; C. semisanguineus olive-ochre to umber-brown, smooth-fibrillose.","C. caperatus has a membranous ring on the stem; C. semisanguineus only has fleeting cortina remnants, no true ring.","Both webcaps (Cortinarius) have a rust-brown spore print – here the gill colour and the ring are the key.","Size: C. caperatus sturdy (cap 5–10 cm); C. semisanguineus small and slender (cap 2–5 cm)."}',false),
('zigeunerpilz','cortinarius_semisanguineus','es','El cortinario gitano (Cortinarius caperatus) es grande, gris-pardo con un sombrero arrugado como escarchado y un anillo membranoso; C. semisanguineus es pequeño, pardo oliváceo con láminas rojo sangre y sin un verdadero anillo.','Cortinario gitano olor suave y agradable; C. semisanguineus inodoro o débilmente rafanoide (olor a rábano).','Ambos crecen en bosques ácidos de coníferas/mixtos, a menudo junto al arándano; por eso el color de las láminas es el rasgo distintivo decisivo, no el hábitat.','Ambos tienen esporada pardo-herrumbre – la esporada NO los distingue; lo decisivo son las láminas rojo sangre (semisanguineus, venenoso) frente a láminas ocre y un anillo membranoso (caperatus, comestible).','Controlar las láminas: cualquier rastro de rojo sangre = cortinario (Dermocybe) = dejarlo. El cortinario gitano es el ÚNICO cortinario comestible recomendado – en caso de duda, TODO Cortinarius debe desecharse sin consumir.','{"C. semisanguineus tiene de joven láminas de un rojo sangre brillante – una clara señal de alarma; el comestible cortinario gitano (C. caperatus) tiene láminas de tono ocre pálido, NUNCA rojas.","Sombrero: C. caperatus gris-pardo ocre con un recubrimiento plateado y arrugado «como escarchado» en el ápice; C. semisanguineus de pardo ocre oliváceo a pardo umbra, liso-fibrilloso.","C. caperatus tiene un anillo membranoso en el pie; C. semisanguineus solo presenta fugaces restos de cortina, ningún verdadero anillo.","Ambos cortinarios con esporada pardo-herrumbre – aquí el color de las láminas y el anillo son la clave.","Tamaño: C. caperatus robusto (sombrero 5–10 cm); C. semisanguineus pequeño y grácil (sombrero 2–5 cm)."}',false),
('zigeunerpilz','cortinarius_semisanguineus','fr','Rozite ridée grande, gris-brun avec un chapeau pruineux-ridé et un anneau membraneux ; C. semisanguineus petit, brun-olive avec des lamelles rouge sang sans véritable anneau.','Rozite ridée douce-agréable ; C. semisanguineus inodore à faiblement de radis.','Les deux dans les forêts de conifères/mixtes acides, souvent près de la myrtille ; c''est pourquoi la couleur des lamelles est le critère de séparation décisif, pas la station.','Les deux brun rouille – la sporée ne sépare PAS ; décisives sont les lamelles rouge sang (semisanguineus, toxique) vs. ocre et anneau membraneux (caperatus, comestible).','Contrôler les lamelles : toute trace de rouge sang = cortinaire = laisser sur place. La rozite ridée est le SEUL cortinaire comestible recommandé – en cas de doute, TOUT cortinaire doit être jeté non mangé.','{"C. semisanguineus a jeune des lamelles rouge sang éclatant – un signal d''alarme clair ; la rozite ridée comestible (C. caperatus) a des lamelles ocre-pâle, JAMAIS rouges.","Chapeau : C. caperatus gris-brun-ocre avec un revêtement « pruineux » argenté-ridé au sommet ; C. semisanguineus ocre-olive à brun ombré, lisse-fibrilleux.","C. caperatus a un anneau membraneux au pied ; C. semisanguineus seulement des restes fugaces de cortine, pas de véritable anneau.","Les deux cortinaires à sporée brun rouille – la couleur des lamelles et l''anneau sont ici les clés.","Taille : C. caperatus robuste (chapeau 5–10 cm) ; C. semisanguineus petit-gracile (chapeau 2–5 cm)."}',false),
('zigeunerpilz','cortinarius_semisanguineus','it','La rossola grinzosa (Cortinarius caperatus) è grande, grigio-bruna con cappello grinzoso come brinato e anello membranoso; C. semisanguineus è piccolo, bruno olivastro con lamelle rosso sangue senza un vero anello.','Rossola grinzosa odore mite e gradevole; C. semisanguineus inodore o debolmente rafanoide (odore di ravanello).','Entrambi crescono in boschi acidi di conifere/misti, spesso presso il mirtillo; perciò è il colore delle lamelle il carattere distintivo decisivo, non l''habitat.','Entrambi hanno sporata bruno-ruggine – la sporata NON li distingue; decisive sono le lamelle rosso sangue (semisanguineus, velenoso) contro lamelle ocra e anello membranoso (caperatus, commestibile).','Controllare le lamelle: ogni minima traccia di rosso sangue = Cortinario (Dermocybe) = lasciare sul posto. La rossola grinzosa è l''UNICO cortinario commestibile raccomandato – nel dubbio, OGNI Cortinarius va gettato senza essere consumato.','{"C. semisanguineus ha da giovane lamelle di un rosso sangue brillante – un chiaro segnale d''allarme; la commestibile rossola grinzosa (C. caperatus) ha lamelle di tonalità ocra pallida, MAI rosse.","Cappello: C. caperatus grigio-bruno ocra con rivestimento argenteo e grinzoso «come brinato» al centro; C. semisanguineus da bruno ocra olivastro a bruno ombra, liscio-fibrilloso.","C. caperatus ha un anello membranoso sul gambo; C. semisanguineus presenta solo fugaci resti di cortina, nessun vero anello.","Entrambi i Cortinari con sporata bruno-ruggine – qui il colore delle lamelle e l''anello sono la chiave.","Dimensione: C. caperatus robusto (cappello 5–10 cm); C. semisanguineus piccolo e gracile (cappello 2–5 cm)."}',false)
